# ══════════════════════════════════════════════════════════════════════════════
# ANTI-DOUBLE-CLICK RACE CONDITION PROTECTION (FIX FOR "DASHBOARD IS STILL ACTIVE")
# ══════════════════════════════════════════════════════════════════════════════
# Prevents the error: "This action could not be completed. Your dashboard is still active."
# This happens when users rapidly click buttons - the cooldown prevents race conditions.
_admin_active_operations = {}  # {user_id: timestamp}
_admin_operation_cooldown = 0.5  # seconds between operations - ADJUST IF NEEDED

import time

def is_admin_dashboard_busy(user_id: int) -> bool:
    """Check if admin is already performing an action (within cooldown)."""
    if user_id not in _admin_active_operations:
        return False
    last_action = _admin_active_operations[user_id]
    return (time.time() - last_action) < _admin_operation_cooldown

def mark_admin_busy(user_id: int):
    """Mark admin as performing an action."""
    _admin_active_operations[user_id] = time.time()

def mark_admin_free(user_id: int):
    """Mark admin as free (reset cooldown)."""
    _admin_active_operations[user_id] = time.time() - _admin_operation_cooldown


