def _protected_callback(func):
    """
    ANTI-DOUBLE-CLICK DECORATOR
    Wraps callback handlers to prevent rapid repeated button clicks.
    If user clicks while processing, they get a "Please wait..." message instead of error.
    """
    async def wrapper(update: Update, ctx: ContextTypes.DEFAULT_TYPE, *args, **kwargs):
        if not update.effective_user:
            return
        
        user_id = update.effective_user.id
        
        # Check if already processing
        if is_admin_dashboard_busy(user_id):
            q = update.callback_query
            if q:
                try:
                    await q.answer("⏳ Processing... Please wait for the previous action to complete.", show_alert=False)
                except Exception:
                    pass
            return
        
        # Mark as busy
        mark_admin_busy(user_id)
        
        try:
            # Execute the actual callback function
            result = await func(update, ctx, *args, **kwargs)
            return result
        except Exception as e:
            logger.error(f"Error in protected callback {func.__name__}: {e}")
            # Mark as free on error
            mark_admin_free(user_id)
            raise
        finally:
            # Always mark as free after execution
            mark_admin_free(user_id)
    
    # Preserve function name for debugging
    wrapper.__name__ = func.__name__
    return wrapper


def _clean_admin_label(text: str) -> str:
    value = re.sub(r"emoji_\d+", "", str(text or ""))
    value = value.replace("[RUNNING]", "").strip()
    # Remove a leading Unicode icon when we are going to render the icon
    # separately (custom icon mode), or when the label is being normalized.
    value = re.sub(r"^[\s\u2600-\u27BF\U0001F000-\U0001FAFF]+\s*", "", value)
    return value.strip()


def _admin_button_text(text: str) -> str:
    label = _clean_admin_label(text)
    if ADMIN_USE_CUSTOM_EMOJI and label in ADMIN_CUSTOM_EMOJI_MAP:
        return label
    return f"{BUTTON_EMOJI_MAP.get(label, '📌')} {label}" if label else "Button"


# Universal callback guard: a broken callback never leaves Telegram with a frozen
# button; ConversationHandler return values are preserved.
_OriginalCallbackQueryHandler = CallbackQueryHandler
class _SafeCallbackQueryHandler(_OriginalCallbackQueryHandler):
    def __init__(self, callback, *args, **kwargs):
        async def _guarded(update, ctx):
            try:
                return await callback(update, ctx)
            except Exception as exc:
                uid = getattr(getattr(update, "effective_user", None), "id", None)
                logger.exception("Admin callback %s failed for user %s: %s", getattr(callback, "__name__", "callback"), uid, exc)
                q = getattr(update, "callback_query", None)
                if q is not None:
                    try: await q.answer("⚠️ Action failed — please try again.")
                    except Exception: pass
                    try:
                        await q.message.reply_text("⚠️ *Admin action could not be completed.*\n\nThe dashboard is still active. Tap *Back to Dashboard* and retry.", parse_mode="Markdown", reply_markup=back_kb())
                    except Exception: pass
                return None
        _guarded.__name__ = getattr(callback, "__name__", "callback")
        super().__init__(_guarded, *args, **kwargs)
CallbackQueryHandler = _SafeCallbackQueryHandler


def InlineKeyboardButton(text: str, *args, **kwargs):
    label = _clean_admin_label(text)
    if ADMIN_USE_CUSTOM_EMOJI and label in ADMIN_CUSTOM_EMOJI_MAP:
        # Newer PTB releases support icon_custom_emoji_id. If an older PTB
        # release is installed, transparently fall back to a Unicode button.
        kwargs.setdefault("icon_custom_emoji_id", ADMIN_CUSTOM_EMOJI_MAP[label])
    if "style" not in kwargs:
        label_cf = label.casefold()
        if any(word in label_cf for word in (
            "back", "cancel", "preview", "stats", "settings", "history",
            "search", "all users", "linked users", "analytics", "howto",
        )):
            kwargs["style"] = "primary"
        else:
            kwargs["style"] = "success"
    try:
        return _TelegramInlineKeyboardButton(_admin_button_text(text), *args, **kwargs)
    except TypeError as exc:
        if "icon_custom_emoji_id" not in str(exc):
            raise
        kwargs.pop("icon_custom_emoji_id", None)
        return _TelegramInlineKeyboardButton(_admin_button_text(text), *args, **kwargs)


