def _set_admin_emoji_context(user, enabled=None) -> None:
    """Set the in-process admin button emoji mode."""
    global ADMIN_USE_CUSTOM_EMOJI
    if enabled is None:
        enabled = bool(getattr(user, "is_premium", False) and getattr(user, "id", 0) == ADMIN_TG_ID)
    ADMIN_USE_CUSTOM_EMOJI = bool(enabled)


async def _load_admin_emoji_context(user) -> None:
    """Load admin emoji mode and migrate old installs to custom mode once.

    Older builds defaulted to Unicode and could also reset the mode after a
    generic Telegram BadRequest.  That left premium button icons disabled even
    when the primary admin had Telegram Premium.  One-time migration enables
    custom icons for the primary Premium admin; the normal Unicode/Custom
    setting remains user-controllable after migration.
    """
    premium = bool(getattr(user, "is_premium", False) and getattr(user, "id", 0) == ADMIN_TG_ID)
    migrated = await db.get_setting("admin_emoji_autofix_v1", "0")
    mode = await db.get_setting("admin_emoji_mode", "unicode")
    if premium and migrated != "1":
        await db.set_setting("admin_emoji_mode", "custom")
        await db.set_setting("admin_emoji_autofix_v1", "1")
        mode = "custom"
    _set_admin_emoji_context(user, enabled=(mode == "custom" and premium))


