async def cb_play_win_event(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not await admin_only(update):
        try: await q.answer()
        except Exception: pass
        return
    await q.answer()
    enabled = (await db.get_setting("play_win_event_enabled", "0")) == "1"
    text = (
        "🎮 *PLAY & WIN EVENT*\n\n"
        f"Status: *{'🟢 ON' if enabled else '🔴 OFF'}*\n\n"
        "When ON, users see *🎮 Play & Win* immediately above the Terms / Support row.\n\n"
        "🎡 Wheel: Better Luck 90%; 1d 3%, 3d 2.5%, 7d 2%, 15d 1.5%, 100d 1%.\n"
        "🎲 Dice: 3d 80%, 7d 70%, 15d 60%, 50d 45%, 100d 30%, Better Luck fallback.\n\n"
        "⏳ Each game has a 24-hour cooldown.\n"
        "👑 Primary admin always receives 100 days on either game."
    )
    await q.message.edit_text(text, parse_mode="Markdown", reply_markup=_play_win_admin_kb(enabled))


async def cb_play_win_toggle(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not await admin_only(update):
        try: await q.answer()
        except Exception: pass
        return
    current = (await db.get_setting("play_win_event_enabled", "0")) == "1"
    new_value = "0" if current else "1"
    await db.set_setting("play_win_event_enabled", new_value)
    await q.answer("Event started" if new_value == "1" else "Event stopped")
    enabled = new_value == "1"
    text = (
        "🎮 *PLAY & WIN EVENT*\n\n"
        f"Status: *{'🟢 ON' if enabled else '🔴 OFF'}*\n\n"
        + ("Users can now access Play & Win." if enabled else "Play & Win is now hidden from the User Bot.")
    )
    await q.message.edit_text(text, parse_mode="Markdown", reply_markup=_play_win_admin_kb(enabled))


