async def cb_back(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    _set_admin_emoji_context(q.from_user)
    try:
        await q.answer()
    except Exception:
        pass
    uid = update.effective_user.id if update.effective_user else 0
    # Agent screens also use ``a_back``.  Never show an admin dashboard to an
    # agent (or to an arbitrary user who somehow obtains an old callback).
    if not (is_primary_admin(uid) or await db.is_extra_admin(uid)):
        if uid and await db.is_agent(uid):
            await _show_agent_panel(q.message, uid)
        else:
            try:
                await q.message.reply_text("❌ Unauthorised access.")
            except Exception:
                pass
        return
    dash = await _build_dashboard()
    is_primary = is_primary_admin(uid)
    try:
        await q.message.edit_text(
            dash, parse_mode="Markdown", reply_markup=admin_menu_kb(is_primary=is_primary))
    except Exception:
        await q.message.reply_text(
            dash, parse_mode="Markdown", reply_markup=admin_menu_kb(is_primary=is_primary))


