def _cyob_kb(current_status: str) -> InlineKeyboardMarkup:
    """Keyboard for the CYOB setting panel."""
    on_label  = "🎯 ON  ✅" if current_status == "1" else "🎯 ON"
    off_label = "🎯 OFF ✅" if current_status == "0" else "🎯 OFF"
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(on_label,  callback_data="a_cyob_on"),
         InlineKeyboardButton(off_label, callback_data="a_cyob_off")],
        [InlineKeyboardButton("🔙 Back to Dashboard", callback_data="a_back")],
    ])


async def cb_cyob_setting(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Ask for password before allowing access to CYOB settings."""
    q = update.callback_query
    try:
        await q.answer()
    except Exception:
        pass
    if not await admin_only(update):
        return
    
    text = (
        f"👑 *Password Required*\n\n"
        f"This is a private feature for the bot. If you want to access or manage it, "
        f"you have to tell me the password.\n\n"
        f"Write the password in the correct form."
    )
    try:
        await q.message.edit_text(text, parse_mode="Markdown", 
                                  reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Cancel", callback_data="a_back")]]))
    except Exception:
        await q.message.reply_text(text, parse_mode="Markdown",
                                   reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Cancel", callback_data="a_back")]]))
    
    return CYOB_PASSWORD_INPUT


async def handle_cyob_password(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Handle CYOB password input and verification."""
    if not await admin_only(update):
        return
    
    user_input = update.message.text.strip()
    
    # Verify password
    if verify_cyob_password(user_input):
        # Password correct - show the ON/OFF buttons
        current = await db.get_setting("cyob_enabled", "1")
        status_label = "🎯 *ON*  — Button is visible to users" if current != "0" \
            else "🎯 *OFF* — Button is hidden from users"
        text = (
            f"🤖 *Create Your Own Bot — Visibility Setting*\n\n"
            f"─────────────────────\n"
            f"Current Status: {status_label}\n"
            f"─────────────────────\n\n"
            f"✅ *Password verified successfully!*\n\n"
            f"• Tap 🎯 *ON* to show the *Create Your Own Bot* button in the User Bot.\n"
            f"• Tap 🎯 *OFF* to completely hide it from all users.\n\n"
            f"The change takes effect immediately."
        )
        await update.message.reply_text(text, parse_mode="Markdown", reply_markup=_cyob_kb(current))
        return ConversationHandler.END
    else:
        # Wrong password
        text = (
            f"✨ *Incorrect Password*\n\n"
            f"The password is wrong.\n\n"
            f"Try again or contact creator of the bot."
        )
        await update.message.reply_text(text, parse_mode="Markdown",
                                        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Cancel", callback_data="a_back")]]))
        return CYOB_PASSWORD_INPUT


