async def _verify_force_join_chat(bot, chat_id: int):
    """Check that the chat exists and that the bot is an admin with invite rights there."""
    try:
        chat = await bot.get_chat(chat_id)
    except Exception:
        return False, ("❌ The bot cannot access a chat with this ID. Check the ID, and make sure the bot "
                       "is added to the channel as an administrator."), ""
    title = getattr(chat, "title", None) or str(chat_id)
    try:
        me = await bot.get_me()
        member = await bot.get_chat_member(chat_id, me.id)
    except Exception:
        return False, ("❌ Could not check the bot's rights in this channel. Make the bot an administrator, "
                       "then send the chat ID again."), title
    status = str(getattr(member, "status", "")).lower()
    if status not in {"administrator", "creator"}:
        return False, ("❌ The bot is not an administrator in this channel. Make the bot an administrator, "
                       "then send the chat ID again."), title
    if status == "administrator" and not getattr(member, "can_invite_users", False):
        return False, ("❌ The bot needs the 'Invite Users via Link' permission to approve join requests. "
                       "Enable it, then send the chat ID again."), title
    return True, "", title


async def handle_channel_add(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Add Force Join channel. Private channels: chat ID first (verified), then the invite link.
    Public channels: username as before."""
    import re
    if not await admin_only(update): return ConversationHandler.END
    raw=(update.message.text or "").strip()
    if not raw: return EDIT_CHANNEL_ADD_INPUT
    try:
        awaiting_link = ctx.user_data.get("fj_chat_id")
        if awaiting_link is not None:
            if not db._is_private_channel_link(raw):
                await update.message.reply_text("Please send the channel's invite link (https://t.me/+...).")
                return EDIT_CHANNEL_ADD_INPUT
            link = db.normalize_channel_input(raw)
            channels = await db.add_force_join_channel(link)
            await db.set_force_join_chat_id(link, int(awaiting_link))
            ctx.user_data.pop("fj_chat_id", None)
            await update.message.reply_text(
                "✅ *Channel added successfully!*\n\n"
                + "\n".join(f"• {_channel_display_label(c)}" for c in channels)
                + "\n\nTap *Add Channel* to add another channel.",
                parse_mode="Markdown", reply_markup=channels_menu_kb())
            return ConversationHandler.END
        if re.fullmatch(r"-?\d{5,}", raw):
            chat_id = int(raw)
            ok, reason, title = await _verify_force_join_chat(ctx.bot, chat_id)
            if not ok:
                await update.message.reply_text(reason, reply_markup=channels_menu_kb())
                return EDIT_CHANNEL_ADD_INPUT
            ctx.user_data["fj_chat_id"] = chat_id
            await update.message.reply_text(
                f"✅ *Channel verified:* {title}\n\nNow send the channel's invite link (https://t.me/+...).",
                parse_mode="Markdown")
            return EDIT_CHANNEL_ADD_INPUT
        if db._is_private_channel_link(raw):
            await update.message.reply_text(
                "Please send the channel's chat ID first (it starts with -100). "
                "Make the bot an administrator in the channel before sending it.")
            return EDIT_CHANNEL_ADD_INPUT
        channel=db.normalize_channel_input(raw)
        channels=await db.add_force_join_channel(channel)
        await update.message.reply_text(
            "✅ *Channel added successfully!*\n\n"
            + "\n".join(f"• {_channel_display_label(c)}" for c in channels)
            + "\n\nTap *Add Channel* to add another channel.",
            parse_mode="Markdown", reply_markup=channels_menu_kb())
    except Exception as exc:
        logger.exception("force join channel add failed: %s",exc)
        await update.message.reply_text(
            "❌ Could not add this channel. Check the input and try again.",
            reply_markup=channels_menu_kb())
    return ConversationHandler.END
    raw = update.message.text.strip()
    channel = db.normalize_channel_input(raw)
    channels = await db.add_force_join_channel(channel)
    label = _channel_display_label(channel)
    ch_list = "\n".join(f"  • {_channel_display_label(c)}" for c in channels)
    await update.message.reply_text(
        f"✅ *Added!*\n\n"
        f"Entry: {label}\n\n"
        f"All force-join channels:\n{ch_list}",
        parse_mode="Markdown",
        reply_markup=edit_menu_kb(),
    )
    return ConversationHandler.END


async def cb_channel_remove(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    if not await admin_only(update):
        return
    channels = await db.get_force_join_channels()
    if not channels:
        await q.message.reply_text("No channels to remove.", reply_markup=channels_menu_kb())
        return
    # Use index-based callbacks — private invite links can exceed callback_data limits
    rows = [
        [InlineKeyboardButton(f"👤 {_channel_display_label(c)}", callback_data=f"ae_rmch_{i}")]
        for i, c in enumerate(channels)
    ]
    rows.append([cancel_button("🔙 Cancel", callback_data="ae_channels")])
    await q.message.reply_text(
        "🗑️ *Remove a Channel*\n\nTap the one to remove:",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup(rows),
    )


async def cb_channel_remove_confirm(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    if not await admin_only(update):
        return
    try:
        index = int(q.data.replace("ae_rmch_", ""))
    except (ValueError, TypeError):
        await q.message.reply_text("⚠️️ Invalid selection.", reply_markup=edit_menu_kb())
        return ConversationHandler.END
    # Snapshot name before removing
    channels_before = await db.get_force_join_channels()
    removed_label = _channel_display_label(channels_before[index]) if index < len(channels_before) else "Unknown"
    channels = await db.remove_force_join_channel_by_index(index)
    ch_list = "\n".join(f"  • {_channel_display_label(c)}" for c in channels) or "  None"
    await q.message.reply_text(
        f"✅ *Removed:* {removed_label}\n\n"
        f"Remaining channels:\n{ch_list}",
        parse_mode="Markdown", reply_markup=edit_menu_kb(),
    )


