async def handle_gift_days_text(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Handles gift code days input - now accepts any number 1-999 (999 = lifetime)."""
    if not await can_create_giftcode(update):
        return ConversationHandler.END
    
    try:
        days = int(update.message.text.strip())
        if days < 1 or days > 999:
            raise ValueError
    except (ValueError, TypeError):
        await update.message.reply_text(
            "❌ *Invalid Input*\n\n"
            "Enter a number between 1-999:\n"
            "• 1-99: Days of premium\n"
            "• 999: Lifetime (Unlimited) Premium",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[cancel_button("Cancel", callback_data="a_edit")]]),
        )
        return GIFT_DAYS_INPUT
    
    # Check which flow we're in
    if ctx.user_data.get("gift_code_text"):
        # Code creation flow
        ctx.user_data["gift_days"] = days
        label = "♾️ Lifetime (Unlimited)" if days == 999 else f"{days} day(s)"
        
        await update.message.reply_text(
            f"✅ Duration set: **{label}**\n\n"
            f"**Step 3 of 3 — How many users can redeem this code?**\n\n"
            "Enter a number:\n"
            "`1` = single use | `10` = 10 users | `999` = unlimited users",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[cancel_button("Cancel", callback_data="a_edit")]]),
        )
        return GIFT_MAXUSES_INPUT
    
    elif ctx.user_data.get("gift_target_uid"):
        # Direct gifting flow  
        target_uid = ctx.user_data.pop("gift_target_uid", None)
        
        if days == 999:
            # Lifetime premium - use 999 days
            await db.set_premium(target_uid, 999)
            label = "♾️ Lifetime Premium"
        else:
            # Add specific days
            await db.extend_premium(target_uid, days)
            label = f"{days} day(s) of Premium"
        
        await update.message.reply_text(
            f"✅ *Premium Added!*\n\n"
            f"User `{target_uid}` → **{label}** added\n\n"
            "Notification sent to user.",
            parse_mode="Markdown",
            reply_markup=admin_menu_kb(),
        )
        
        # Notify user
        try:
            await ctx.bot.send_message(
                chat_id=target_uid,
                text=(
                    f"🎉 *Premium Granted!*\n\n"
                    f"The admin has granted you: **{label}**\n"
                    f"Check your account status now! 💎"
                ),
                parse_mode="Markdown",
            )
        except:
            pass
        
        return ConversationHandler.END
    
    return ConversationHandler.END
async def handle_gift_maxuses(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Finish gift-code creation after the maximum-use count is entered."""
    if not await can_create_giftcode(update):
        return ConversationHandler.END
    try:
        max_uses = int(update.message.text.strip())
        if not 1 <= max_uses <= 999:
            raise ValueError
    except (TypeError, ValueError):
        await update.message.reply_text(
            "❌ Enter a number from 1 to 999.\n\n1 = single use\n999 = unlimited uses",
            reply_markup=InlineKeyboardMarkup([[cancel_button("🔙 Cancel", callback_data="a_back")]]),
        )
        return GIFT_MAXUSES_INPUT

    code = ctx.user_data.get("gift_code_text")
    days = ctx.user_data.get("gift_days")
    if not code or days is None:
        await update.message.reply_text("⚠️ Gift-code session expired. Please start again.", reply_markup=admin_menu_kb())
        return ConversationHandler.END

    try:
        await db.create_gift_code(code, days, max_uses)
    except Exception as exc:
        logger.exception("Gift-code creation failed", exc_info=exc)
        await update.message.reply_text(
            "❌ Could not create this gift code. Please use a different code and try again.",
            reply_markup=admin_menu_kb(),
        )
        return ConversationHandler.END

    days_label = "♾️ Lifetime" if days == 999 else f"{days} day(s)"
    uses_label = "Unlimited" if max_uses == 999 else str(max_uses)
    await update.message.reply_text(
        f"✅ Gift Code Created!\n\n🎁 Code: `{code}`\n💎 Duration: `{days_label}`\n👥 Max Uses: `{uses_label}`",
        parse_mode="Markdown",
        reply_markup=admin_menu_kb(),
    )
    for key in ("gift_code_text", "gift_days", "gift_target_uid"):
        ctx.user_data.pop(key, None)
    return ConversationHandler.END


# ── Revenue Stats ─────────────────────────────────────────────────────────────

@_protected_callback
async def cb_revenue(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    if not await admin_only(update):
        return

    payments = await db.get_all_payments()
    approved = [p for p in payments if p["status"] == "approved"]
    pending = [p for p in payments if p["status"] == "pending"]
    rejected = [p for p in payments if p["status"] == "rejected"]

    total_rev = sum(p["amount"] for p in approved)

    # Per-plan breakdown
    plan_counts: dict = {}
    for p in approved:
        pk = p["plan_key"]
        plan_counts[pk] = plan_counts.get(pk, {"count": 0, "rev": 0})
        plan_counts[pk]["count"] += 1
        plan_counts[pk]["rev"] += p["amount"]

    all_plans = await db.get_plans()
    plan_lines = ""
    for pk, data in sorted(plan_counts.items(), key=lambda x: -x[1]["rev"]):
        plan = all_plans.get(pk, {})
        plan_lines += f"  {plan.get('label', pk)}: *{data['count']}x* = ₹{data['rev']}\n"

    msg = (
        f"📊 *REVENUE ANALYTICS*\n"
        f"{DIVIDER}\n"
        f"✨ Total Revenue: *₹{total_rev:,}*\n"
        f"✅ Approved: *{len(approved)}*\n"
        f"⏳ Pending: *{len(pending)}*\n"
        f"✨ Rejected: *{len(rejected)}*\n\n"
        f"⚙️ *BREAKDOWN BY PLAN*\n"
        f"{DIVIDER}\n"
        f"{plan_lines or '  No approved payments yet.'}"
    )
    await q.message.reply_text(msg, parse_mode="Markdown", reply_markup=back_kb())


# ── Pending Payments ──────────────────────────────────────────────────────────

@_protected_callback
async def cb_pending(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    try:
        await q.answer()
    except Exception:
        pass
    if not await admin_only(update):
        return
    # Always reload fresh from DB — never use cached state
    payments = await db.get_pending_payments()
    if not payments:
        await q.message.reply_text(
            f"✅ *No Pending Payments*\n\n{DIVIDER}\nAll payments have been reviewed!",
            parse_mode="Markdown", reply_markup=back_kb())
        return

    all_plans = await db.get_plans()
    await q.message.reply_text(
        f"⏳ *PENDING PAYMENTS — {len(payments)} request(s)*\n{DIVIDER}\n"
        "Each payment is shown below with Approve / Reject buttons.",
        parse_mode="Markdown", reply_markup=back_kb())

    for p in payments:
        plan = all_plans.get(p["plan_key"], {})
        days = plan.get("days", 1)
        dur_label = "Unlimited (Lifetime)" if days >= 999 else f"{days} day(s)"
        order_line = f"  👁️ Order ID: `{p['order_id']}`\n" if p.get("order_id") else ""
        utr = p.get("utr") or "N/A"
        created = str(p.get("created_at", ""))[:16]
        uname = p.get("username") or "N/A"
        msg = (
            f"⏳ *PAYMENT #{p['id']}*\n"
            f"{DIVIDER}\n"
            f"📱 *User Details*\n"
            f"  🆔 User ID: `{p['user_id']}`\n"
            f"  🤖 Username: @{uname}\n\n"
            f"⚙️ *Plan Details*\n"
            f"  [TARGET] Plan: *{plan.get('label', p['plan_key'])}*\n"
            f"  ⏳ Duration: *{dur_label}*\n"
            f"  ❌ Amount Paid: ₹{p['amount']}\n\n"
            f"📊 *Payment Info*\n"
            f"  🧾 UTR / Txn ID: `{utr}`\n"
            f"{order_line}"
            f"  ✨ Screenshot: {'✅ Attached above' if p.get('screenshot_file_id') else '✨ Not provided'}\n"
            f"  🔗 Submitted: `{created}`\n"
            f"{DIVIDER}"
        )
        kb = payment_action_kb(p["id"])
        try:
            if p.get("screenshot_file_id"):
                await q.message.reply_photo(
                    photo=p["screenshot_file_id"],
                    caption=msg,
                    parse_mode="Markdown",
                    reply_markup=kb,
                )
            else:
                await q.message.reply_text(msg, parse_mode="Markdown", reply_markup=kb)
        except Exception as ex:
            logger.warning(f"Failed to show payment #{p['id']}: {ex}")
            try:
                await q.message.reply_text(msg, parse_mode="Markdown", reply_markup=kb)
            except Exception:
                pass





async def _notify_user_via_user_bot(user_id: int, text: str):
    """Send a user-facing payment result through the USER bot, never the admin bot."""
    from telegram import Bot as _UserBot
    async with _UserBot(token=BOT_TOKEN) as user_bot:
        await user_bot.send_message(chat_id=user_id, text=text, parse_mode="Markdown")


@_protected_callback
async def cb_approve(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    # Always answer immediately so button never freezes
    try:
        await q.answer("✅ Approving payment…")
    except Exception:
        pass
    if not await admin_only(update):
        return
    try:
        payment_id = int(q.data.replace("pay_approve_", ""))
    except (ValueError, AttributeError):
        await q.message.reply_text("⚠️️ Invalid payment ID.", reply_markup=back_kb())
        return
    payment = await db.get_payment(payment_id)
    if not payment:
        await q.message.reply_text("⚠️️ Payment not found — it may have been removed.", reply_markup=back_kb())
        return
    # Guard: already processed — don't double-approve
    if payment.get("status") in ("approved", "rejected"):
        status_icon = "✅" if payment["status"] == "approved" else "✨"
        await q.message.reply_text(
            f"{status_icon} *Payment #{payment_id} was already {payment['status']}.*",
            parse_mode="Markdown", reply_markup=back_kb())
        try:
            await q.message.edit_reply_markup(reply_markup=None)
        except Exception:
            pass
        return
    all_plans = await db.get_plans()
    plan = all_plans.get(payment["plan_key"], {})
    days = plan.get("days", 1)
    now_dt = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
    now_str = datetime.now(timezone.utc).strftime("%d %b %Y, %H:%M UTC")
    await db.set_premium(payment["user_id"], payment["plan_key"], days, amount_paid=payment.get("amount", 0))
    await db.update_payment(payment_id, status="approved", reviewed_at=now_dt)
    await db.increment_plans(payment["user_id"])
    order_id = payment.get("order_id") or ""
    
    # ── Automatic Payout Trigger ───────────────────────────────────────────────
    # Send automatic payout notification to all admins' payout channels
    try:
        # Get the admin's ID (assuming primary admin for now)
        admin_id = ADMIN_TG_ID
        payout_channel = await db.get_payout_channel(admin_id)
        
        # Check if payout hasn't been recorded already for this payment
        if payout_channel and not await db.check_payout_recorded(payment_id):
            amount = payment.get("amount", 0)
            # Send payout notification
            success = await send_payout_notification(ctx, payout_channel['channel_id'], days, amount, "automatic")
            
            if success:
                # Record the payout to prevent duplicates
                await db.record_payout(admin_id, days, amount, payment_id=payment_id, payout_type="automatic")
    except Exception as e:
        logger.error(f"Error sending automatic payout: {e}")
    
    # Remove Approve/Reject buttons from the notification message
    try:
        await q.message.edit_reply_markup(reply_markup=None)
    except Exception:
        pass
    await q.message.reply_text(
        f"✅ *Payment #{payment_id} Approved!*\n\n"
        f"{DIVIDER}\n"
        f"📱 User: `{payment['user_id']}`\n"
        f"⚙️ Plan: *{plan.get('label', payment['plan_key'])}*\n"
        f"⏳ Duration: *{days} day(s)*\n"
        f"❌ Amount: ₹{payment['amount']}\n"
        + (f"👁️ Order: `{order_id}`\n" if order_id else "")
        + f"🔗 Approved: {now_str}",
        parse_mode="Markdown", reply_markup=admin_menu_kb(is_primary=is_primary_admin(update.effective_user.id)))
    # Notify user ONLY through the USER BOT.
    try:
        order_line = f"👁️ Order ID: `{order_id}`\n" if order_id else ""
        utr_line = f"🧾 UTR: `{payment.get('utr') or 'N/A'}`\n" if payment.get("utr") else ""
        dur_label = "Unlimited (Lifetime)" if days >= 999 else f"{days} day(s)"
        await _notify_user_via_user_bot(
            payment["user_id"],
            f"🎉 *Premium Activated Successfully!*\n\n"
            f"{DIVIDER}\n"
            f"{order_line}"
            f"💎 Plan: *{plan.get('label', payment['plan_key'])}*\n"
            f"⏳ Duration: *{dur_label}*\n"
            f"💰 Amount Paid: ₹{payment['amount']}\n"
            f"{utr_line}"
            f"🔗 Approved: {now_str}\n"
            f"{DIVIDER}\n\n"
            "Your Premium has been activated by the Admin. Enjoy your Premium features! 🚀"
        )
    except Exception as ex:
        logger.warning(f"Could not notify user {payment['user_id']} via user bot: {ex}")



@_protected_callback
async def cb_reject(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Ask the admin for a rejection reason before notifying the user."""
    q = update.callback_query
    try:
        await q.answer("✍️ Send the rejection reason…")
    except Exception:
        pass
    if not await admin_only(update):
        return
    try:
        payment_id = int(q.data.replace("pay_reject_", ""))
    except (ValueError, AttributeError):
        await q.message.reply_text("⚠️ Invalid payment ID.")
        return
    payment = await db.get_payment(payment_id)
    if not payment:
        await q.message.reply_text("⚠️ Payment not found.")
        return
    if payment.get("status") in ("approved", "rejected"):
        await q.message.reply_text(f"Payment #{payment_id} was already {payment['status']}.")
        return
    ctx.user_data["payment_reject_id"] = payment_id
    ctx.user_data["payment_reject_message_id"] = q.message.message_id
    await q.message.reply_text(
        f"❌ *Reject Payment #{payment_id}*\n\n"
        f"User: `{payment['user_id']}`\n"
        f"Amount: ₹{payment.get('amount', 'N/A')}\n"
        f"Plan: `{payment.get('plan_key', 'N/A')}`\n\n"
        "Please send the *reason for rejection*. This exact reason will be sent to the user.",
        parse_mode="Markdown",
    )
    return PAYMENT_REJECT_REASON_INPUT


async def handle_payment_reject_reason(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Persist rejection reason and send the final rejection through the USER bot."""
    if not await admin_only(update):
        return ConversationHandler.END
    reason = (update.message.text or "").strip()
    payment_id = ctx.user_data.pop("payment_reject_id", None)
    original_message_id = ctx.user_data.pop("payment_reject_message_id", None)
    if not payment_id:
        await update.message.reply_text("⚠️ No payment rejection is waiting for a reason.")
        return ConversationHandler.END
    if not reason:
        await update.message.reply_text("Please send a non-empty rejection reason.")
        ctx.user_data["payment_reject_id"] = payment_id
        return PAYMENT_REJECT_REASON_INPUT

    payment = await db.get_payment(payment_id)
    if not payment:
        await update.message.reply_text("⚠️ Payment not found.")
        return ConversationHandler.END
    if payment.get("status") in ("approved", "rejected"):
        await update.message.reply_text(f"Payment #{payment_id} was already {payment['status']}.")
        return ConversationHandler.END

    now_dt = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
    await db.update_payment(payment_id, status="rejected", reviewed_at=now_dt, rejection_reason=reason)
    plan_map = await db.get_plans()
    plan = plan_map.get(payment.get("plan_key"), {})
    days = plan.get("days", 1)
    dur = "Unlimited (Lifetime)" if days >= 999 else f"{days} day(s)"
    order_id = payment.get("order_id") or "N/A"

    # Remove review buttons from the original admin notification.
    try:
        await update.get_bot().edit_message_reply_markup(
            chat_id=update.effective_chat.id,
            message_id=original_message_id or 0,
            reply_markup=None,
        )
    except Exception:
        pass

    # Notify the user ONLY via the user bot.
    try:
        await _notify_user_via_user_bot(
            payment["user_id"],
            f"❌ *Premium Payment Rejected*\n\n"
            f"{DIVIDER}\n"
            f"🆔 Order ID: `{order_id}`\n"
            f"💎 Plan: *{plan.get('label', payment.get('plan_key', 'N/A'))}*\n"
            f"⏳ Duration: *{dur}*\n"
            f"💰 Amount: ₹{payment.get('amount', 'N/A')}\n"
            f"🧾 UTR: `{payment.get('utr') or 'N/A'}`\n"
            f"{DIVIDER}\n\n"
            f"*Reason from Admin:*\n{reason}\n\n"
            "Please correct the issue and submit the payment again, or contact support.",
        )
        user_notified = True
    except Exception as ex:
        logger.warning("Could not notify user %s via user bot: %s", payment["user_id"], ex)
        user_notified = False

    await update.message.reply_text(
        f"❌ *Payment #{payment_id} Rejected*\n\n"
        f"{DIVIDER}\n"
        f"👤 User: `{payment['user_id']}`\n"
        f"💰 Amount: ₹{payment.get('amount', 'N/A')}\n"
        f"💎 Plan: *{plan.get('label', payment.get('plan_key', 'N/A'))}*\n"
        f"📝 Reason: {reason}\n"
        f"📨 User notification: {'Sent' if user_notified else 'Failed'}",
        parse_mode="Markdown",
    )
    return ConversationHandler.END


# ── All Payments ──────────────────────────────────────────────────────────────
async def cb_allpayments(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    if not await admin_only(update):
        return
    payments = await db.get_all_payments()
    if not payments:
        await q.message.reply_text("No payments yet.", reply_markup=back_kb())
        return
    all_plans = await db.get_plans()
    chunks = []
    chunk = f"❌ *ALL PAYMENTS ({len(payments)} total)*\n{DIVIDER}\n"
    for p in payments:
        plan = all_plans.get(p["plan_key"], {})
        icon = {"approved": "✅", "rejected": "✨", "pending": "⏳"}.get(p["status"], "✨")
        order_part = f" | 👁️`{p['order_id']}`" if p.get("order_id") else ""
        line = (
            f"{icon} `{p['user_id']}` @{p.get('username') or 'N/A'} | "
            f"{plan.get('label', p['plan_key'])} ₹{p['amount']}{order_part} | "
            f"UTR:`{p.get('utr') or 'N/A'}` | {str(p['created_at'])[:10]}\n"
        )
        if len(chunk) + len(line) > 3800:
            chunks.append(chunk)
            chunk = ""
        chunk += line
    if chunk:
        chunks.append(chunk)
    for c in chunks:
        await q.message.reply_text(c, parse_mode="Markdown", reply_markup=back_kb())


