async def handle_v18_select_user(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not await admin_only(update):
        return ConversationHandler.END
    raw = (update.message.text or "").strip()
    try:
        uid = int(raw)
        if uid <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("❌ Invalid User ID. Please send a numeric Telegram User ID.")
        return BROADCAST_SELECT_USER_STATE

    user = await db.get_user(uid)
    if not user:
        await update.message.reply_text(
            f"❌ *User not found*\n\nUser ID `{uid}` is not registered in this bot.\n"
            "The user may have deleted their account or never started the bot.",
            parse_mode="Markdown",
        )
        return BROADCAST_SELECT_USER_STATE

    # Best possible pre-flight check. Telegram does not expose a private-chat
    # 'can receive bot messages' flag, so a successful get_chat cannot prove
    # that the user has not blocked the bot; a block can only be confirmed by
    # an actual send attempt. We never send a probe message.
    try:
        chat = await ctx.bot.get_chat(chat_id=uid)
    except Forbidden as exc:
        await update.message.reply_text(
            f"❌ *Cannot send to this user*\n\nUser ID: `{uid}`\nReason: `Bot access is forbidden / user is not reachable.`\n\nNo broadcast message was sent.",
            parse_mode="Markdown",
        )
        return BROADCAST_SELECT_USER_STATE
    except BadRequest as exc:
        reason = _v19_reason(str(exc))
        await update.message.reply_text(
            f"❌ *Cannot send to this user*\n\nUser ID: `{uid}`\nReason: *{reason}*\n\nNo broadcast message was sent.",
            parse_mode="Markdown",
        )
        return BROADCAST_SELECT_USER_STATE
    except TelegramError as exc:
        await update.message.reply_text(
            f"⚠️ *User is registered, but Telegram pre-check failed.*\n\nUser ID: `{uid}`\nReason: `{str(exc)[:250]}`\n\nNo message was sent. You can try again.",
            parse_mode="Markdown",
        )
        return BROADCAST_SELECT_USER_STATE

    ctx.user_data["v18_bc_target_ids"] = [uid]
    display = getattr(chat, "username", None)
    extra = f"@{display}" if display else "No username"
    await update.message.reply_text(
        f"✅ *User found!*\n\nUser ID: `{uid}`\nUsername: `{extra}`\n\n"
        "Telegram chat lookup succeeded. Now send the message.\n\n"
        "*Note:* Telegram does not expose a separate pre-check for whether a user has blocked the bot; if they have blocked it, the send attempt will report the exact Telegram rejection reason.",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Cancel", callback_data="bc_confirm_cancel")]]),
    )
    return BROADCAST_MESSAGE_STATE


def _v19_parse_delay(value: str):
    m = re.fullmatch(r"\s*(\d+(?:\.\d+)?)\s*([MSDmsd])\s*", value or "")
    if not m:
        return None
    amount = float(m.group(1))
    unit = m.group(2).upper()
    if amount <= 0:
        return None
    multiplier = {"M": 60, "S": 3600, "D": 86400}[unit]
    return amount * multiplier, unit


def _v19_reason(error: str) -> str:
    text = (error or "Unknown Telegram error").strip()
    low = text.lower()
    if "bot was blocked by the user" in low:
        return "User blocked the bot"
    if "user is deactivated" in low or "user is deleted" in low:
        return "Deleted/deactivated account"
    if "chat not found" in low:
        return "Chat not found"
    if "user not found" in low:
        return "User not found"
    if "bot can't initiate conversation" in low or "can’t initiate conversation" in low:
        return "Bot cannot initiate conversation"
    if "have no rights to send" in low or "not enough rights" in low:
        return "No permission to send message"
    return text[:300]


def _broadcast_targets(users):
    """Return valid private Telegram user/chat IDs for bot broadcasts.

    The users table contains registered bot users.  Keep this helper defensive
    because older databases may contain malformed/legacy rows.  A bot cannot
    initiate arbitrary group/channel broadcasts, so only positive numeric user
    IDs are accepted here.
    """
    targets = []
    seen = set()
    for user in users or []:
        try:
            uid = int(user.get("user_id"))
        except (TypeError, ValueError, AttributeError):
            continue
        if uid <= 0 or uid in seen:
            continue
        seen.add(uid)
        targets.append(uid)
    return targets


async def _v19_get_targets(mode: str, ctx: ContextTypes.DEFAULT_TYPE):
    if mode == "select":
        return list(ctx.user_data.get("v18_bc_target_ids", []))
    return _broadcast_targets(await db.get_all_users())


async def _v19_copy_message(bot, source_message, target_id: int, semaphore: asyncio.Semaphore) -> tuple[str, str]:
    retry_delay = 1.0
    while True:
        try:
            async with semaphore:
                await bot.copy_message(
                    chat_id=target_id,
                    from_chat_id=source_message.chat_id,
                    message_id=source_message.message_id,
                    reply_markup=getattr(source_message, "reply_markup", None),
                )
            return "sent", ""
        except RetryAfter as error:
            await asyncio.sleep(max(float(error.retry_after), 1.0))
        except (TimedOut, NetworkError) as error:
            await asyncio.sleep(retry_delay)
            retry_delay = min(retry_delay * 2, 30.0)
        except (Forbidden, BadRequest) as error:
            return "failed", str(error)
        except TelegramError as error:
            return "failed", str(error)
        except Exception as error:
            return "failed", str(error)


async def _v19_send_failure_report(chat_id: int, bot, failed, title="❌ FAILED / SKIPPED USERS"):
    if not failed:
        return
    lines = [title, "", f"Total: {len(failed)}", ""]
    for uid, reason in failed:
        lines.append(f"{uid} — {reason}")
    chunk = ""
    for line in lines:
        if len(chunk) + len(line) + 1 > 3800:
            await bot.send_message(chat_id=chat_id, text=chunk)
            chunk = ""
        chunk += line + "\n"
    if chunk:
        await bot.send_message(chat_id=chat_id, text=chunk)


async def _v19_send_to_targets(source_message, bot, target_ids, status_message, admin_id: int):
    total = len(target_ids)
    sent = 0
    failed = []
    processed = 0
    stop_event = _v19_active_broadcasts.get(admin_id, {}).get("stop_event")
    semaphore = asyncio.Semaphore(10)
    batch_size = 50

    async def one(uid):
        result, err = await _v19_copy_message(bot, source_message, uid, semaphore)
        return uid, result, err

    for start in range(0, total, batch_size):
        if stop_event and stop_event.is_set():
            break
        batch = target_ids[start:start + batch_size]
        results = await asyncio.gather(*(one(uid) for uid in batch))
        for uid, result, err in results:
            processed += 1
            if result == "sent":
                sent += 1
            else:
                failed.append((uid, _v19_reason(err)))
        percent = round(100 * processed / total) if total else 100
        filled = round(20 * processed / total) if total else 20
        try:
            await status_message.edit_text(
                "📢 *Broadcast in progress…*\n\n"
                f"`[{('█'*filled)+('░'*(20-filled))}]` {percent}%\n"
                f"👥 Processed: *{processed:,} / {total:,}*\n"
                f"✅ Sent: *{sent:,}*\n"
                f"❌ Failed: *{len(failed):,}*",
                parse_mode="Markdown", reply_markup=_v19_stop_markup(),
            )
        except TelegramError:
            pass
        if start + batch_size < total and not (stop_event and stop_event.is_set()):
            await asyncio.sleep(0.2)
    stopped = bool(stop_event and stop_event.is_set())
    return total, processed, sent, failed, stopped


async def _v19_finish_broadcast(admin_id: int, admin_chat_id: int, bot, status_message, total, processed, sent, failed, stopped=False):
    rate = round(100 * sent / processed) if processed else 0
    status = "⛔ *Broadcast Stopped by Admin*" if stopped else "✅ *Broadcast Complete*"
    try:
        await status_message.edit_text(
            f"{status}\n\n"
            f"👥 Total targets: *{total:,}*\n"
            f"📊 Processed: *{processed:,}*\n"
            f"📨 Successfully sent: *{sent:,}* ({rate}%)\n"
            f"❌ Failed / skipped: *{len(failed):,}*",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("📢 Broadcast Center", callback_data="a_broadcast")],
                [InlineKeyboardButton("🔙 Main Admin Menu", callback_data="a_back")],
            ]),
        )
    except TelegramError:
        pass
    await _v19_send_failure_report(admin_chat_id, bot, failed)
    _v19_active_broadcasts.pop(admin_id, None)


async def _v19_run_immediate(admin_id: int, admin_chat_id: int, bot, source_message, target_ids, status_message):
    try:
        result = await _v19_send_to_targets(source_message, bot, target_ids, status_message, admin_id)
        await _v19_finish_broadcast(admin_id, admin_chat_id, bot, status_message, *result)
    except Exception as exc:
        logger.exception("V19 broadcast failed: %s", exc)
        await _v19_finish_broadcast(admin_id, admin_chat_id, bot, status_message, len(target_ids), 0, 0, [(0, str(exc))], False)


async def handle_v18_broadcast_message(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not await admin_only(update):
        return ConversationHandler.END
    mode = ctx.user_data.get("v18_bc_mode")
    if not mode:
        return ConversationHandler.END
    source = update.effective_message
    if mode == "schedule":
        ctx.user_data["v18_bc_source_chat_id"] = source.chat_id
        ctx.user_data["v18_bc_source_message_id"] = source.message_id
        await update.message.reply_text(
            "⏰ Now send the delay. Examples: `10M`, `2S`, `1D`.", parse_mode="Markdown"
        )
        return BROADCAST_SCHEDULE_DELAY_STATE

    if ctx.user_data.get("v19_preview_required", True):
        ctx.user_data["v19_source_chat_id"] = source.chat_id
        ctx.user_data["v19_source_message_id"] = source.message_id
        ctx.user_data["v19_source_message"] = source
        targets = await _v19_get_targets(mode, ctx)
        ctx.user_data["v19_preview_targets"] = targets
        await update.message.reply_text(
            "📋 *BROADCAST PREVIEW*\n\n"
            f"👥 Targets: *{len(targets):,}*\n"
            f"📨 Mode: *{'Select User' if mode == 'select' else 'Broadcast All'}*\n\n"
            "The message is ready. Confirm to start sending.",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("✅ Confirm & Send", callback_data="v19_bc_confirm_send")],
                [InlineKeyboardButton("❌ Cancel", callback_data="bc_confirm_cancel")],
            ]),
        )
        return BROADCAST_MESSAGE_STATE


async def cb_v19_confirm_send(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    if not await can_broadcast(update):
        return ConversationHandler.END
    if ctx.user_data.get("v19_active_started"):
        return ConversationHandler.END
    mode = ctx.user_data.get("v18_bc_mode")
    source_chat_id = ctx.user_data.get("v19_source_chat_id")
    source_message_id = ctx.user_data.get("v19_source_message_id")
    targets = ctx.user_data.get("v19_preview_targets", [])
    if not mode or not source_chat_id or not source_message_id:
        await q.message.reply_text("❌ Broadcast data expired. Please start again.")
        return ConversationHandler.END
    source = ctx.user_data.get("v19_source_message")
    if source is None:
        source = type("SourceMessage", (), {"chat_id": source_chat_id, "message_id": source_message_id, "reply_markup": None})()
    status = await q.message.reply_text(
        f"📢 *Broadcast starting…*\n\n👥 Targets: *{len(targets):,}*",
        parse_mode="Markdown", reply_markup=_v19_stop_markup(),
    )
    admin_id = update.effective_user.id
    stop_event = asyncio.Event()
    _v19_active_broadcasts[admin_id] = {"stop_event": stop_event, "status_message": status}
    ctx.user_data["v19_active_started"] = True
    asyncio.create_task(_v19_run_immediate(admin_id, q.message.chat_id, ctx.bot, source, targets, status))
    return ConversationHandler.END


async def handle_v18_schedule_delay(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not await admin_only(update):
        return ConversationHandler.END
    parsed = _v19_parse_delay(update.message.text)
    if not parsed:
        await update.message.reply_text("❌ Invalid delay. Use formats like `10M`, `2S`, or `1D`.", parse_mode="Markdown")
        return BROADCAST_SCHEDULE_DELAY_STATE
    seconds, unit = parsed
    chat_id = ctx.user_data.get("v18_bc_source_chat_id")
    message_id = ctx.user_data.get("v18_bc_source_message_id")
    if not chat_id or not message_id:
        await update.message.reply_text("❌ Scheduled message data was lost. Please start again.")
        return ConversationHandler.END
    ctx.user_data["v19_schedule_seconds"] = seconds
    ctx.user_data["v19_schedule_pretty"] = (
        f"{seconds/60:g} minutes" if unit == "M" else
        (f"{seconds/3600:g} hours" if unit == "S" else f"{seconds/86400:g} days")
    )
    await update.message.reply_text(
        "📋 *SCHEDULE PREVIEW*\n\n"
        f"👥 Recipients: *All registered bot users*\n"
        f"⏰ Delay: *{ctx.user_data['v19_schedule_pretty']}*\n\n"
        "Confirm to save this schedule. It will survive a bot restart.",
        parse_mode="Markdown", reply_markup=_v19_schedule_confirm_markup(),
    )
    return BROADCAST_SCHEDULE_CONFIRM_STATE


async def cb_v19_schedule_confirm(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    if not await can_broadcast(update):
        return ConversationHandler.END
    seconds = ctx.user_data.get("v19_schedule_seconds")
    chat_id = ctx.user_data.get("v18_bc_source_chat_id")
    message_id = ctx.user_data.get("v18_bc_source_message_id")
    if not seconds or not chat_id or not message_id:
        await q.message.reply_text("❌ Schedule data expired. Please start again.")
        return ConversationHandler.END
    import time as _time
    schedule_id = await db.create_scheduled_broadcast(
        update.effective_user.id, q.message.chat_id, chat_id, message_id, _time.time() + float(seconds)
    )
    await q.message.reply_text(
        f"✅ *Broadcast scheduled successfully!*\n\n🆔 Schedule: `{schedule_id}`\n"
        f"⏰ Delay: *{ctx.user_data.get('v19_schedule_pretty', 'scheduled delay')}*\n"
        "💾 The schedule is saved and will survive a bot restart.",
        parse_mode="Markdown", reply_markup=admin_menu_kb(is_primary=is_primary_admin(update.effective_user.id)),
    )
    for key in list(ctx.user_data):
        if key.startswith("v18_bc_") or key.startswith("v19_"):
            ctx.user_data.pop(key, None)
    return ConversationHandler.END


async def cb_v19_stop(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer("Stopping broadcast…")
    if not await can_broadcast(update):
        return
    active = _v19_active_broadcasts.get(update.effective_user.id)
    if not active:
        await q.message.reply_text("ℹ️ No active broadcast is running.", reply_markup=admin_menu_kb(is_primary=True))
        return
    active["stop_event"].set()
    try:
        await q.message.edit_text("⛔ *Stopping broadcast…*\n\nThe current batch will finish, then sending will stop.", parse_mode="Markdown")
    except TelegramError:
        pass


async def cb_broadcast_cancel(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer("Cancelled.")
    if not await admin_only(update):
        return ConversationHandler.END
    for key in list(ctx.user_data):
        if key.startswith("v18_bc_") or key.startswith("v19_"):
            ctx.user_data.pop(key, None)
    await q.message.reply_text(
        "✨ *Broadcast cancelled.* No messages were sent.",
        parse_mode="Markdown", reply_markup=admin_menu_kb(is_primary=is_primary_admin(update.effective_user.id)),
    )
    return ConversationHandler.END


async def _v19_run_persisted_schedule(row):
    schedule_id = int(row["id"])
    admin_id = int(row["admin_id"])
    admin_chat_id = int(row["admin_chat_id"])
    if not await db.mark_scheduled_broadcast_running(schedule_id):
        return
    try:
        bot = Bot(BOT_TOKEN)
        source = type("SourceMessage", (), {
            "chat_id": int(row["source_chat_id"]),
            "message_id": int(row["source_message_id"]),
            "reply_markup": None,
        })()
        targets = _broadcast_targets(await db.get_all_users())
        status = await bot.send_message(
            admin_chat_id,
            f"⏰ *Scheduled Broadcast Started*\n\n👥 Targets: *{len(targets):,}*",
            parse_mode="Markdown", reply_markup=_v19_stop_markup(),
        )
        stop_event = asyncio.Event()
        _v19_active_broadcasts[admin_id] = {"stop_event": stop_event, "status_message": status}
        result = await _v19_send_to_targets(source, bot, targets, status, admin_id)
        await _v19_finish_broadcast(admin_id, admin_chat_id, bot, status, *result)
        await db.finish_scheduled_broadcast(schedule_id, "completed" if not result[-1] else "stopped")
        await bot.shutdown()
    except Exception as exc:
        logger.exception("Persistent scheduled broadcast %s failed", schedule_id)
        await db.finish_scheduled_broadcast(schedule_id, "failed", str(exc))


async def _v19_scheduler_loop(app):
    while True:
        try:
            import time as _time
            due = await db.get_due_scheduled_broadcasts(_time.time())
            for row in due:
                asyncio.create_task(_v19_run_persisted_schedule(row))
            await asyncio.sleep(5)
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception("Broadcast scheduler loop error")
            await asyncio.sleep(5)


async def _v19_post_init(app):
    global _v19_scheduler_task
    _v19_scheduler_task = asyncio.create_task(_v19_scheduler_loop(app), name="v19_broadcast_scheduler")


async def _v19_post_shutdown(app):
    global _v19_scheduler_task
    if _v19_scheduler_task:
        _v19_scheduler_task.cancel()
        try:
            await _v19_scheduler_task
        except asyncio.CancelledError:
            pass
        _v19_scheduler_task = None

