async def handle_promo_reject_reason(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Receives the admin's reason and delivers it to the user."""
    order_id = ctx.user_data.pop("promo_reject_order_id", None)
    target_user_id = ctx.user_data.pop("promo_reject_user_id", None)

    if not order_id or not target_user_id:
        await update.message.reply_text("⚠️️ Session expired. Please try again.", reply_markup=admin_menu_kb())
        return ConversationHandler.END

    # Mark order as rejected in DB
    await db.update_promo_order(order_id, status="rejected", reviewed_at="CURRENT_TIMESTAMP")

    msg = update.message
    CONTACT_LINE = "IF YOU THINK ITS A MISTAKE CONTACT ADMIN @okdruv"

    # Deliver reason to user depending on message type
    sent_ok = False
    try:
        if msg.text:
            await ctx.bot.send_message(
                chat_id=target_user_id,
                text=(
                    f"✨ YOUR ORDER IS REJECTED\n\n"
                    f"REASON - {msg.text}\n\n"
                    f"{CONTACT_LINE}"
                ),
            )
            sent_ok = True
        elif msg.photo:
            caption = (
                f"✨ YOUR ORDER IS REJECTED\n\n"
                f"REASON - {msg.caption or 'See screenshot above'}\n\n"
                f"{CONTACT_LINE}"
            )
            await ctx.bot.send_photo(
                chat_id=target_user_id,
                photo=msg.photo[-1].file_id,
                caption=caption,
            )
            sent_ok = True
        elif msg.voice:
            await ctx.bot.send_message(
                chat_id=target_user_id,
                text=(
                    f"✨ YOUR ORDER IS REJECTED\n\n"
                    f"REASON - (Voice message from admin)\n\n"
                    f"{CONTACT_LINE}"
                ),
            )
            await ctx.bot.send_voice(chat_id=target_user_id, voice=msg.voice.file_id)
            sent_ok = True
        elif msg.document:
            caption = (
                f"✨ YOUR ORDER IS REJECTED\n\n"
                f"REASON - {msg.caption or 'See attached file'}\n\n"
                f"{CONTACT_LINE}"
            )
            await ctx.bot.send_document(
                chat_id=target_user_id,
                document=msg.document.file_id,
                caption=caption,
            )
            sent_ok = True
        elif msg.video:
            caption = (
                f"✨ YOUR ORDER IS REJECTED\n\n"
                f"REASON - {msg.caption or 'See video above'}\n\n"
                f"{CONTACT_LINE}"
            )
            await ctx.bot.send_video(
                chat_id=target_user_id,
                video=msg.video.file_id,
                caption=caption,
            )
            sent_ok = True
        else:
            # Fallback: forward whatever it is, then send the framing text
            await ctx.bot.forward_message(
                chat_id=target_user_id,
                from_chat_id=msg.chat_id,
                message_id=msg.message_id,
            )
            await ctx.bot.send_message(
                chat_id=target_user_id,
                text=(
                    f"✨ YOUR ORDER IS REJECTED\n\n"
                    f"REASON - See message above\n\n"
                    f"{CONTACT_LINE}"
                ),
            )
            sent_ok = True
    except Exception as ex:
        logger.warning(f"Could not send rejection reason to user {target_user_id}: {ex}")

    status_note = "✅ User notified." if sent_ok else "⚠️️ Could not notify user (they may have blocked the bot)."
    await update.message.reply_text(
        f"✨ *Promo Order Rejected.*\n\n"
        f"👁️ Order: `{order_id}`\n"
        f"{status_note}",
        parse_mode="Markdown",
        reply_markup=admin_menu_kb(),
    )
    return ConversationHandler.END


