async def cancel_conv(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Cancel an active admin/agent conversation and honour its nav button.

    ConversationHandler fallbacks run before the global callback handlers.
    Without this callback fallback, inline Cancel/Back buttons appear to do
    nothing while a conversation is active.
    """
    q = update.callback_query
    if q is not None:
        destinations = {
            "a_back": cb_back,
            "a_edit": cb_edit,
            "a_upi_settings": cb_upi_settings,
            "a_set_price": cb_set_price,
            "a_custom_buttons": cb_custom_buttons,
            "ae_channels": cb_edit_channels,
            "a_referral": cb_referral_settings,
            "a_ads_branding": cb_ads_branding,
            "a_botsettings": cb_botsettings,
            "a_gmail_settings": cb_gmail_settings,
            "a_logs_bot_settings": cb_logs_bot_settings,
            "a_payout_mgmt": cb_payout_mgmt,
            "a_channel_promo": cb_channel_promo,
            "a_premium_post": cb_premium_post_admin,
            "a_check_emoji": cb_check_emoji,
            "ag_set_agents": cb_set_agents,
            "ag_give_order": cb_give_order,
            "ag_agent_refresh": cb_agent_panel_refresh,
            "ag_completed": cb_agent_completed,
            "cb_user_bot_emojis": cb_user_bot_emojis,
            "cb_emoji_premium": cb_emoji_premium,
            "cb_emoji_unicode": cb_emoji_unicode,
            "bc_stop_mass_dm": cb_mass_dm_stop,
            "bc_stop_join_req": cb_join_request_stop,
            "a_ads_analytics": cb_ads_analytics_detailed,
        }
        destination = destinations.get(q.data)
        if destination is not None:
            try:
                await destination(update, ctx)
            except Exception as ex:
                logger.warning("Callback %s raised exception: %s", q.data, ex)
                try:
                    await q.answer("An error occurred. Please try again.", show_alert=True)
                except Exception:
                    pass
        else:
            try:
                await q.answer("Cancelled.")
            except Exception:
                pass
            uid = update.effective_user.id if update.effective_user else 0
            if uid and await db.is_agent(uid) and not (
                is_primary_admin(uid) or await db.is_extra_admin(uid)
            ):
                await _show_agent_panel(q.message, uid)
            elif uid and (is_primary_admin(uid) or await db.is_extra_admin(uid)):
                await q.message.reply_text(
                    "Cancelled.",
                    reply_markup=admin_menu_kb(is_primary=is_primary_admin(uid)),
                )
        return ConversationHandler.END

    uid = update.effective_user.id if update.effective_user else 0
    if uid and await db.is_agent(uid) and not (
        is_primary_admin(uid) or await db.is_extra_admin(uid)
    ):
        await _show_agent_panel(update.effective_message, uid)
    else:
        await update.effective_message.reply_text(
            "Cancelled.",
            reply_markup=admin_menu_kb(is_primary=is_primary_admin(uid)),
        )
    return ConversationHandler.END


