async def handle_pp_add(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    ids = _extract_emoji_ids(update.message.text)
    if not ids:
        await update.message.reply_text("No emoji IDs found. Please send the numbers.")
        return PP_ADD
    current = await load_emoji_ids(db)
    valid, invalid = [], []
    for i in range(0, len(ids), 200):
        chunk = ids[i:i + 200]
        try:
            stickers = await ctx.bot.get_custom_emoji_stickers(custom_emoji_ids=chunk)
            found = {s.custom_emoji_id for s in stickers}
            valid += [x for x in chunk if x in found]
            invalid += [x for x in chunk if x not in found]
        except Exception:
            invalid += chunk
    added = [x for x in valid if x not in current]
    already = [x for x in valid if x in current]
    if added:
        await save_emoji_ids(db, current + added)
    lines = [
        "<b>Emoji IDs updated</b>",
        "━━━━━━━━━━━━━━━━━━━━",
        f"Added: <b>{len(added)}</b>",
        f"Already in collection: <b>{len(already)}</b>",
        f"Invalid or not found: <b>{len(invalid)}</b>",
        f"Total in collection: <b>{len(current) + len(added)}</b>",
    ]
    if invalid:
        lines.append("\nInvalid IDs:\n" + "\n".join(invalid))
    await update.message.reply_text("\n".join(lines), parse_mode="HTML",
                                    reply_markup=_pp_back_kb())
    return ConversationHandler.END


async def handle_pp_remove(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    ids = _extract_emoji_ids(update.message.text)
    if not ids:
        await update.message.reply_text("No emoji IDs found. Please send the numbers.")
        return PP_REMOVE
    current = await load_emoji_ids(db)
    removed = [x for x in ids if x in current]
    missing = [x for x in ids if x not in current]
    remaining = [x for x in current if x not in removed]
    if not remaining:
        await update.message.reply_text(
            "At least one emoji must stay in the collection. Nothing was removed.",
            reply_markup=_pp_back_kb())
        return ConversationHandler.END
    if removed:
        await save_emoji_ids(db, remaining)
    lines = [
        "<b>Emoji IDs removed</b>",
        "━━━━━━━━━━━━━━━━━━━━",
        f"Removed: <b>{len(removed)}</b>",
        f"Not in collection: <b>{len(missing)}</b>",
        f"Total in collection: <b>{len(remaining)}</b>",
    ]
    await update.message.reply_text("\n".join(lines), parse_mode="HTML",
                                    reply_markup=_pp_back_kb())
    return ConversationHandler.END


async def cancel_pp(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    await update.message.reply_text("Cancelled.", reply_markup=_pp_back_kb())
    return ConversationHandler.END


def _pp_back_kb():
    return InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Back to Controller", callback_data="a_premium_post")]])


pp_emoji_conv = ConversationHandler(
    entry_points=[
        CallbackQueryHandler(cb_pp_add_start, pattern="^a_pp_add$"),
        CallbackQueryHandler(cb_pp_remove_start, pattern="^a_pp_remove$"),
    ],
    states={
        PP_ADD: [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_pp_add)],
        PP_REMOVE: [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_pp_remove)],
    },
    fallbacks=[CommandHandler("cancel", cancel_pp)],
    allow_reentry=True, per_message=False,
)


