async def cb_broadcast_send(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Copy the exact admin message to every stored user.

    Telegram's copy_message preserves the original message type, caption/entities,
    links, custom/animated emojis, media and formatting instead of rebuilding the
    message with a limited set of media branches.
    """
    if not ctx.user_data.get("broadcast_mode"):
        return
    user_id = update.effective_user.id
    if not (is_primary_admin(user_id) or await db.is_extra_admin(user_id)):
        return
    message = update.message
    all_users = await db.get_all_users()
    sent_count = failed_count = 0

    async def send_one(user):
        nonlocal sent_count, failed_count
        try:
            await ctx.bot.copy_message(
                chat_id=int(user["user_id"]),
                from_chat_id=int(ADMIN_TG_ID),
                message_id=int(message.message_id),
            )
            sent_count += 1
        except Exception as exc:
            failed_count += 1
            logger.debug("Broadcast copy failed for %s: %s", user.get("user_id"), exc)

    # Telegram flood limits still apply; concurrent batches make normal
    # broadcasts fast without turning one failed recipient into a global error.
    batch_size = 25
    for i in range(0, len(all_users), batch_size):
        await asyncio.gather(*(send_one(u) for u in all_users[i:i+batch_size]), return_exceptions=True)
        await asyncio.sleep(0.05)

    ctx.user_data["broadcast_mode"] = False
    result_text = (
        f"✅ *BROADCAST SENT*\n\n{DIVIDER}\n"
        f"Sent to: *{sent_count}* users\n"
        f"Failed: *{failed_count}* users\n"
        f"Total: *{sent_count + failed_count}* users\n\n"
        "Broadcast copied exactly as sent."
    )
    await message.reply_text(
        result_text, parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("📢 Send Another", callback_data="a_broadcast")],
            [InlineKeyboardButton("🔙 Back to Dashboard", callback_data="a_back")],
        ]),
    )


# ── Pending Payments Management ────────────────────────────────────────────────
async def cb_pending_payments(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Show EVERY pending payment as a separate review item with receipt/screenshot."""
    q = update.callback_query
    try:
        await q.answer()
    except Exception:
        pass
    if not await admin_only(update):
        return

    pending = await db.get_pending_payments()
    if not pending:
        await q.message.reply_text(
            "💳 *NO PENDING PAYMENTS*\n\nAll payments have been processed.",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("🔙 Back to Dashboard", callback_data="a_back")],
            ]),
        )
        return

    plans = await db.get_plans()
    await q.message.reply_text(
        f"💳 *PENDING PAYMENTS — {len(pending)} REQUEST(S)*\n\n"
        "Every pending payment is shown below with its complete details. "
        "Manual payments include the submitted screenshot.",
        parse_mode="Markdown",
    )

    for payment in pending:
        plan = plans.get(payment.get("plan_key"), {})
        days = plan.get("days", 1)
        duration = "Unlimited (Lifetime)" if days >= 999 else f"{days} day(s)"
        uname = payment.get("username") or "N/A"
        order_id = payment.get("order_id") or "N/A"
        utr = payment.get("utr") or "N/A"
        created = str(payment.get("created_at") or "N/A")
        method = str(payment.get("payment_method") or "manual").upper()
        screenshot = payment.get("screenshot_file_id")

        receipt = (
            f"💳 *PAYMENT #{payment['id']} — PENDING*\n\n"
            f"👤 *User Details*\n"
            f"• User ID: `{payment.get('user_id')}`\n"
            f"• Username: @{uname}\n\n"
            f"💎 *Plan Details*\n"
            f"• Plan: *{plan.get('label', payment.get('plan_key'))}*\n"
            f"• Duration: *{duration}*\n"
            f"• Amount: *₹{payment.get('amount', 'N/A')}*\n\n"
            f"🧾 *Payment Details*\n"
            f"• Method: *{method}*\n"
            f"• UTR / Transaction ID: `{utr}`\n"
            f"• Order ID: `{order_id}`\n"
            f"• Submitted: `{created}`\n"
            f"• Screenshot: {'✅ Attached' if screenshot else '❌ Not provided'}\n\n"
            "Choose an action below."
        )
        kb = payment_action_kb(payment["id"])
        try:
            if screenshot:
                await q.message.reply_photo(
                    photo=screenshot,
                    caption=receipt,
                    parse_mode="Markdown",
                    reply_markup=kb,
                )
            else:
                await q.message.reply_text(receipt, parse_mode="Markdown", reply_markup=kb)
        except Exception as ex:
            logger.warning("Failed to display pending payment #%s: %s", payment.get("id"), ex)
            await q.message.reply_text(receipt, parse_mode="Markdown", reply_markup=kb)

    await q.message.reply_text(
        "✅ *End of pending payment list.*",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("🔙 Back to Dashboard", callback_data="a_back")],
        ]),
    )


async def cb_payment_approve(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Approve from the Pending Payments screen and notify user via USER bot."""
    q = update.callback_query
    await q.answer("✅ Approving…")
    if not await admin_only(update):
        return
    try:
        payment_id = int(q.data.replace("a_pay_approve_", ""))
    except ValueError:
        await q.message.reply_text("⚠️ Invalid payment ID.")
        return
    payment = await db.get_payment(payment_id)
    if not payment or payment.get("status") != "pending":
        await q.message.reply_text("⚠️ Payment not found or already processed.")
        return
    all_plans = await db.get_plans()
    plan = all_plans.get(payment["plan_key"], {})
    days = plan.get("days", 1)
    await db.set_premium(payment["user_id"], payment["plan_key"], days, amount_paid=payment.get("amount", 0))
    await db.update_payment(payment_id, status="approved", reviewed_at=datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S"))
    await db.increment_plans(payment["user_id"])
    dur = "Unlimited (Lifetime)" if days >= 999 else f"{days} day(s)"
    try:
        await _notify_user_via_user_bot(
            payment["user_id"],
            f"🎉 *Premium Activated Successfully!*\n\n{DIVIDER}\n"
            f"🆔 Order ID: `{payment.get('order_id') or 'N/A'}`\n"
            f"💎 Plan: *{plan.get('label', payment['plan_key'])}*\n"
            f"⏳ Duration: *{dur}*\n"
            f"💰 Amount Paid: ₹{payment.get('amount', 'N/A')}\n"
            f"{DIVIDER}\n\nYour Premium has been activated by the Admin. Enjoy! 🚀"
        )
    except Exception as ex:
        logger.warning("User notification failed: %s", ex)
    try: await q.message.edit_reply_markup(reply_markup=None)
    except Exception: pass
    await q.message.reply_text(f"✅ Payment #{payment_id} approved and user notified.")


