async def handle_order_members(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not is_primary_admin(update.effective_user.id):
        return ConversationHandler.END
    text = update.message.text.strip()
    try:
        members = int(text)
        if members <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("✨ Please enter a valid positive number for members.")
        return AGENT_ORDER_MEMBERS
    ctx.user_data["ag_order_members"] = members
    display = ctx.user_data.get("ag_order_agent_display", "Agent")
    await update.message.reply_text(
        f"👁️ *Order for {display}*\n{DIVIDER}\n"
        "Step 2 of 3\n\n"
        "How much will you *pay the agent*? (Enter amount in ₹)",
        parse_mode="Markdown",
    )
    return AGENT_ORDER_PAYMENT


async def handle_order_payment(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not is_primary_admin(update.effective_user.id):
        return ConversationHandler.END
    text = update.message.text.strip().replace("₹", "").replace(",", "")
    try:
        amount = float(text)
        if amount <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("✨ Please enter a valid payment amount (e.g. 500).")
        return AGENT_ORDER_PAYMENT
    ctx.user_data["ag_order_payment"] = amount
    display = ctx.user_data.get("ag_order_agent_display", "Agent")
    await update.message.reply_text(
        f"👁️ *Order for {display}*\n{DIVIDER}\n"
        "Step 3 of 3\n\n"
        "Enter the *channel link* for the promotion:",
        parse_mode="Markdown",
    )
    return AGENT_ORDER_CHANNEL


async def handle_order_channel(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not is_primary_admin(update.effective_user.id):
        return ConversationHandler.END
    channel = update.message.text.strip()
    agent_id = ctx.user_data.get("ag_order_agent_id")
    members  = ctx.user_data.get("ag_order_members")
    payment  = ctx.user_data.get("ag_order_payment")
    display  = ctx.user_data.get("ag_order_agent_display", str(agent_id))

    if not agent_id or not members or not payment:
        await update.message.reply_text(
            "⚠️️ Session expired. Please start over.", reply_markup=_agent_back_kb()
        )
        return ConversationHandler.END

    order = await db.create_agent_order(agent_id, channel, members, payment)
    order_id = order["id"]

    # ── Notify the agent inside the Admin Bot ──────────────────────────────────
    agent_kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("✅ Approve", callback_data=f"ag_approve_{order_id}"),
         InlineKeyboardButton("❌ Reject",  callback_data=f"ag_reject_{order_id}")],
    ])
    try:
        await ctx.bot.send_message(
            chat_id=agent_id,
            text=(
                f"👁️ *NEW ORDER RECEIVED*\n{DIVIDER}\n"
                f"📣 Channel:       `{channel}`\n"
                f"👥 Member Target: *{members:,}*\n"
                f"❌ Your Payment:  *₹{payment:,.0f}*\n"
                f"{DIVIDER}\n"
                "Please review this order and respond below."
            ),
            parse_mode="Markdown",
            reply_markup=agent_kb,
        )
        notified = True
    except Exception:
        notified = False

    status_note = "" if notified else "\n\n⚠️️ _Could not notify the agent — they may not have started the bot yet._"
    await update.message.reply_text(
        f"✅ *Order Sent!*\n{DIVIDER}\n"
        f"📱 Agent:   {display}\n"
        f"📣 Channel: `{channel}`\n"
        f"👥 Members: *{members:,}*\n"
        f"❌ Payment: *₹{payment:,.0f}*\n"
        f"🧾 Order #: `{order_id}`"
        f"{status_note}",
        parse_mode="Markdown", reply_markup=_agent_back_kb(),
    )
    return ConversationHandler.END


