async def cb_agent_approve(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Step 1 of approve flow: mark approved, notify admin, ask agent to send join request."""
    q = update.callback_query
    await q.answer()
    uid = update.effective_user.id
    if not await db.is_agent(uid):
        return ConversationHandler.END
    order_id = int(q.data.replace("ag_approve_", ""))
    order = await db.get_agent_order(order_id)
    if not order or order["agent_id"] != uid:
        await q.message.reply_text("✨ Order not found.")
        return ConversationHandler.END
    if order["status"] != "pending":
        await q.message.reply_text("⚠️️ This order has already been responded to.")
        return ConversationHandler.END

    await db.update_agent_order(order_id, status="approved")
    ctx.user_data["ag_completing_order_id"] = order_id

    # ── Notify Main Admin: Order Approved ─────────────────────────────────────
    try:
        agent = await db.get_agent(uid)
        display = f"@{agent['username']}" if agent and agent.get("username") else str(uid)
        await ctx.bot.send_message(
            chat_id=_get_main_admin_id(),
            text=(
                f"✅ *Order Approved*\n{DIVIDER}\n"
                f"📱 Agent:    {display}\n"
                f"🆔 Order ID: #{order_id}\n"
                f"👁️ Status:   Accepted\n\n"
                "The agent has accepted the order and is starting the join request step."
            ),
            parse_mode="Markdown",
        )
    except Exception:
        pass

    # ── Step 1: Instruct agent to send join request ───────────────────────────
    await q.message.reply_text(
        f"✅ *Order #{order_id} Approved!*\n{DIVIDER}\n"
        f"📣 Channel: `{order['channel_link']}`\n"
        f"👥 Members: *{order['member_target']:,}*\n\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📝 *Step 1 of 3 — Send Join Request*\n\n"
        f"Please send a join request to the provided link:\n"
        f"📤 `{order['channel_link']}`\n\n"
        "Once you have sent the request, tap the button below.",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("✅ Request Sent", callback_data=f"ag_join_sent_{order_id}"),
        ]]),
    )
    return ConversationHandler.END


