async def cb_agent_reject(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Entry point: ask agent for a rejection reason before rejecting the order."""
    q = update.callback_query
    await q.answer()
    uid = update.effective_user.id
    if not await db.is_agent(uid):
        return ConversationHandler.END
    order_id = int(q.data.replace("ag_reject_", ""))
    order = await db.get_agent_order(order_id)
    if not order or order["agent_id"] != uid:
        await q.message.reply_text("✨ Order not found.")
        return ConversationHandler.END
    if order["status"] != "pending":
        await q.message.reply_text("⚠️️ This order has already been responded to.")
        return ConversationHandler.END

    ctx.user_data["ag_reject_order_id"] = order_id
    ctx.user_data["ag_reject_channel"]  = order.get("channel_link", "")
    ctx.user_data["ag_reject_members"]  = order.get("member_target", 0)

    await q.message.reply_text(
        f"✨ *Reject Order #{order_id}*\n{DIVIDER}\n"
        f"📣 Channel: `{order.get('channel_link', '')}`\n\n"
        "Please enter the *reason* for rejecting this order.\n\n"
        "_Examples: \"Waiting for admin access.\", \"Invalid channel link.\", \"Unable to complete the order.\"_",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[
            cancel_button("🔙 Cancel", callback_data="ag_agent_refresh"),
        ]]),
    )
    return AGENT_REJECT_REASON


async def handle_agent_reject_reason(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Receive rejection reason, mark order rejected, notify Main Admin with reason."""
    uid = update.effective_user.id
    if not await db.is_agent(uid):
        return ConversationHandler.END

    reason   = (update.message.text or "").strip()
    order_id = ctx.user_data.pop("ag_reject_order_id", None)
    ctx.user_data.pop("ag_reject_channel", None)
    ctx.user_data.pop("ag_reject_members", None)

    if not order_id:
        await update.message.reply_text("⚠️️ Session expired. Please start over.", reply_markup=_agent_back_kb())
        return ConversationHandler.END

    if not reason:
        await update.message.reply_text(
            "⚠️️ Reason cannot be empty. Please type a rejection reason.",
        )
        return AGENT_REJECT_REASON

    await db.update_agent_order(order_id, status="rejected")

    # ── Notify Main Admin with reason ─────────────────────────────────────────
    try:
        agent = await db.get_agent(uid)
        display = f"@{agent['username']}" if agent and agent.get("username") else str(uid)
        order   = await db.get_agent_order(order_id)
        await update.get_bot().send_message(
            chat_id=_get_main_admin_id(),
            text=(
                f"✨ *Order Rejected*\n{DIVIDER}\n"
                f"📱 Agent:    {display}\n"
                f"🆔 Order ID: #{order_id}\n\n"
                f"🚀 Reason:\n\"{reason}\""
            ),
            parse_mode="Markdown",
        )
    except Exception:
        pass

    await update.message.reply_text(
        f"✨ *Order #{order_id} Rejected*\n{DIVIDER}\n"
        "Your rejection reason has been sent to the Main Admin.",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("[RUNNING] Back to Panel", callback_data="ag_agent_refresh"),
        ]]),
    )
    return ConversationHandler.END


