async def handle_agent_payment_qr(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    if not await db.is_agent(uid):
        return ConversationHandler.END
    if not update.message.photo:
        await update.message.reply_text("✨ Please send a *photo* of your payment QR code.")
        return AGENT_PAYMENT_QR

    order_id = ctx.user_data.get("ag_completing_order_id")
    screenshot_id = ctx.user_data.get("ag_completion_screenshot_id")
    if not order_id or not screenshot_id:
        await update.message.reply_text("⚠️️ Session expired. Please start over.")
        return ConversationHandler.END

    qr_id = update.message.photo[-1].file_id
    await db.update_agent_order(order_id, status="completed",
                                completion_screenshot_id=screenshot_id,
                                payment_qr_id=qr_id)

    order = await db.get_agent_order(order_id)
    agent = await db.get_agent(uid)
    display = f"@{agent['username']}" if agent and agent.get("username") else str(uid)

    # Forward both files + summary to Main Admin
    try:
        await ctx.bot.send_message(
            chat_id=_get_main_admin_id(),
            text=done_message_html(
                f"*Agent Order Completed — #{order_id}*\n{DIVIDER}\n"
                f"📱 Agent:   {display} (`{uid}`)\n"
                f"📣 Channel: `{order['channel_link']}`\n"
                f"👥 Members: *{order['member_target']:,}*\n"
                f"❌ Payment: *₹{order['payment_amount']:,.0f}*\n\n"
                "✨ Completion screenshot and QR code follow.\n"
                "Open *✅ Agent Orders Completed* to review and pay."
            ),
            parse_mode="HTML",
        )
        await ctx.bot.send_photo(chat_id=_get_main_admin_id(), photo=screenshot_id,
                                 caption=custom_emoji_html("✨") + f" Completion Screenshot — Order #{order_id}",
                                 parse_mode="HTML")
        await ctx.bot.send_photo(chat_id=_get_main_admin_id(), photo=qr_id,
                                 caption=custom_emoji_html("💳") + f" Agent Payment QR — Order #{order_id}",
                                 parse_mode="HTML")
    except Exception:
        pass

    await update.message.reply_text(
        f"[CELEBRATE] *Submitted Successfully!*\n{DIVIDER}\n"
        "Your completion screenshot and payment QR have been forwarded to the Main Admin.\n\n"
        "You will receive a confirmation once the payment is sent.",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("[RUNNING] Back to Panel", callback_data="ag_agent_refresh")
        ]]),
    )
    return ConversationHandler.END


# ── Agent Orders Completed (Main Admin view) ───────────────────────────────────

async def cb_agent_completed(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not is_primary_admin(update.effective_user.id):
        await q.answer("❌ Only the Main Admin can view this.", show_alert=True)
        return
    await q.answer()
    orders = await db.get_all_agent_orders_by_status("completed")
    if not orders:
        await q.message.reply_text(
            done_message_html(
                f"*Agent Orders Completed*\n{DIVIDER}\nNo completed orders waiting for payment."
            ),
            parse_mode="HTML", reply_markup=_agent_back_kb(),
        )
        return
    rows = []
    for o in orders:
        uname = o.get("agent_username", "") or ""
        label = f"@{uname}" if uname else f"ID {o['agent_id']}"
        rows.append([InlineKeyboardButton(
            f"💳 Pay — Order #{o['id']} | {label} | ₹{o['payment_amount']:,.0f}",
            callback_data=f"ag_admin_pay_{o['id']}"
        )])
    rows.append([InlineKeyboardButton("🔙 Back", callback_data="a_back")])
    await q.message.reply_text(
        f"✅ *AGENT ORDERS COMPLETED*\n{DIVIDER}\n"
        f"*{len(orders)}* order(s) awaiting your payment.\n\n"
        "Tap an order to review and pay:",
        parse_mode="Markdown", reply_markup=InlineKeyboardMarkup(rows),
    )


async def cb_agent_payments(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Alias — same view as Agent Orders Completed but named 'Agent Payments'."""
    await cb_agent_completed(update, ctx)


async def cb_admin_pay_order(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    if not is_primary_admin(update.effective_user.id):
        return ConversationHandler.END
    order_id = int(q.data.replace("ag_admin_pay_", ""))
    order = await db.get_agent_order(order_id)
    if not order:
        await q.message.reply_text("✨ Order not found.")
        return ConversationHandler.END
    if order["status"] not in ("completed",):
        await q.message.reply_text("⚠️️ This order is not in a payable state.")
        return ConversationHandler.END

    agent = await db.get_agent(order["agent_id"])
    display = f"@{agent['username']}" if agent and agent.get("username") else str(order["agent_id"])

    ctx.user_data["ag_paying_order_id"] = order_id
    ctx.user_data["ag_paying_agent_id"] = order["agent_id"]
    ctx.user_data["ag_paying_agent_display"] = display

    # Show the screenshots to the admin for review
    try:
        await ctx.bot.send_photo(
            chat_id=update.effective_chat.id,
            photo=order["completion_screenshot_id"],
            caption=f"✨ Completion Screenshot — Order #{order_id}",
        )
        await ctx.bot.send_photo(
            chat_id=update.effective_chat.id,
            photo=order["payment_qr_id"],
            caption=f"💳 Agent Payment QR — Scan & pay ₹{order['payment_amount']:,.0f}",
        )
    except Exception:
        pass

    await q.message.reply_text(
        f"💳 *PAY AGENT — Order #{order_id}*\n{DIVIDER}\n"
        f"📱 Agent:   {display}\n"
        f"📣 Channel: `{order['channel_link']}`\n"
        f"👥 Members: *{order['member_target']:,}*\n"
        f"❌ Amount:  *₹{order['payment_amount']:,.0f}*\n\n"
        "Scan the QR above and send the payment manually.\n\n"
        "Once paid, upload the *payment screenshot* below to confirm.",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[cancel_button("🔙 Cancel", callback_data="ag_completed")]]),
    )
    return ADMIN_PAYMENT_SCREENSHOT


async def handle_admin_payment_screenshot(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not is_primary_admin(update.effective_user.id):
        return ConversationHandler.END
    if not update.message.photo:
        await update.message.reply_text("✨ Please upload a *photo* of the payment screenshot.")
        return ADMIN_PAYMENT_SCREENSHOT

    order_id   = ctx.user_data.get("ag_paying_order_id")
    agent_id   = ctx.user_data.get("ag_paying_agent_id")
    display    = ctx.user_data.get("ag_paying_agent_display", str(agent_id))

    if not order_id or not agent_id:
        await update.message.reply_text("⚠️️ Session expired. Please start over.", reply_markup=_agent_back_kb())
        return ConversationHandler.END

    file_id = update.message.photo[-1].file_id
    await db.update_agent_order(order_id, status="paid", payment_screenshot_id=file_id)

    # Notify the agent
    try:
        await ctx.bot.send_message(
            chat_id=agent_id,
            text=(
                f"❌ *Payment Sent — Order #{order_id}*\n{DIVIDER}\n"
                "Your payment has been sent successfully.\n\n"
                "If you do not receive the payment, please contact the Main Admin."
            ),
            parse_mode="Markdown",
        )
        await ctx.bot.send_photo(
            chat_id=agent_id,
            photo=file_id,
            caption=f"💳 Payment Screenshot — Order #{order_id}",
        )
    except Exception:
        pass

    order = await db.get_agent_order(order_id)
    await update.message.reply_text(
        f"✅ *Payment Confirmed — Order #{order_id}*\n{DIVIDER}\n"
        f"📱 Agent {display} has been notified.\n"
        f"❌ Amount: *₹{order['payment_amount']:,.0f}*",
        parse_mode="Markdown", reply_markup=_agent_back_kb(),
    )
    return ConversationHandler.END


