# ── PAYOUT RECEIPTS TRACKING ──────────────────────────────────────────────────
async def record_premium_receipt(admin_id: int, channel_id: int, user_id: int, 
                                 days: int, amount: float, hidden_username: bool = True) -> dict:
    """Record a premium subscription receipt for payout tracking"""
    from datetime import datetime
    receipt = {
        'timestamp': datetime.now(),
        'user_id': user_id,
        'username': f"user_{user_id}" if hidden_username else None,
        'days': days,
        'amount': amount,
        'hidden': hidden_username,
        'receipt_id': secrets.token_hex(4).upper(),
    }
    await db.add_payout_receipt(admin_id, channel_id, receipt)
    return receipt

def format_payout_receipt_message(receipts: list, channel_name: str) -> str:
    """Format receipts into readable message"""
    if not receipts:
        return f"📊 *No receipts yet for {channel_name}*"
    
    message = f"💰 *Payout Receipts - {channel_name}*\n\n"
    message += f"📅 Last 24h Premium Subscriptions:\n\n"
    
    total_amount = 0
    total_days = 0
    
    for receipt in receipts[-10:]:
        user_display = "🔒 Hidden" if receipt.get('hidden') else f"@{receipt.get('username', 'Unknown')}"
        message += f"• {user_display} - {receipt['days']}d - ₹{receipt['amount']}\n"
        total_amount += receipt['amount']
        total_days += receipt['days']
    
    message += f"\n━━━━━━━━━━━━━━\n"
    message += f"📈 Total: {len(receipts)} subscriptions\n"
    message += f"💵 Amount: ₹{total_amount}\n"
    message += f"📅 Days: {total_days}d total\n"
    
    return message


# ── MASS OPERATION STATE TRACKING ─────────────────────────────────────────────
class MassOperationState:
    """Track state of mass operations to prevent duplicates and manage stops"""
    def __init__(self):
        self.mass_dm_active = {}  # user_id -> is_active
        self.join_requests_active = {}  # user_id -> is_active
        self.broadcast_active = {}  # user_id -> is_active
        self.operation_stats = {}  # user_id -> stats
    
    def start_mass_dm(self, user_id: int):
        """Mark mass DM as active"""
        self.mass_dm_active[user_id] = True
        self.operation_stats[user_id] = {'sent': 0, 'failed': 0, 'skipped': 0}
    
    def stop_mass_dm(self, user_id: int) -> dict:
        """Stop mass DM and get stats"""
        self.mass_dm_active[user_id] = False
        return self.operation_stats.get(user_id, {})
    
    def is_mass_dm_active(self, user_id: int) -> bool:
        """Check if mass DM is active"""
        return self.mass_dm_active.get(user_id, False)
    
    def update_stats(self, user_id: int, sent: int = 0, failed: int = 0, skipped: int = 0):
        """Update operation stats"""
        if user_id not in self.operation_stats:
            self.operation_stats[user_id] = {'sent': 0, 'failed': 0, 'skipped': 0}
        
        self.operation_stats[user_id]['sent'] += sent
        self.operation_stats[user_id]['failed'] += failed
        self.operation_stats[user_id]['skipped'] += skipped
    
    def get_stats(self, user_id: int) -> dict:
        """Get operation stats"""
        return self.operation_stats.get(user_id, {'sent': 0, 'failed': 0, 'skipped': 0})
    
    def clear_stats(self, user_id: int):
        """Clear stats"""
        self.operation_stats[user_id] = {'sent': 0, 'failed': 0, 'skipped': 0}

mass_op_state = MassOperationState()

async def cb_mass_dm_stop(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Stop ongoing mass DM operation"""
    query = update.callback_query
    user_id = query.from_user.id
    
    if not (is_primary_admin(user_id) or await db.is_extra_admin(user_id)):
        await query.answer("❌ Admin only!", show_alert=True)
        return
    
    if not mass_op_state.is_mass_dm_active(user_id):
        await query.answer("❌ No active operation!", show_alert=True)
        return
    
    # Stop the operation
    stats = mass_op_state.stop_mass_dm(user_id)
    
    await query.answer("✅ Mass DM Stopped!")
    
    status_text = (
        f"✅ *MASS DM STOPPED*\n\n"
        f"{DIVIDER}\n"
        f"Sent: *{stats.get('sent', 0)}* messages\n"
        f"Failed: *{stats.get('failed', 0)}* (blocked/deleted)\n"
        f"Skipped: *{stats.get('skipped', 0)}* (unavailable)\n\n"
        f"Total: *{stats.get('sent', 0) + stats.get('failed', 0) + stats.get('skipped', 0)}*"
    )
    
    await query.edit_message_text(
        status_text,
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("📢 Send Another", callback_data="a_broadcast")],
            [InlineKeyboardButton("🔙 Back", callback_data="a_back")],
        ])
    )

async def cb_join_request_stop(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Stop ongoing join request processing"""
    query = update.callback_query
    user_id = query.from_user.id
    
    if not (is_primary_admin(user_id) or await db.is_extra_admin(user_id)):
        await query.answer("❌ Admin only!", show_alert=True)
        return
    
    if not mass_op_state.join_requests_active.get(user_id, False):
        await query.answer("❌ No active operation!", show_alert=True)
        return
    
    # Stop the operation
    mass_op_state.join_requests_active[user_id] = False
    stats = mass_op_state.get_stats(user_id)
    
    await query.answer("✅ Join Request Processing Stopped!")
    
    status_text = (
        f"✅ *JOIN REQUESTS STOPPED*\n\n"
        f"{DIVIDER}\n"
        f"Accepted: *{stats.get('sent', 0)}* requests\n"
        f"Failed: *{stats.get('failed', 0)}*\n\n"
        f"Total Processed: *{stats.get('sent', 0) + stats.get('failed', 0)}*"
    )
    
    await query.edit_message_text(
        status_text,
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("🔙 Back", callback_data="a_back")],
        ])
    )

# ── LEADERBOARD MANAGEMENT ────────────────────────────────────────────────────
async def setup_leaderboard_for_admin(admin_id: int, channel_id: int) -> dict:
    """Setup leaderboard tracking for an admin"""
    from datetime import datetime
    leaderboard = {
        'admin_id': admin_id,
        'channel_id': channel_id,
        'created_at': datetime.now(),
        'metrics': {
            'highest_mass_dms': 0,
            'highest_join_requests': 0,
            'highest_accept_pending': 0
        }
    }
    await db.set_leaderboard(admin_id, leaderboard)
    return leaderboard

async def update_leaderboard_metrics(admin_id: int, mass_dms: int = 0,
                                    join_requests: int = 0, accept_pending: int = 0) -> dict:
    """Update daily leaderboard metrics"""
    leaderboard = await db.get_leaderboard(admin_id)
    
    if not leaderboard:
        leaderboard = await setup_leaderboard_for_admin(admin_id, None)
    
    metrics = leaderboard.get('metrics', {})
    metrics['highest_mass_dms'] = max(metrics.get('highest_mass_dms', 0), mass_dms)
    metrics['highest_join_requests'] = max(metrics.get('highest_join_requests', 0), join_requests)
    metrics['highest_accept_pending'] = max(metrics.get('highest_accept_pending', 0), accept_pending)
    
    await db.update_leaderboard_metrics(admin_id, metrics)
    return metrics

