async def handle_payout_channel_input(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Handle channel input for payout configuration."""
    if not await admin_only(update):
        return
    
    admin_id = update.effective_user.id
    channel_input = update.message.text.strip()
    
    try:
        channel_ref = _normalise_payout_channel_input(channel_input)
        chat = await ctx.bot.get_chat(channel_ref)
        try:
            await _check_payout_channel_access(ctx.bot, chat.id)
        except Exception:
            # Telegram reports both "not an administrator" and "bot is not
            # yet a member" as access errors. In either case, keep the
            # channel reference and wait for the admin to finish setup.
            bot_user = await ctx.bot.get_me()
            task_map = ctx.application.bot_data.setdefault("pending_payout_channel_tasks", {})
            old_task = task_map.get(admin_id)
            if old_task and not old_task.done():
                old_task.cancel()
            task_map[admin_id] = asyncio.create_task(
                _finish_pending_payout_channel(ctx.application, admin_id, chat.id)
            )
            await update.message.reply_text(
                f"📣 *Channel Found: {chat.title or channel_input}*\n\n"
                f"Please add @{bot_user.username or 'this bot'} to the channel as an "
                f"*administrator* and enable *Post Messages* permission.\n\n"
                f"I will automatically verify the access and confirm here once it is ready.",
                parse_mode="Markdown",
            )
            return ConversationHandler.END

        # Access is already valid: send the confirmation first, then persist
        # the resolved numeric ID so future payouts never depend on a username.
        await ctx.bot.send_message(
            chat_id=chat.id,
            text=(
                "✅ Payout channel connected successfully.\n\n"
                "The bot is an administrator and can send payout notifications."
            ),
        )
        await db.set_payout_channel(admin_id, chat.id, chat.title or str(chat.id))
        await update.message.reply_text(
            f"✅ *Payout Channel Ready*\n\n"
            f"Channel: {chat.title or channel_input}\n"
            f"Status: Verified\n\n"
            f"The *Send Payouts* button is ready to use.",
            parse_mode="Markdown",
            reply_markup=payout_menu_kb(),
        )
        return ConversationHandler.END
    except Exception as e:
        logger.error(f"Error processing channel input: {e}")
        await update.message.reply_text(
            f"✨ Could not access that channel: {e}\n\n"
            f"Send a public channel username (e.g., @channelname) or numeric channel ID "
            f"(e.g., -100123456789).",
            parse_mode="Markdown"
        )
        return PAYOUT_CHANNEL_INPUT


