async def cb_payout_confirm_send(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Confirm and send manual payout."""
    q = update.callback_query
    try:
        await q.answer()
    except Exception:
        pass
    if not await admin_only(update):
        return
    
    admin_id = update.effective_user.id
    days = ctx.user_data.get('payout_days', 1)
    amount = ctx.user_data.get('payout_amount', 0)
    
    channel = await db.get_payout_channel(admin_id)
    if not channel:
        await q.message.reply_text("✨ Payout channel not found.", reply_markup=payout_menu_kb())
        return
    
    # Send payout notification
    success = await send_payout_notification(ctx, channel['channel_id'], days, amount, "manual")
    
    if success:
        # Record the payout
        await db.record_payout(admin_id, days, amount, payment_id=None, payout_type="manual")
        for key in ("payout_admin_id", "payout_days", "payout_amount"):
            ctx.user_data.pop(key, None)
        
        await q.message.reply_text(
            f"✅ *Payout Sent Successfully*\n\n"
            f"Days: {days}\n"
            f"Amount: ₹{amount}\n"
            f"Type: Manual Payout",
            parse_mode="Markdown",
            reply_markup=payout_menu_kb()
        )
    else:
        for key in ("payout_admin_id", "payout_days", "payout_amount"):
            ctx.user_data.pop(key, None)
        await q.message.reply_text(
            "✨ Failed to send payout. Please verify channel access.",
            parse_mode="Markdown",
            reply_markup=payout_menu_kb()
        )


