async def _error_handler(update: object, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """
    IMPROVED: Recover failed admin actions without exposing internal Telegram errors.
    This no longer sends the misleading "dashboard is still active" message.
    """
    logger.error("Unhandled Admin Bot update %s: %s", update, ctx.error, exc_info=ctx.error)
    global ADMIN_USE_CUSTOM_EMOJI
    error_text = str(ctx.error or "").lower()
    
    # Only disable custom icons for an explicit custom-emoji rejection.
    # Generic BadRequest/markup errors must not silently turn off Premium icons.
    if "custom emoji" in error_text or "custom_emoji_id" in error_text:
        ADMIN_USE_CUSTOM_EMOJI = False
        try:
            await db.set_setting("admin_emoji_mode", "unicode")
        except Exception:
            pass
    
    # Send better error messages based on error type
    if isinstance(update, Update) and update.effective_user:
        uid = update.effective_user.id
        
        # Mark admin as free after error (release the cooldown lock)
        mark_admin_free(uid)
        
        q = update.callback_query
        if q is not None:
            try:
                # Provide specific error messages based on error type
                if isinstance(ctx.error, TimedOut) or "timeout" in error_text:
                    await q.answer("⏱️ Request timed out. Try again.", show_alert=False)
                elif isinstance(ctx.error, NetworkError) or "network" in error_text:
                    await q.answer("🌐 Network error. Retrying...", show_alert=False)
                elif isinstance(ctx.error, RetryAfter):
                    await q.answer("⏳ Too many requests. Wait a moment.", show_alert=False)
                elif isinstance(ctx.error, Forbidden) or "not allowed" in error_text:
                    await q.answer("❌ Permission denied. Contact admin.", show_alert=True)
                elif isinstance(ctx.error, BadRequest):
                    await q.answer("⚠️ Invalid request. Try again.", show_alert=False)
                else:
                    await q.answer("Try again in a moment.", show_alert=False)
            except Exception as e:
                logger.debug(f"Could not send callback answer: {e}")


