async def handle_user_premium_uid(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Handle user ID input and display/modify premium status."""
    if not await admin_only(update):
        return ConversationHandler.END
    
    try:
        user_id = int(update.message.text.strip())
    except ValueError:
        await update.message.reply_text("❌ *Invalid User ID* — Please enter a valid number.")
        return USER_PREMIUM_UID_INPUT
    
    # Get user's premium info
    premium = await db.get_premium(user_id)
    user = await db.get_user(user_id)
    
    if not user:
        await update.message.reply_text(
            f"❌ *User Not Found*\n\nNo user with ID `{user_id}` in system.",
            parse_mode="Markdown",
            reply_markup=edit_menu_kb(),
        )
        return ConversationHandler.END
    
    # Calculate premium info
    from datetime import datetime
    
    if premium and premium.get("is_active"):
        starts = premium.get("starts_at", "N/A")
        expires = premium.get("expires_at", "N/A")
        plan = premium.get("plan_key", "unknown")
        total_days = premium.get("days", 0)
        amount = premium.get("amount_paid", 0)
        
        # Parse dates
        try:
            if isinstance(expires, str):
                exp_dt = datetime.fromisoformat(expires.replace('Z', '+00:00'))
                now_dt = datetime.now(exp_dt.tzinfo) if exp_dt.tzinfo else datetime.now()
                remaining_days = max(0, (exp_dt - now_dt).days)
            else:
                remaining_days = 0
        except:
            remaining_days = 0
        
        # Determine purchase source
        source = "Payment" if amount > 0 else "Redeem Code"
        
        status = "✅ ACTIVE"
        info_line = f"Expires: {expires}"
    else:
        remaining_days = 0
        total_days = 0
        status = "⭐ FREE"
        info_line = "Status: No active premium"
        source = "N/A"
    
    ctx.user_data['premium_user_id'] = user_id
    ctx.user_data['premium_remaining'] = remaining_days
    ctx.user_data['premium_total'] = total_days
    
    info_text = (
        f"👥 *Premium Status for User {user_id}*\n\n"
        f"{'━' * 40}\n"
        f"Status: *{status}*\n"
        f"Days Remaining: *{remaining_days}*\n"
        f"Total Days: *{total_days}*\n"
        f"{info_line}\n"
        f"{'━' * 40}\n\n"
        f"*What would you like to do?*"
    )
    
    await update.message.reply_text(
        info_text,
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("➕ Add Days", callback_data="premium_add"),
             InlineKeyboardButton("➖ Remove Days", callback_data="premium_deduct")],
            [cancel_button("⬅️ Back", callback_data="a_edit")],
        ]),
    )
    return USER_PREMIUM_ACTION_SELECT


