async def cb_start_giveaway(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not await admin_only(update):
        return ConversationHandler.END
    await q.answer()
    recent = await db.get_giveaway_history(5)
    pending = next((g for g in recent if str(g.get("status")) in ("active", "stopped")), None)
    if pending:
        state = "running" if str(pending.get("status")) == "active" else "stopped and awaiting winner selection/cancellation"
        await q.message.reply_text(
            f"⚠️ A giveaway is already {state}.\n\n"
            "Finish the current giveaway first, then start a new one."
        )
        return ConversationHandler.END
    ctx.user_data["gw_draft"] = {}
    await q.message.reply_text(
        "🎉 *CHOOSE GIVEAWAY TYPE*\n\n"
        "Select how winners will be selected:",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("🎲 Random Winner", callback_data="a_gw_type_random")],
            [InlineKeyboardButton("🔗 Invite Link", callback_data="a_gw_type_invite")],
            [InlineKeyboardButton("🔙 Back to Dashboard", callback_data="a_back")],
        ]),
    )
    return GIVEAWAY_TYPE_INPUT


async def handle_giveaway_type(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not await admin_only(update):
        return ConversationHandler.END
    await q.answer()
    typ = str(q.data).rsplit("_", 1)[-1]
    if typ not in ("random", "invite"):
        await q.answer("Invalid type.", show_alert=True)
        return GIVEAWAY_TYPE_INPUT
    ctx.user_data.setdefault("gw_draft", {})["giveaway_type"] = typ
    await q.message.edit_text(
        "🎉 *START GIVEAWAY*\n\n"
        "Step 1/4 — Send the *Giveaway Name*.\n\n"
        "Example: Diwali Mega Giveaway",
        parse_mode="Markdown",
    )
    return GIVEAWAY_NAME_INPUT


async def handle_giveaway_duration(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    raw = (update.message.text or "").strip()
    delta = _gw_parse_duration(raw)
    if delta is None:
        await update.message.reply_text(
            "❌ Invalid duration. Use formats like `10m`, `1h`, `6h`, `12h`, `1d`, `3d`, or `7d`.",
            parse_mode="Markdown",
        )
        return GIVEAWAY_DURATION_INPUT
    draft = ctx.user_data.setdefault("gw_draft", {})
    draft["duration"] = raw
    draft["ends_at"] = (datetime.now(timezone.utc) + delta).strftime("%Y-%m-%d %H:%M:%S")
    type_label = "🔗 Invite Link" if draft.get("giveaway_type") == "invite" else "🎲 Random Winner"
    preview = (
        "╔════════════════════════════╗\n"
        "       🎉 *GIVEAWAY PREVIEW* 🎉\n"
        "╚════════════════════════════╝\n\n"
        f"🎯 *GIVEAWAY TYPE*\n{type_label}\n\n"
        f"🎉 *GIVEAWAY NAME*\n{draft['name']}\n\n"
        f"🎁 *PRIZE*\n{draft['prize']}\n\n"
        f"🏆 *TOTAL WINNERS*\n{draft['winners_count']}\n\n"
        f"⏰ *GIVEAWAY TILL*\n{draft['ends_at']} UTC\n"
    )
    await update.message.reply_text(
        preview, parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("🚀 START GIVEAWAY", callback_data="a_gw_start")],
            [InlineKeyboardButton("✏️ EDIT", callback_data="a_gw_edit"),
             InlineKeyboardButton("❌ CANCEL", callback_data="a_gw_cancel")],
        ]),
    )
    return ConversationHandler.END


async def cb_giveaway_preview_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not await admin_only(update):
        return
    await q.answer()
    draft = ctx.user_data.get("gw_draft") or {}
    required = ("name", "prize", "winners_count", "ends_at", "giveaway_type")
    if any(k not in draft for k in required):
        await q.message.reply_text("❌ Giveaway draft expired. Tap Start Giveaway and create it again.")
        return
    if await db.get_active_giveaway():
        await q.message.reply_text("⚠️ A giveaway is already running. Stop it before starting another.")
        return
    typ = draft["giveaway_type"]
    invite_username = ""
    if typ == "invite":
        try:
            me = await q.get_bot().get_me()
            invite_username = me.username or ""
        except Exception:
            try:
                me = await ctx.bot.get_me()
                invite_username = me.username or ""
            except Exception:
                invite_username = ""
        if not invite_username:
            await q.message.reply_text("❌ Could not determine the bot username for the invite link.")
            return

    gw = await db.create_giveaway(
        draft["name"], draft["prize"], int(draft["winners_count"]), draft["ends_at"],
        int(update.effective_user.id), typ, invite_username
    )
    ctx.user_data.pop("gw_draft", None)
    type_label = "🔗 Invite Link" if typ == "invite" else "🎲 Random Winner"
    text = (
        "🎉 *NEW GIVEAWAY STARTED* 🎉\n\n"
        f"🎯 *GIVEAWAY TYPE:* {type_label}\n"
        f"🎉 *GIVEAWAY NAME:* {gw['name']}\n"
        f"🎁 *PRIZE:* {gw['prize']}\n"
        f"🏆 *TOTAL WINNERS:* {gw['winners_count']}\n"
        f"⏰ *GIVEAWAY TILL:* {str(gw['ends_at'])[:19]} UTC\n\n"
        "👇 Tap *PARTICIPATE* to enter!"
    )
    kb = InlineKeyboardMarkup([[InlineKeyboardButton("🎉 PARTICIPATE", callback_data=f"gw_join_{gw['id']}")]])
    sent = failed = 0
    try:
        users = await db.get_all_users()
        outbot = Bot(BOT_TOKEN)
        try:
            for row in users:
                try:
                    await outbot.send_message(chat_id=int(row["user_id"]), text=text, parse_mode="Markdown", reply_markup=kb)
                    sent += 1
                except Exception:
                    failed += 1
                await asyncio.sleep(0.02)
        finally:
            await outbot.shutdown()
    except Exception as exc:
        logger.warning("giveaway start broadcast failed: %s", exc)

    await q.message.edit_text(
        f"✅ *GIVEAWAY STARTED*\n\n{text}\n\n📢 Broadcast: *{sent}* sent | *{failed}* failed",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("👥 See Participants", callback_data="a_gw_active")],
            [InlineKeyboardButton("⏹ Stop Giveaway", callback_data=f"a_gw_stop_{gw['id']}")],
            [InlineKeyboardButton("🔙 Back to Dashboard", callback_data="a_back")],
        ]),
    )


async def cb_giveaway_active(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q=update.callback_query
    if not await admin_only(update): return
    await q.answer("Refreshing participants…")
    gw=await db.get_active_giveaway()
    if not gw:
        await q.message.edit_text("ℹ️ No active giveaway.", reply_markup=admin_menu_kb(is_primary=True))
        return
    gid=int(gw["id"])
    count=await db.get_giveaway_entry_count(gid)
    typ=str(gw.get("giveaway_type") or "random")
    type_label="🔗 Invite Link" if typ=="invite" else "🎲 Random Winner"
    text=(
        "🎉 *ACTIVE GIVEAWAY*\n\n"
        f"🎯 Type: *{type_label}*\n"
        f"🎉 Name: *{gw['name']}*\n"
        f"🎁 Prize: *{gw['prize']}*\n"
        f"🏆 Winners: *{gw['winners_count']}*\n"
        f"👥 Participants: *{count}*\n"
        f"⏰ Till: *{str(gw['ends_at'])[:19]} UTC*"
    )
    if typ=="invite":
        board=await db.get_giveaway_referral_leaderboard(gid)
        text += "\n\n📊 *TOP REFERRERS*\n"
        if board:
            text += "\n".join(f"{i}. {('@'+r['username']) if r.get('username') else r['referrer_id']} — {r['referrals']} referrals"
                              for i,r in enumerate(board[:10],1))
        else:
            text += "No referrals yet."
    await q.message.edit_text(text,parse_mode="Markdown",reply_markup=InlineKeyboardMarkup([
        [InlineKeyboardButton("🔄 See Participants / Refresh", callback_data="a_gw_active")],
        [InlineKeyboardButton("⏹ Stop Giveaway", callback_data=f"a_gw_stop_{gid}")],
        [InlineKeyboardButton("🔙 Back to Dashboard", callback_data="a_back")],
    ]))


async def cb_giveaway_stop(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q=update.callback_query
