# ── Force Join: Add Channel (public or private) ──────────────────────────────
# 1. Admin taps Add Channel and makes the user bot an admin in the channel.
# 2. The user bot verifies the channel automatically (my_chat_member update).
# 3. Admin sends the invite link. It is saved together with the verified chat ID.
async def cb_channel_add(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    if not await admin_only(update):
        return ConversationHandler.END
    uid = update.effective_user.id
    await db.set_fj_waiting(uid, True)
    await db.clear_fj_verified(uid)
    await q.message.reply_text(
        "*Add Channel*\n\n"
        "1. Add the user bot as an *administrator* in your channel (public or private), "
        "and enable *Invite Users via Link*.\n"
        f"Bot: @{BOT_USERNAME}\n\n"
        "2. The bot verifies the channel automatically and will message you.\n"
        "3. Then send the channel's invite link here.\n\n"
        "Send /cancel to stop.",
        parse_mode="Markdown")
    return EDIT_CHANNEL_ADD_INPUT


async def handle_channel_add(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not await admin_only(update):
        return ConversationHandler.END
    uid = update.effective_user.id
    raw = (update.message.text or "").strip()
    if not raw:
        return EDIT_CHANNEL_ADD_INPUT
    try:
        verified = await db.get_fj_verified(uid)
        if not verified:
            if await db.is_fj_waiting(uid):
                await update.message.reply_text(
                    "Add the user bot as an administrator in your channel first. "
                    "The bot verifies it automatically.")
            else:
                await update.message.reply_text("Tap *Add Channel* first.", parse_mode="Markdown")
            return EDIT_CHANNEL_ADD_INPUT
        key = db.normalize_channel_input(raw)
        is_private = db._is_private_channel_link(raw)
        is_public = bool(re.fullmatch(r"[A-Za-z0-9_]{4,}", key))
        if not (is_private or is_public):
            await update.message.reply_text(
                "Please send the invite link (https://t.me/+...) or the public username (@channel).")
            return EDIT_CHANNEL_ADD_INPUT
        channels = await db.add_force_join_channel(key)
        await db.set_force_join_chat_id(key, int(verified["chat_id"]))
        await db.clear_fj_verified(uid)
        await db.set_fj_waiting(uid, False)
        await update.message.reply_text(
            f"✅ *Channel added successfully!* ({verified.get('title', '')})\n\n"
            + "\n".join(f"• {_channel_display_label(c)}" for c in channels)
            + "\n\nTap *Add Channel* to add another channel.",
            parse_mode="Markdown", reply_markup=channels_menu_kb())
    except Exception as exc:
        logger.exception("force join channel add failed: %s", exc)
        await update.message.reply_text(
            "❌ Could not add this channel. Try again.", reply_markup=channels_menu_kb())
    return ConversationHandler.END
