class _VerifiedCallbackQueryHandler(_TelegramCallbackQueryHandler):
    """Gate every user callback behind the one-time human verification.

    Verification callbacks themselves (``hv_``) are exempt.  Once a user is
    verified, the wrapped callback runs normally.
    """
    def __init__(self, callback, *args, **kwargs):
        async def _guarded(update, ctx):
            q = getattr(update, "callback_query", None)
            user = getattr(update, "effective_user", None)
            if q is None or user is None:
                return await callback(update, ctx)
            data = q.data or ""
            if str(data).startswith("hv_") or user.id == ADMIN_TG_ID:
                return await callback(update, ctx)
            try:
                verified = await db.is_human_verified(user.id)
            except Exception:
                verified = False
            if not verified:
                await _send_human_verification(update, ctx, replace=True)
                try:
                    await q.answer("Human verification required", show_alert=True)
                except Exception:
                    pass
                return None
            return await callback(update, ctx)
        _guarded.__name__ = getattr(callback, "__name__", "callback")
        super().__init__(_guarded, *args, **kwargs)

CallbackQueryHandler = _VerifiedCallbackQueryHandler

