# ── Telegram custom-emoji transport ──────────────────────────────────────────
# The project historically used strings such as ``emoji_123...`` as if they
# were Telegram markup.  Telegram treats those as ordinary text.  Normalize
# them at the Bot API boundary so every existing screen gets real custom
# emoji entities without requiring fragile, one-off edits to hundreds of
# message calls.
def _strip_custom_emoji_markup(markup):
    """Return a copy of inline/reply markup without custom-emoji icon IDs."""
    if markup is None:
        return None
    try:
        if hasattr(markup, "inline_keyboard"):
            rows = []
            for row in markup.inline_keyboard:
                new_row = []
                for button in row:
                    data = button.to_dict()
                    data.pop("icon_custom_emoji_id", None)
                    new_row.append(InlineKeyboardButton(**data))
                rows.append(new_row)
            return InlineKeyboardMarkup(rows)
    except Exception:
        return markup
    return markup


def _install_custom_emoji_transport() -> None:
    if getattr(Bot, "_forward_dms_custom_emoji_transport", False):
        return

    method_fields = {
        "send_message": (1, "text"),
        "send_photo": (2, "caption"),
        "edit_message_text": (2, "text"),
        "edit_message_caption": (2, "caption"),
    }

    for method_name, (position, field_name) in method_fields.items():
        original = getattr(Bot, method_name, None)
        if original is None:
            continue

        async def _wrapped(
            self, *args, __original=original, __position=position,
            __field_name=field_name, **kwargs
        ):
            # Messages that already carry their own entities (Premium Post Maker
            # previews and posts) must reach Telegram exactly as built. Rewriting
            # their text here drops the formatting and the custom emoji.
            if kwargs.get("entities") or kwargs.get("caption_entities"):
                return await __original(self, *args, **kwargs)
            values = list(args)
            original_values = list(args)
            original_kwargs = dict(kwargs)
            changed = False
            if __field_name in kwargs:
                value = kwargs.get(__field_name)
                rendered, rendered_mode = render_custom_emoji_message(
                    value, kwargs.get("parse_mode")
                )
                if rendered != value:
                    kwargs[__field_name] = rendered
                    kwargs["parse_mode"] = rendered_mode
                    changed = True
            elif len(values) > __position:
                rendered, rendered_mode = render_custom_emoji_message(
                    values[__position], kwargs.get("parse_mode")
                )
                if rendered != values[__position]:
                    values[__position] = rendered
                    kwargs["parse_mode"] = rendered_mode
                    changed = True
            try:
                return await __original(self, *values, **kwargs)
            except TelegramError as exc:
                # If the owner is not Premium (or the supplied custom emoji is
                # otherwise rejected), transparently retry once with the exact
                # original Unicode text and button markup stripped of custom
                # emoji icons. This preserves the requested Unicode fallback.
                err = str(exc).lower()
                custom_error = any(token in err for token in (
                    "custom emoji", "custom_emoji", "premium",
                    "emoji-id", "emoji id", "entity_text_invalid",
                ))
                if not changed or not custom_error:
                    raise
                fallback_kwargs = dict(original_kwargs)
                if "reply_markup" in fallback_kwargs:
                    fallback_kwargs["reply_markup"] = _strip_custom_emoji_markup(
                        fallback_kwargs.get("reply_markup")
                    )
                return await __original(self, *original_values, **fallback_kwargs)

        setattr(Bot, method_name, _wrapped)

    Bot._forward_dms_custom_emoji_transport = True


_install_custom_emoji_transport()

