def get_image_bytes(name: str) -> BytesIO:
    """Load one of the bundled images without a separate Python data module."""
    filenames = {
        "welcome": "welcome.jpg",
        "qr": "payment_qr.jpg",
    }
    filename = filenames.get(name)
    if not filename:
        raise KeyError(f"Unknown asset: {name!r}. Available: {list(filenames)}")
    path = os.path.join(os.path.dirname(__file__), "assets", filename)
    with open(path, "rb") as image_file:
        return BytesIO(image_file.read())


