# ── Helpers ───────────────────────────────────────────────────────────────────
def _fmt_remaining(delta) -> str:
    """Format a timedelta into a human-readable remaining-time string."""
    total_secs = max(0, int(delta.total_seconds()))
    days  = total_secs // 86400
    hours = (total_secs % 86400) // 3600
    mins  = (total_secs % 3600) // 60
    if days > 0:
        return f"{days}d {hours}h {mins}m"
    if hours > 0:
        return f"{hours}h {mins}m"
    return f"{mins}m"


async def _premium_badge(user_id: int) -> str:
    is_active = await db.check_premium_active(user_id)
    if not is_active:
        return "🆓 Free Plan"
    prem = await db.get_premium(user_id)
    if prem:
        try:
            exp = datetime.fromisoformat(prem["expires_at"])
            now = datetime.now(timezone.utc).replace(tzinfo=None)
            delta = exp - now
            if delta.total_seconds() <= 0:
                return "emoji_5454415424319931791️ Premium Expired"
            return f"emoji_5472239203590888751 VIP Premium — {_fmt_remaining(delta)} left"
        except Exception:
            return "emoji_5472239203590888751 VIP Premium"
    return "emoji_5472239203590888751 VIP Premium"


