# ── Premium Expiry Background Checker ─────────────────────────────────────────
async def _premium_expiry_checker(app):
    """
    Runs every 60 seconds.  Finds users whose premium just expired, marks them
    as notified (and revokes is_active) in one atomic DB call, then sends each
    user an expiry notification with a ⭐ Go Premium renewal button.
    """
    logger.info("Premium expiry checker started.")
    while True:
        try:
            expired_rows = await db.get_users_to_notify_expired()
            for row in expired_rows:
                user_id  = row["user_id"]
                plan_key = row.get("plan_key", "unknown")
                days     = row.get("days", 0)
                amt      = row.get("amount_paid", 0)

                # Determine display label for the expired plan
                all_plans = _PLANS_CACHE or {}
                plan_info = all_plans.get(plan_key, {})
                plan_label = plan_info.get("label") or (
                    "Unlimited (Lifetime)" if days >= 999 else f"{days} Day{'s' if days != 1 else ''}"
                )

                # Price line: use stored amount_paid if available, else current plan price
                if amt and float(amt) > 0:
                    price_line = f"₹{float(amt):.0f} (price you paid)"
                elif plan_info.get("price"):
                    price_line = f"₹{plan_info['price']} (current price)"
                else:
                    price_line = "N/A"

                text = (
                    f"⏰ *Your Premium Has Expired*\n\n"
                    f"{DIVIDER}\n"
                    f"emoji_5447410659077661506 Plan: *{plan_label}*\n"
                    f"emoji_6120625823285251747 Price: {price_line}\n"
                    f"{DIVIDER}\n\n"
                    "Your VIP Premium subscription has ended.\n"
                    "Renew now to keep sending unlimited DMs! emoji_5472239203590888751"
                )
                kb = InlineKeyboardMarkup([
                    [vip_button("💎 Go Premium", callback_data="cb_premium")],
                ])
                try:
                    await app.bot.send_message(
                        chat_id=user_id,
                        text=text,
                        parse_mode="Markdown",
                        reply_markup=kb,
                    )
                    logger.info("Sent expiry notification to user %s (plan=%s)", user_id, plan_key)
                except Exception as notify_err:
                    logger.warning("Could not notify user %s about expiry: %s", user_id, notify_err)
        except Exception as e:
            logger.warning("Premium expiry checker error: %s", e)

        await asyncio.sleep(60)


