# ── Personalized welcome helpers ─────────────────────────────────────────────
def _escape_markdown_v1(value: str) -> str:
    """Escape Telegram Markdown-v1 special characters in user-provided text."""
    text = str(value or "").strip()
    for ch in ("\\", "_", "*", "[", "`"):
        text = text.replace(ch, "\\" + ch)
    return text


def _personalize_welcome_text(template: str, user) -> str:
    """Replace the old placeholders with the actual Telegram user's details."""
    full_name = getattr(user, "full_name", None) or getattr(user, "username", None) or "User"
    user_name = _escape_markdown_v1(full_name)
    user_id = str(getattr(user, "id", ""))

    return (
        template
        .replace("*👤 USER NAME*", f"*👤 {user_name}*")
        .replace("*🆔 USER ID: 123456789*", f"*🆔 USER ID: {user_id}*")
        .replace("*🖥️ SERVER: ACTIVE*", "*🖥️ NODE: ACTIVE*")
    )


# ── One-time Human Verification ──────────────────────────────────────────────
_VERIFICATION_EMOJIS = {
    "clown": "🤡", "party": "🥳", "trophy": "🏆",
    "heart": "❤️", "money": "💵", "check": "✅",
}
_VERIFICATION_TARGETS = tuple(_VERIFICATION_EMOJIS.keys())
_VERIFICATION_TTL = 10 * 60

def _verification_image_path(target_key: str) -> str:
    return os.path.join(os.path.dirname(__file__), "assets", "verification", f"{target_key}.png")

async def _send_human_verification(update: Update, ctx: ContextTypes.DEFAULT_TYPE, replace: bool = False):
    user = update.effective_user
    if not user or int(user.id) == int(ADMIN_TG_ID):
        return
    if await db.is_human_verified(user.id):
        return
    target_key = secrets.choice(_VERIFICATION_TARGETS)
    target = _VERIFICATION_EMOJIS[target_key]
    options = list(_VERIFICATION_EMOJIS.values())
    secrets.SystemRandom().shuffle(options)
    token = secrets.token_urlsafe(8)
    # Store the complete challenge in memory and DB settings are deliberately
    # avoided; the challenge only needs to survive the current bot process.
    # A short per-user context value prevents old buttons from being reused.
    ctx.user_data["human_verification"] = {"token": token, "target": target, "target_key": target_key, "options": options, "expires": time.time() + _VERIFICATION_TTL}
    # Verification choices must display the six actual Unicode emojis.
    # Do NOT route these through user_button(): that helper intentionally
    # strips a leading emoji to use Telegram's custom-emoji icon field, which
    # would turn a label containing only an emoji into the literal fallback
    # text "Button".
    rows = []
    for i in range(0, 6, 3):
        row = []
        for j in range(i, i + 3):
            row.append(InlineKeyboardButton(
                options[j],
                callback_data=f"hv_{token}_{j}",
                style="success",
            ))
        rows.append(row)
    text = (
        "🛡️ *HUMAN VERIFICATION REQUIRED* ✅\n\n"
        "🔐 To keep this bot safe from automated and spam activity, "
        "please complete this quick verification.\n\n"
        f"🎯 *Tap the emoji shown in the image:*\n\n"
        f"{target}\n\n"
        "⚡ This verification is required *only once* for your account."
    )
    msg = update.effective_message
    try:
        with open(_verification_image_path(target_key), "rb") as photo:
            await msg.reply_photo(photo=photo, caption=text, parse_mode="Markdown", reply_markup=InlineKeyboardMarkup(rows))
    except Exception:
        await msg.reply_text(text, parse_mode="Markdown", reply_markup=InlineKeyboardMarkup(rows))

async def cb_human_verification(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    user = update.effective_user
    if not q or not user:
        return
    if int(user.id) == int(ADMIN_TG_ID):
        await q.answer("Admin bypass enabled")
        return
    # A user may interact with a callback before ever sending /start.
    # Ensure the user row exists so the one-time verified flag can persist.
    try:
        await db.upsert_user(user.id, username=user.username or "", telegram_premium=1 if getattr(user, "is_premium", False) else 0)
    except Exception:
        pass
    challenge = ctx.user_data.get("human_verification") or {}
    parts = str(q.data or "").split("_", 2)
    token = parts[1] if len(parts) > 1 else ""
    selected_index = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else -1
    # Reconstruct the randomized six options deterministically from the
    # callback's stored order so a stale callback cannot guess the target.
    # We store the actual option list in the same context entry.
    options = challenge.get("options")
    if not options:
        # Backward-safe fallback for a challenge generated before this field.
        options = list(_VERIFICATION_EMOJIS.values())
    if token != challenge.get("token") or time.time() > float(challenge.get("expires", 0)) or selected_index not in range(6):
        await q.answer("⚠️ Challenge expired. New verification sent.", show_alert=True)
        await _send_human_verification(update, ctx, replace=True)
        return
    selected = options[selected_index]
    if selected != challenge.get("target"):
        await q.answer("❌ Wrong emoji", show_alert=True)
        await _send_human_verification(update, ctx, replace=True)
        return
    await db.set_human_verified(user.id, True)
    ctx.user_data.pop("human_verification", None)
    await q.answer("✅ Human verification successful")
    # Referral is finalized only after force-join succeeds. If no force-join
    # channels are configured, this is the point at which the start counts.
    # Continue into the existing force-join gate. Verification itself never
    # grants channel membership and never runs twice for the same user.
    pending = await _check_force_join(ctx.bot, user.id)
    if pending:
        rows = [[channel_join_button(ch["label"], url=ch["url"])] for ch in pending]
        rows.append([channels_joined_button("I've Joined All", callback_data="cb_check_joined")])
        await q.message.reply_text(
            "📢 *Channel Membership Required*\n\n"
            "You must join all required channels to continue.\n"
            "After joining every channel, tap *I've Joined All*.",
            parse_mode="Markdown", reply_markup=InlineKeyboardMarkup(rows),
        )
        return
    if await _send_first_time_tutorial(update, ctx):
        return
    await q.message.reply_text(
        f"👋 *Welcome, {html.escape(user.first_name or 'User')}!*\n\n"
        "✅ Human verification completed.\n\nChoose an option below:",
        parse_mode="Markdown", reply_markup=await get_main_menu_kb(),
    )

async def _send_giveaway_deeplink_screen(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> bool:
    """Consume a shared giveaway deep-link and show the live giveaway."""
    arg = (ctx.user_data or {}).get("pending_gw_ref")
    if not arg or not str(arg).startswith("gwref_"):
        return False
    try:
        parts = str(arg).split("_")
        gid = int(parts[1]) if len(parts) == 3 else 0
    except Exception:
        gid = 0
    ctx.user_data.pop("pending_gw_ref", None)
    if gid <= 0:
        return False
    gw = await db.get_active_giveaway()
    if not gw or int(gw.get("id") or 0) != gid:
        await update.effective_message.reply_text(
            "ℹ️ *NO GIVEAWAYS ARE CURRENTLY ACTIVE*\n\n"
            "This giveaway link has expired or the giveaway has already ended.",
            parse_mode="Markdown",
        )
        return True
    try:
        ends = datetime.strptime(str(gw.get("ends_at", ""))[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
        if ends.timestamp() <= time.time():
            await update.effective_message.reply_text("ℹ️ *NO GIVEAWAYS ARE CURRENTLY ACTIVE*", parse_mode="Markdown")
            return True
    except Exception:
        pass
    participants = await db.get_giveaway_entry_count(gid)
    gtype = str(gw.get("giveaway_type") or "random").lower()
    type_label = "Invite Link" if gtype == "invite" else "Random Winner"
    text = (
        "🎉 *LIVE GIVEAWAY* 🎉\n\n"
        f"🎁 *NAME:* {gw.get('name','')}\n"
        f"🏆 *PRIZE:* {gw.get('prize','')}\n"
        f"👥 *TOTAL PARTICIPANTS:* {participants}\n"
        f"🏅 *WINNERS:* {int(gw.get('winners_count') or 0)}\n"
        f"⏰ *ENDS:* {str(gw.get('ends_at',''))[:19]} UTC\n"
        f"🎯 *TYPE:* {type_label}\n\n"
        "Tap *PARTICIPATE* to join this giveaway."
    )
    await update.effective_message.reply_text(
        text, parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [user_button("🎉 PARTICIPATE", callback_data=f"gw_join_{gid}")],
            [user_button("🎮 Play & Win", callback_data="cb_play_win")],
        ])
    )
    return True


# ── /start ────────────────────────────────────────────────────────────────────
async def cmd_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """
    Send personalized welcome with user's own profile picture.

    The primary admin must never enter the normal USER /start flow.
    In the single-bot architecture /start from the admin account is routed
    to the Admin Dashboard, so the admin account cannot accidentally receive
    both the user menu and the admin panel.
    """
    user = update.effective_user

    # SINGLE-BOT ADMIN/USER MODE:
    # /start explicitly switches the primary admin account back to USER MODE.
    # This is critical because the same Telegram account can use both the
    # Admin Dashboard and the normal User Panel in one bot.
    try:
        if ctx.user_data is not None:
            ctx.user_data["__single_bot_mode"] = "user"
    except Exception:
        pass

    # The admin is ALSO a normal user of this same bot.  Therefore /start
    # MUST enter the normal USER panel for the admin account.  The ADMIN
    # dashboard is intentionally available only through /admin.
    #
    # Do not add any admin bypass here: the normal user flow must run for
    # ADMIN_TG_ID exactly like it does for every other user.  The user-side
    # callback guard already allows the admin to use the user panel.

    logger.info(f"✅ /START COMMAND RECEIVED from user_id={user.id}, username={user.username}")
    
    try:
        await _sync_user_emoji_context()
    except Exception as e:
        logger.warning("emoji sync failed: %s", e)

    async def _do_start():
        # 1. Persist user
        try:
            await db.upsert_user(user.id, username=user.username or "", telegram_premium=1 if getattr(user, "is_premium", False) else 0)
            logger.info(f"✅ User {user.id} added/updated in database")
        except Exception as e:
            logger.warning("upsert_user failed for %s: %s", user.id, e)

        # Giveaway invite deep-link is held until the user completes human verification
        # and the force-join gate (so only genuinely verified starts count).
        try:
            if ctx.args and str(ctx.args[0]).startswith("gwref_"):
                ctx.user_data["pending_gw_ref"] = str(ctx.args[0])
        except Exception:
            pass

        # 2. One-time human verification gate. Existing users from older
        # database versions also start as unverified and complete it once.
        if int(user.id) != int(ADMIN_TG_ID) and not await db.is_human_verified(user.id):
            await _send_human_verification(update, ctx)
            return

        # 3. Maintenance gate
        try:
            if await _check_maintenance(update):
                return
        except Exception as e:
            logger.warning("maintenance check failed: %s", e)

        # 3. Referral deep-link / Giveaway invite deep-link
        if ctx.args:
            arg = ctx.args[0]
            if arg.startswith("ref_"):
                try:
                    referrer_id = int(arg[4:])
                    if referrer_id != user.id:
                        await db.set_referral(user.id, referrer_id)
                except Exception:
                    pass
            elif arg.startswith("gwref_"):
                ctx.user_data["pending_gw_ref"] = arg

        # 4. Ban check
        try:
            if not await ensure_not_banned(update):
                logger.info(f"User {user.id} is banned - returning from start")
                return
        except Exception as e:
            logger.warning("ban check failed: %s", e)

        # 5. Force-join check
        try:
            pending_channels = await _check_force_join(ctx.bot, user.id)
            if pending_channels:
                rows = [[channel_join_button(ch["label"], url=ch["url"])] for ch in pending_channels]
                rows.append([channels_joined_button("I've Joined All", callback_data="cb_check_joined")])
                await update.message.reply_text(
                    "emoji_5249050854392091366 *Channel Membership Required*\n\n"
                    f"{DIVIDER}\n"
                    "You must join all channels below to use this bot.\n"
                    "After joining *every* channel, tap *I've Joined All*:",
                    parse_mode="Markdown",
                    reply_markup=InlineKeyboardMarkup(rows),
                )
                return
        except Exception as e:
            logger.warning("force-join check failed: %s", e)

        # First-time users get the tutorial intro BEFORE the normal main menu.
        # Once skipped/completed, subsequent /start calls go straight to the main menu.
        try:
            if await _send_first_time_tutorial(update, ctx):
                return
        except Exception as e:
            logger.warning("first-time tutorial gate failed: %s", e)

        # Giveaway invite counts only after human verification + force-join gate.
        try:
            await _record_pending_giveaway_referral(user.id, ctx)
        except Exception as exc:
            logger.warning("giveaway referral recording after gates failed: %s", exc)

        # Shared giveaway links open the live giveaway after verification.
        try:
            if await _send_giveaway_deeplink_screen(update, ctx):
                return
        except Exception as exc:
            logger.warning("giveaway deep-link screen failed for %s: %s", user.id, exc)

        # 6. Load session
        try:
            await userbot.load_existing_session(user.id)
        except Exception as e:
            logger.warning("load_existing_session failed for %s: %s", user.id, e)

        # 7. Build welcome text
        try:
            acc = await db.get_account(user.id)
            stats = await db.get_stats(user.id) or {}
            badge = await _premium_badge(user.id)
            custom_welcome = await db.get_setting("welcome_text", "")
        except Exception as e:
            logger.warning("DB reads in cmd_start failed: %s", e)
            acc, stats, badge, custom_welcome = None, {}, "🆓 Free", ""

        # Use custom welcome text or default
        if custom_welcome:
            text = custom_welcome
        else:
            text = (
                "*👋 WELCOME TO DM BOT*\n\n"
                "*👤 USER NAME*\n"
                "*🆔 USER ID: 123456789*\n"
                "*🖥️ SERVER: ACTIVE*\n\n"
                "*🚀 MANAGE YOUR TELEGRAM ACCESS IN ONE CLICK*\n\n"
                "*📋 FEATURES :-*\n\n"
                "*⏹️ MASS DM FORWARDER*\n"
                "*⭐ JOIN REQUEST DM*\n"
                "*📢 ADS FOR CHATS & CHANNELS*\n"
                "*🤖 AUTO REPLY*\n"
                "*📣 CHANNEL PROMOTION*\n\n"
                "*👤 100 DMs + 100 JOIN REQUEST DMs*\n"
                "*🎁 COMPLETELY FREE*\n\n"
                "*📢 ADS & AUTO REPLY — FREE*"
            )

        # Replace placeholders with the real Telegram user's name and ID.
        # Also display NODE: ACTIVE instead of the old SERVER label.
        text = _personalize_welcome_text(text, user)

        # 8. Fetch user's profile picture
        photo_sent = False
        try:
            # Get user's profile photos
            photos = await ctx.bot.get_user_profile_photos(user.id, limit=1)
            if photos.photos:
                # Get the largest available photo
                photo_file = photos.photos[0][-1]  # last item is the largest
                await update.message.reply_photo(
                    photo=photo_file.file_id,
                    caption=text,
                    parse_mode="Markdown",
                    reply_markup=await get_main_menu_kb(),
                )
                photo_sent = True
                logger.info(f"✅ Welcome photo sent to user {user.id}")
        except Exception as e:
            logger.warning(f"Failed to send user profile photo: {e}")
        
        # If photo failed, send text + buttons
        if not photo_sent:
            try:
                await update.message.reply_text(
                    text,
                    parse_mode="Markdown",
                    reply_markup=await get_main_menu_kb()
                )
                logger.info(f"✅ Welcome text sent to user {user.id}")
            except Exception:
                pass

    try:
        await _do_start()
    except Exception as e:
        logger.error("cmd_start unhandled error for %s: %s", user.id, e)
        # Send error response if _do_start crashed
        try:
            await update.message.reply_text(
                "emoji_5337312745857501717 *Something went wrong*\n\n"
                f"{DIVIDER}\n"
                "Please try /start again or contact support.",
                parse_mode="Markdown",
            )
        except Exception:
            pass


