async def cb_check_joined(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Robust force-join verification: membership failures are isolated per channel
    and successful verification never gets turned into a generic callback error."""
    q = update.callback_query
    user = update.effective_user
    try:
        await q.answer("Verifying membership…")
    except Exception:
        pass
    try:
        pending_channels = await _check_force_join(ctx.bot, user.id)
    except Exception as exc:
        logger.exception("force-join checker crashed for user %s: %s", user.id, exc)
        pending_channels = [{"url": "", "label": "⚠️ Channel verification unavailable — check bot admin access"}]

    if not pending_channels:
        await _approve_pending_join_requests(ctx.bot, user.id)
    if pending_channels:
        # Public channels that cannot be inspected because the bot is not an
        # administrator use an explicit user-confirmation fallback. Private
        # invite links already use the same trust-based mechanism.
        unverifiable = [c for c in pending_channels if c.get("type") == "public_unverifiable"]
        if unverifiable:
            for ch in unverifiable:
                try:
                    await db.confirm_force_join_channel(user.id, ch.get("id", ""))
                except Exception as exc:
                    logger.warning("force-join confirmation save failed for %s/%s: %s", user.id, ch.get("id"), exc)
            # Re-check after recording fallback confirmations. This lets the
            # user continue without requiring the bot to be made channel admin.
            try:
                pending_channels = await _check_force_join(ctx.bot, user.id)
            except Exception:
                pending_channels = [c for c in pending_channels if c.get("type") != "public_unverifiable"]

        if not pending_channels:
            return await cb_check_joined(update, ctx)

        rows = []
        for ch in pending_channels:
            if ch.get("url"):
                rows.append([channel_join_button(ch["label"], url=ch["url"])])
        rows.append([channels_joined_button("I've Joined All", callback_data="cb_check_joined")])
        text = (
            "⚠️ *Membership verification pending.*\n\n"
            "Join every required channel, then tap *I've Joined All*.\n\n"
            "For public channels where the bot cannot inspect members, your tap is "
            "used as the membership confirmation, so the bot does not need to be "
            "an administrator in that channel."
        )
        try:
            await q.message.edit_text(text, parse_mode="Markdown", reply_markup=InlineKeyboardMarkup(rows))
        except Exception:
            try:
                await q.message.reply_text(text, parse_mode="Markdown", reply_markup=InlineKeyboardMarkup(rows))
            except Exception:
                pass
        return

    try:
        await _record_pending_giveaway_referral(user.id, ctx)
    except Exception as exc:
        logger.warning("giveaway referral recording failed after force join: %s", exc)

    try:
        await userbot.load_existing_session(user.id)
    except Exception as exc:
        logger.warning("load_existing_session after force join failed for %s: %s", user.id, exc)

    try:
        acc = await db.get_account(user.id)
        stats = await db.get_stats(user.id) or {}
        badge = await _premium_badge(user.id)
        custom_welcome = await db.get_setting("welcome_text", "")
    except Exception as exc:
        logger.warning("welcome DB load after force join failed for %s: %s", user.id, exc)
        acc, stats, badge, custom_welcome = None, {}, "🆓 Free", ""

    if await _send_first_time_tutorial(update, ctx):
        return

    uname = f"@{user.username}" if user.username else "N/A"
    if acc:
        text = (
            f"👋 *Welcome back, {user.first_name}!*\n\n"
            f"{DIVIDER}\n"
            f"🆔 User ID: `{user.id}`\n"
            f"👤 Username: {uname}\n"
            f"📱 Account: `{acc.get('phone','')}`\n"
            f"⭐ Status: {badge}\n"
            f"📤 Total Sent: *{stats.get('total_sent', 0):,}* DMs\n"
            f"{DIVIDER}\n\nChoose an option below."
        )
    elif custom_welcome:
        text = custom_welcome
    else:
        text = (
            f"👋 *All channels joined! Welcome, {user.first_name}!*\n\n"
            f"{DIVIDER}\n"
            f"🆔 Your ID: `{user.id}`\n"
            f"👤 Username: {uname}\n"
            f"{DIVIDER}\n\n"
            "Tap *Add Account* to get started!"
        )

    try:
        await q.message.delete()
    except Exception:
        pass
    try:
        await ctx.bot.send_photo(
            chat_id=user.id, photo=get_image_bytes("welcome"),
            caption=text, parse_mode="Markdown", reply_markup=await get_main_menu_kb(),
        )
    except Exception:
        try:
            await ctx.bot.send_message(
                chat_id=user.id, text=text, parse_mode="Markdown",
                reply_markup=await get_main_menu_kb()
            )
        except Exception as exc:
            logger.warning("final welcome send failed for %s: %s", user.id, exc)


