    if not await ensure_account(update):
        return
    if not await ensure_not_banned(update):
        return
    user = update.effective_user
    user_id = user.id

    user_row = await db.get_user(user_id)
    acc = await db.get_account(user_id)
    prem = await db.get_premium(user_id)
    stats = await db.get_stats(user_id) or {}
    is_active = await db.check_premium_active(user_id)
    uname = f"@{user.username}" if user.username else "N/A"
    joined = str(user_row.get("created_at", "N/A"))[:10] if user_row else "N/A"

    if is_active and prem:
        try:
            exp = datetime.fromisoformat(prem["expires_at"])
            now = datetime.now(timezone.utc).replace(tzinfo=None)
            delta = exp - now
            purchased = str(prem.get("starts_at", "N/A"))[:16].replace("T", " ")
            expires   = str(prem.get("expires_at", "N/A"))[:16].replace("T", " ")
            plan_status = (
                f"emoji_5472239203590888751 *VIP Premium*\n"
                f"   Plan: `{prem['plan_key']}`\n"
                f"   emoji_5280920959132380213 Purchased: `{purchased} UTC`\n"
                f"   ⏰ Expires:   `{expires} UTC`\n"
                f"   emoji_6147565374289220368 Remaining: `{_fmt_remaining(delta)}`"
            )
        except Exception:
            plan_status = "emoji_5472239203590888751 *VIP Premium* (active)"
    else:
        used = stats.get("total_sent", 0)
        fl = await db.get_free_limit()
        remaining = max(0, fl - used)
        plan_status = f"🆓 *Free Plan*\n   Sends used: `{used}` / `{fl}`\n   Remaining: `{remaining}`"

    msg = (
        f"emoji_6271665430650163493 *MY PROFILE*\n"
        f"{DIVIDER}\n"
        f"🆔 User ID: `{user_id}`\n"
        f"emoji_6271665430650163493 Username: {uname}\n"
        f"emoji_5778271407435682765 Phone: `{acc['phone'] if acc else 'Not linked'}`\n"
        f"emoji_5280920959132380213 Joined: `{joined}`\n\n"
        f"emoji_5215579104807497179 *PLAN STATUS*\n"
        f"{DIVIDER}\n"
        f"{plan_status}\n\n"
        f"emoji_6129801569941592173 *STATISTICS*\n"
        f"{DIVIDER}\n"
        f"emoji_5287651735525937879 Total DMs Sent: *{stats.get('total_sent', 0):,}*\n"
        f"emoji_6120625823285251747 Plans Purchased: *{stats.get('plans_bought', 0)}*\n"
    )
    await q.message.reply_text(msg, parse_mode="Markdown", reply_markup=back_kb())


