async def cb_delete_all_chats_confirm(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Start deleting all chats."""
    q = update.callback_query
    user_id = update.effective_user.id
    
    try:
        # Loading message
        prog_msg = await q.message.edit_text(
            "emoji_5472239203590888751 *Deleting All Chats Messages…*\n\n"
            f"{DIVIDER}\n"
            "emoji_5287651735525937879 Progress: 0/0 chats\n"
            "emoji_6147565374289220368 Deleted: 0 messages\n\n"
            "Please wait...",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [_rbtn("emoji_5832262406226579218 Stop", callback_data="cb_stop_delete_chats")],
            ]),
        )
        
        _stop_delete_event = asyncio.Event()
        ctx.user_data['delete_stop_event'] = _stop_delete_event
        ctx.user_data['delete_prog_msg_id'] = prog_msg.message_id
        
        async def on_delete_progress(uid, cleared_chats, deleted_msgs, total_chats, current):
            try:
                if current % 5 == 0 or current >= total_chats:
                    await ctx.bot.edit_message_text(
                        chat_id=uid,
                        message_id=prog_msg.message_id,
                        text=(
                            "emoji_5472239203590888751 *Deleting All Chats Messages…*\n\n"
                            f"{DIVIDER}\n"
                            f"emoji_5287651735525937879 Progress: {current}/{total_chats} chats\n"
                            f"emoji_6147565374289220368 Deleted: {deleted_msgs} messages\n\n"
                            "Deleting..."
                        ),
                        parse_mode="Markdown",
                        reply_markup=InlineKeyboardMarkup([
                            [_rbtn("emoji_5832262406226579218 Stop", callback_data="cb_stop_delete_chats")],
                        ]),
                    )
            except Exception:
                pass
        
        deleted_chats, deleted_msgs = await userbot.delete_all_chats_messages(
            user_id, 
            progress_cb=on_delete_progress,
            stop_event=_stop_delete_event
        )
        
        await ctx.bot.edit_message_text(
            chat_id=user_id,
            message_id=prog_msg.message_id,
            text=(
                "emoji_5877618313139327986 *Complete!*\n\n"
                f"{DIVIDER}\n"
                f"emoji_5287651735525937879 Chats Cleared: {deleted_chats}\n"
                f"emoji_6147565374289220368 Messages Deleted: {deleted_msgs}\n\n"
                "All done! Your chats have been cleared."
            ),
            parse_mode="Markdown",
            reply_markup=await get_main_menu_kb(),
        )
        
    except Exception as e:
        logger.error(f"Delete all chats error for {user_id}: {e}")
        await q.message.edit_text(
            "emoji_5337312745857501717 *Error*\n\n"
            f"Failed to delete chats: {str(e)}",
            parse_mode="Markdown",
            reply_markup=await get_main_menu_kb(),
        )


async def cb_stop_delete_chats(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Stop delete chats operation."""
    q = update.callback_query
    
    if 'delete_stop_event' in ctx.user_data:
        ctx.user_data['delete_stop_event'].set()
    
    await q.answer("Stopping...", show_alert=False)
    await q.message.edit_text(
        "emoji_5832262406226579218 *Stopped*\n\n"
        f"{DIVIDER}\n"
        "Delete operation stopped. Your chats have been partially cleared.",
        parse_mode="Markdown",
        reply_markup=await get_main_menu_kb(),
    )


