async def cb_stats(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Show the user's sending statistics and latest campaign status."""
    q = update.callback_query
    await q.answer()
    await _clear_user_convs(update)
    if not await ensure_account(update):
        return
    if not await ensure_not_banned(update):
        return
    user_id = update.effective_user.id

    stats = await db.get_stats(user_id) or {}
    camp = await db.get_campaign(user_id)
    is_active = await db.check_premium_active(user_id)
    prem = await db.get_premium(user_id)

    total_sent = stats.get("total_sent", 0)
    plans = stats.get("plans_bought", 0)

    last_camp = "None yet"
    if camp:
        status_map = {"done": "emoji_5877618313139327986 Completed", "running": "emoji_6269118781331609137 Running", "cancelled": "emoji_5832262406226579218 Stopped", "error": "emoji_5337312745857501717 Error"}
        last_camp = f"{status_map.get(camp['status'], camp['status'])} — {camp['sent']}/{camp['total']} sent"

    if is_active and prem:
        try:
            exp = datetime.fromisoformat(prem["expires_at"])
            now = datetime.now(timezone.utc).replace(tzinfo=None)
            delta = exp - now
            plan_line = f"emoji_5472239203590888751 VIP Premium — {_fmt_remaining(delta)} left"
        except Exception:
            plan_line = "emoji_5472239203590888751 VIP Premium"
    else:
        used = total_sent
        _fl = await db.get_free_limit()
        plan_line = f"🆓 Free — {max(0, _fl - used)} sends left"

    msg = (
        f"emoji_6129801569941592173 *YOUR STATISTICS*\n"
        f"{DIVIDER}\n"
        f"emoji_5215579104807497179 Plan: {plan_line}\n\n"
        f"emoji_5287651735525937879 *Sending*\n"
        f"   Total DMs Sent: *{total_sent:,}*\n"
        f"   Plans Purchased: *{plans}*\n\n"
        f"emoji_6006051952847230749 *Last Campaign*\n"
        f"   {last_camp}\n"
        f"{DIVIDER}\n"
        f"_Keep sending to grow your reach!_ emoji_5472239203590888751"
    )
    await q.message.reply_text(msg, parse_mode="Markdown", reply_markup=back_kb())


