async def _send_first_time_tutorial(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> bool:
    """Show the one-time tutorial intro after verification/force-join gates."""
    user = update.effective_user
    if not user or int(user.id) == int(ADMIN_TG_ID):
        return False
    try:
        if await db.is_tutorial_seen(user.id):
            return False
    except Exception:
        return False
    text = (
        "📚 *TUTORIAL SECTION*\n\n"
        "*Start Tutorial* — Learn how to use all bot features step by step.\n\n"
        "*Skip* — Already know how to use the bot? Skip and open the main menu."
    )
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("▶️ Start Tutorial", callback_data="tut_start", style="primary")],
        [InlineKeyboardButton("⏭️ Skip", callback_data="tut_skip", style="danger")],
    ])
    msg = update.effective_message
    try:
        with open(TUTORIAL_IMAGE, "rb") as photo:
            await msg.reply_photo(photo=photo, caption=text, parse_mode="Markdown", reply_markup=kb)
    except Exception:
        await msg.reply_text(text, parse_mode="Markdown", reply_markup=kb)
    return True


