async def _send_welcome_after_gate(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Reuse the normal welcome screen after first-time tutorial skip."""
    user = update.effective_user
    try:
        acc = await db.get_account(user.id)
        stats = await db.get_stats(user.id) or {}
        badge = await _premium_badge(user.id)
        custom_welcome = await db.get_setting("welcome_text", "")
    except Exception:
        acc, stats, badge, custom_welcome = None, {}, "🆓 Free", ""
    if custom_welcome:
        text = custom_welcome
    else:
        text = (
            "*👋 WELCOME TO DM BOT*\n\n"
            "*👤 USER NAME*\n*🆔 USER ID: 123456789*\n*🖥️ SERVER: ACTIVE*\n\n"
            "*🚀 MANAGE YOUR TELEGRAM ACCESS IN ONE CLICK*\n\n"
            "*📋 FEATURES :-*\n\n*⏹️ MASS DM FORWARDER*\n"
            "*⭐ JOIN REQUEST DM*\n*📢 ADS FOR CHATS & CHANNELS*\n*🤖 AUTO REPLY*\n*📣 CHANNEL PROMOTION*\n\n"
            "*👤 100 DMs + 100 JOIN REQUEST DMs*\n*🎁 COMPLETELY FREE*\n\n*📢 ADS & AUTO REPLY — FREE*"
        )
    text = _personalize_welcome_text(text, user)
    photo_sent = False
    try:
        photos = await ctx.bot.get_user_profile_photos(user.id, limit=1)
        if photos.photos:
            photo_file = photos.photos[0][-1]
            await ctx.bot.send_photo(chat_id=user.id, photo=photo_file.file_id, caption=text, parse_mode="Markdown", reply_markup=await get_main_menu_kb())
            photo_sent = True
    except Exception:
        pass
    if not photo_sent:
        await ctx.bot.send_message(chat_id=user.id, text=text, parse_mode="Markdown", reply_markup=await get_main_menu_kb())

