# ── Preview Message ───────────────────────────────────────────────────────────
async def cb_previewmsg(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    await _clear_user_convs(update)
    if not await ensure_account(update):
        return
    if not await ensure_not_banned(update):
        return
    user_id = update.effective_user.id

    msgs = await db.get_user_messages(user_id)
    if not msgs:
        await q.message.reply_text(
            f"emoji_5447183459602669338 *Message Preview*\n\n"
            f"{DIVIDER}\n"
            "emoji_5337312745857501717 No messages set yet.\n\n"
            "Tap *Set Message* to compose your campaign message.",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [setmsg_button("emoji_6269362834258269327️ Set Message Now", callback_data="cb_setmsg")],
                [_bbtn("emoji_6123107313654960925 Back", callback_data="cb_back")],
            ]),
        )
        return

    await q.message.reply_text(
        f"emoji_5447183459602669338 *Campaign Messages Preview*\n"
        f"{DIVIDER}\n"
        f"You have *{len(msgs)}* message(s) ready to send:\n",
        parse_mode="Markdown",
    )
    for i, m in enumerate(msgs, 1):
        if m.get("media_path") and os.path.exists(m["media_path"]):
            try:
                with open(m["media_path"], "rb") as f:
                    caption = f"emoji_6120625823285251747 *Message {i}*" + (f"\n_{m['content']}_" if m.get("content") else "")
                    await q.message.reply_photo(photo=f, caption=caption, parse_mode="Markdown")
            except Exception:
                await q.message.reply_text(f"emoji_6129801569941592173 *Message {i}:* [media file]", parse_mode="Markdown")
        elif m.get("content"):
            await q.message.reply_text(
                f"emoji_6073288235642000201 *Message {i}:*\n{m['content']}",
                parse_mode="Markdown",
            )

    await q.message.reply_text(
        f"{DIVIDER}\n"
        "These messages will be sent to *all your DMs*.\n"
        "Ready? emoji_6196964713738279294",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [campaign_button("Start Campaign Now", callback_data="cb_campaign")],
            [setmsg_button("emoji_6269362834258269327️ Change Messages", callback_data="cb_setmsg")],
            [_bbtn("emoji_6123107313654960925 Back to Menu", callback_data="cb_back")],
        ]),
    )


