async def cb_premium(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    await _clear_user_convs(update)
    if not await ensure_account(update):
        return
    if not await ensure_not_banned(update):
        return
    user_id = update.effective_user.id
    is_active = await db.check_premium_active(user_id)
    prem = await db.get_premium(user_id)
    upi = await db.get_setting("upi_id", UPI_ID)

    if is_active and prem:
        try:
            exp = datetime.fromisoformat(prem["expires_at"])
            now = datetime.now(timezone.utc).replace(tzinfo=None)
            delta = exp - now
            expires_str = str(prem.get("expires_at", ""))[:16].replace("T", " ")
            status_line = (
                f"emoji_5877618313139327986 Active — *{_fmt_remaining(delta)}* remaining\n"
                f"   ⏰ Expires: `{expires_str} UTC`"
            )
        except Exception:
            status_line = "emoji_5877618313139327986 *Premium Active*"
    else:
        used = (await db.get_stats(user_id) or {}).get("total_sent", 0)
        _fl2 = await db.get_free_limit()
        remaining = max(0, _fl2 - used)
        status_line = f"🆓 Free Plan — `{remaining}` sends remaining"

    text = (
        f"emoji_5472239203590888751 *VIP PREMIUM*\n"
        f"{DIVIDER}\n"
        f"emoji_5215579104807497179 Current Status: {status_line}\n"
        f"{DIVIDER}\n\n"
        f"emoji_5472239203590888751 *What Premium Unlocks:*\n"
        f"   emoji_5877618313139327986 Unlimited DM sends\n"
        f"   emoji_5188481279963715781 Maximum speed\n"
        f"   emoji_6070920317092500169 Priority support\n"
        f"   emoji_6129801569941592173 Full campaign analytics\n\n"
        f"{DIVIDER}\n"
        f"emoji_5420323339723881652 Payment: *UPI* — `{upi}`\n"
        f"{DIVIDER}\n\n"
        f"Select a plan to continue emoji_6196964713738279294"
    )
    await q.message.reply_text(text, parse_mode="Markdown", reply_markup=premium_plans_kb())


