async def handle_utr(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    utr = update.message.text.strip()
    plan_key = ctx.user_data.get("pending_plan")
    plan = _PLANS_CACHE.get(plan_key, {})
    if not plan:
        await update.message.reply_text("emoji_5454415424319931791️ Session expired. Please select a plan again.", reply_markup=await get_main_menu_kb())
        return ConversationHandler.END

    ctx.user_data["pending_utr"] = utr

    order_id = ctx.user_data.get("pending_order_id", "")
    order_line = f"emoji_5447183459602669338 Order ID: `{order_id}`\n" if order_id else ""

    await update.message.reply_text(
        f"emoji_5877618313139327986 *UTR saved!*\n\n"
        f"{DIVIDER}\n"
        f"emoji_5447410659077661506 Plan: *{plan['label']}*\n"
        f"emoji_6120625823285251747 Amount: ₹{plan['price']}\n"
        f"{order_line}"
        f"emoji_6028565819225542441 UTR: `{utr}`\n"
        f"{DIVIDER}\n\n"
        "emoji_6120625823285251747 *Last step — Send your Payment Screenshot:*\n\n"
        "Please send a screenshot of the payment confirmation from your UPI app "
        "(GPay, PhonePe, Paytm, etc.).\n\n"
        "_The screenshot helps the admin verify your payment quickly._",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[cancel_button("emoji_6123107313654960925 Cancel", callback_data="cb_back")]]),
    )
    return PAY_SCREENSHOT


async def handle_pay_screenshot(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    user    = update.effective_user
    user_id = user.id

    # Accept photo or image document
    screenshot_file_id = None
    if update.message.photo:
        screenshot_file_id = update.message.photo[-1].file_id
    elif update.message.document and update.message.document.mime_type and "image" in update.message.document.mime_type:
        screenshot_file_id = update.message.document.file_id

    if not screenshot_file_id:
        await update.message.reply_text(
            "emoji_5454415424319931791️ Please send a *photo* (screenshot) of your payment.\n\n"
            "Take a screenshot from your UPI app and send it here.",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[cancel_button("emoji_6123107313654960925 Cancel", callback_data="cb_back")]]),
        )
        return PAY_SCREENSHOT

    plan_key = ctx.user_data.get("pending_plan")
    order_id = ctx.user_data.pop("pending_order_id", "")
    utr      = ctx.user_data.pop("pending_utr", "")
    plan     = _PLANS_CACHE.get(plan_key, {})

    if not plan:
        await update.message.reply_text("emoji_5454415424319931791️ Session expired. Please select a plan again.", reply_markup=await get_main_menu_kb())
        return ConversationHandler.END

    payment = await db.create_payment(user_id, plan_key, plan["price"], order_id=order_id)
    await db.update_payment(payment["id"], utr=utr, screenshot_file_id=screenshot_file_id, payment_method="manual")

    uname = f"@{user.username}" if user.username else "N/A"
    full_name = user.full_name or user.first_name or "N/A"
    now_str = datetime.now(timezone.utc).strftime("%d %b %Y, %H:%M UTC")

    if ADMIN_TG_ID:
        from telegram import InlineKeyboardButton as IKB, InlineKeyboardMarkup as IKM
        admin_kb = IKM([
            [IKB("Approve", callback_data=f"pay_approve_{payment['id']}"),
             IKB("Reject",  callback_data=f"pay_reject_{payment['id']}")],
        ])
        order_line_a = f"  emoji_5447183459602669338 Order ID: `{order_id}`\n" if order_id else ""
        _days = plan.get("days", 1)
        _dur = "Unlimited (Lifetime)" if _days >= 999 else f"{_days} day(s)"
        admin_text = (
            f"💳 *NEW PREMIUM PAYMENT — MANUAL VERIFICATION*\n\n"
            f"╔══════════════════════════════╗\n"
            f"║        🧾 PAYMENT RECEIPT        ║\n"
            f"╠══════════════════════════════╣\n"
            f"║ 👤 User: `{full_name}`\n"
            f"║ 🆔 User ID: `{user.id}`\n"
            f"║ 📱 Username: {uname}\n"
            f"║ 💎 Plan: *{plan['label']}*\n"
            f"║ ⏳ Duration: *{_dur}*\n"
            f"║ 💰 Amount: *₹{plan['price']}*\n"
            f"║ 🧾 UTR: `{utr}`\n"
            f"║ 🆔 Order ID: `{order_id or 'N/A'}`\n"
            f"║ 🔢 Payment ID: `#{payment['id']}`\n"
            f"║ 🕐 Submitted: `{now_str}`\n"
            f"╚══════════════════════════════╝\n\n"
            f"🖼️ *Payment screenshot is attached above.*\n"
            f"Choose *Approve* to activate Premium or *Reject* to request a reason."
        )
        # Single-bot architecture: payment review is sent through the same User Bot.
        # The received file_id can be reused directly because it belongs to this bot.
        try:
            await ctx.bot.send_photo(
                chat_id=ADMIN_TG_ID,
                photo=screenshot_file_id,
                caption=admin_text,
                parse_mode="Markdown",
                reply_markup=admin_kb,
            )
        except Exception as _admin_err:
            logger.error("Admin payment notification failed: %s", _admin_err)


