async def _do_autopay_verify(
    utr: str,
    plan_key: str,
    plan: dict,
    user_id: int,
    order_id: str,
    hold_msg,
    ctx,
    user,
    is_retry: bool = False,
):
    """Core verification logic shared by first attempt and retry."""
    result = await asyncio.get_running_loop().run_in_executor(
        None, gmail_checker.check_payment, utr, plan["price"]
    )

    if result.matched:
        await db.mark_utr_used(utr, user_id)
        await db.set_premium(user_id, plan_key, plan["days"], amount_paid=plan["price"])
        await db.increment_plans(user_id)
        support = await db.get_setting("support_username", ADMIN_USERNAME)
        await hold_msg.edit_text(
            f"{autoverify_emoji_html()} <b>Payment Verified Successfully!</b>\n"
            f"{DIVIDER}\n"
            f"emoji_5447410659077661506 Plan: <b>{html.escape(str(plan['label']))}</b>\n"
            f"emoji_6120625823285251747 Amount Paid: ₹{plan['price']}\n"
            f"emoji_6028565819225542441 UTR: <code>{html.escape(utr)}</code>\n"
            f"emoji_6147565374289220368 Duration: <b>{plan['days']} day(s)</b>\n"
            f"emoji_5472239203590888751 Activated: Just now\n"
            f"{DIVIDER}\n\n"
            f"{campaign_emoji_html()} <b>Premium is now ACTIVE!</b>\n"
            "You can now send unlimited DMs.\n\n"
            f"emoji_6073288235642000201 Support: @{html.escape(str(support))}",
            parse_mode="HTML",
            reply_markup=await get_main_menu_kb(),
        )
        return True

    # Verification failed — determine failure reason for tailored message
    reason = result.reason  # "not_found" | "amount_mismatch" | "gmail_not_configured" | "gmail_auth_error" | "error"

    if reason == "amount_mismatch":
        # Found the UTR but amount didn't match — likely wrong plan selected
        support = await db.get_setting("support_username", ADMIN_USERNAME)
        await hold_msg.edit_text(
            f"emoji_5454415424319931791️ *Amount Mismatch Detected*\n"
            f"{DIVIDER}\n"
            f"emoji_5447410659077661506 Plan: *{plan['label']}* — ₹{plan['price']}\n"
            f"emoji_6028565819225542441 UTR: `{utr}`\n"
            f"{DIVIDER}\n\n"
            "emoji_5877618313139327986 Your UTR was found in our inbox.\n"
            f"emoji_5337312745857501717 However, the payment amount does *not match* ₹{plan['price']}.\n\n"
            "Please make sure you:\n"
            f"• Paid exactly ₹{plan['price']} for this plan\n"
            "• Selected the correct plan\n\n"
            f"Contact support if you believe this is a mistake.\n"
            f"emoji_6073288235642000201 @{support}",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [_bbtn("emoji_6070920317092500169 Back to Menu", callback_data="cb_back")],
            ]),
        )
        return False

    if reason in ("gmail_not_configured", "gmail_auth_error"):
        # Admin hasn't set up Gmail — fall back to manual review
        payment = await db.create_payment(user_id, plan_key, plan["price"], order_id=order_id)
        await db.update_payment(payment["id"], utr=utr, payment_method="automatic")
        support = await db.get_setting("support_username", ADMIN_USERNAME)
        await hold_msg.edit_text(
            f"emoji_6269118781331609137 *Submitted for Manual Review*\n"
            f"{DIVIDER}\n"
            f"emoji_5447410659077661506 Plan: *{plan['label']}* — ₹{plan['price']}\n"
            f"emoji_6028565819225542441 UTR: `{utr}`\n"
            f"{DIVIDER}\n\n"
            "Auto-verification is currently unavailable.\n"
            "Your payment details have been sent to the admin for *manual approval*.\n\n"
            "⏱ *Typical approval time: 1–30 minutes*\n\n"
            f"emoji_6073288235642000201 Contact support: @{support}",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [_bbtn("emoji_6070920317092500169 Back to Menu", callback_data="cb_back")],
            ]),
        )
        _notify_admin_failed(ctx, user, plan, utr, order_id, "Gmail not configured", payment_id=payment["id"])
        return False

    # not_found or generic error — offer retry
    payment = await db.create_payment(user_id, plan_key, plan["price"], order_id=order_id)
    await db.update_payment(payment["id"], utr=utr, payment_method="automatic")
    support = await db.get_setting("support_username", ADMIN_USERNAME)
    retry_label = "emoji_6269118781331609137 Retry Verification" if not is_retry else "emoji_6269118781331609137 Try Again"
    await hold_msg.edit_text(
        f"emoji_5337312745857501717 *Payment Not Found*\n"
        f"{DIVIDER}\n"
        f"emoji_5447410659077661506 Plan: *{plan['label']}* — ₹{plan['price']}\n"
        f"emoji_6028565819225542441 UTR Entered: `{utr}`\n"
        f"{DIVIDER}\n\n"
        "We couldn't find this payment in our inbox.\n\n"
        "emoji_5447183459602669338 *Please check:*\n"
        "• The UTR / Transaction ID is correct\n"
        "• The payment was sent to the correct UPI ID\n"
        f"• The amount is exactly ₹{plan['price']}\n\n"
        "_Payments sometimes take 1–2 minutes to appear._\n"
        "Tap *Retry* after a moment, or contact support.\n\n"
        f"emoji_6073288235642000201 Support: @{support}",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [_gbtn(retry_label, callback_data=f"autopay_retry_{plan_key}|{utr}")],
            [_bbtn("emoji_6070920317092500169 Back to Menu", callback_data="cb_back")],
        ]),
    )
    _notify_admin_failed(ctx, user, plan, utr, order_id, "Not found in Gmail", payment_id=payment["id"])
    return False


def _notify_admin_failed(ctx, user, plan: dict, utr: str, order_id: str, reason: str, payment_id: int | None = None):
    """Send automatic-verification failures ONLY to the ADMIN BOT."""
    async def _send():
        if not ADMIN_TG_ID:
            return
        try:
            uname = f"@{user.username}" if user.username else "N/A"
            order_line = f"Order ID: `{order_id}`\n" if order_id else ""
            text = (
                f"⚠️ *Automatic Payment Verification Failed*\n\n"
                f"{DIVIDER}\n"
                f"👤 User: `{user.id}` | {uname}\n"
                f"📋 Plan: *{plan['label']}*\n"
                f"💰 Amount: ₹{plan['price']}\n"
                f"{order_line}"
                f"🧾 UTR / Transaction ID: `{utr}`\n"
                f"❗ Reason: `{reason}`\n"
                f"{DIVIDER}\n\n"
                "Automatic verification did not confirm this payment. You can manually review it below."
            )
            from telegram import InlineKeyboardButton as IKB, InlineKeyboardMarkup as IKM
            kb = None
            if payment_id:
                kb = IKM([[
                    IKB("✅ Approve", callback_data=f"pay_approve_{payment_id}"),
                    IKB("❌ Reject", callback_data=f"pay_reject_{payment_id}"),
                ]])
            await ctx.bot.send_message(chat_id=ADMIN_TG_ID, text=text, parse_mode="Markdown", reply_markup=kb)
        except Exception as ex:
            logger.error("Admin bot auto-payment notification failed: %s", ex)
    asyncio.create_task(_send())


async def handle_utr_auto(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    utr = update.message.text.strip()
    user_id = update.effective_user.id
    plan_key = ctx.user_data.get("auto_pending_plan")
    order_id = ctx.user_data.pop("auto_pending_order_id", "")
    plan = _PLANS_CACHE.get(plan_key, {})

    if not plan:
        await update.message.reply_text(
            "emoji_5454415424319931791️ *Session Expired*\n\n"
            "Please go back to the menu and select a plan again.",
            parse_mode="Markdown",
            reply_markup=await get_main_menu_kb(),
        )
        return ConversationHandler.END

    # Basic format validation
    if len(utr) < 6 or len(utr) > 64:
        await update.message.reply_text(
            "emoji_5454415424319931791️ *Invalid Entry*\n\n"
            "A UTR / Transaction ID is usually 6–20 characters.\n"
            "Please double-check and try again.",
            parse_mode="Markdown",
        )
        return PAY_UTR_AUTO

    # Duplicate UTR check
    if await db.is_utr_used(utr):
        support = await db.get_setting("support_username", ADMIN_USERNAME)
        await update.message.reply_text(
            f"emoji_6116290955743073366 *Already Used*\n"
            f"{DIVIDER}\n"
            f"emoji_6028565819225542441 UTR: `{utr}`\n"
            f"{DIVIDER}\n\n"
            "This UTR / Transaction ID has already been used to activate a premium plan.\n"
            "Each transaction can only be used *once*.\n\n"
            "If you believe this is an error, contact support.\n"
            f"emoji_6073288235642000201 @{support}",
            parse_mode="Markdown",
            reply_markup=await get_main_menu_kb(),
        )
        return ConversationHandler.END

    hold_msg = await update.message.reply_text(
        f"{autoverify_emoji_html()} emoji_5465443379917629504 *Verifying Payment…*\n"
        f"{DIVIDER}\n"
        f"emoji_5447410659077661506 Plan: *{plan['label']}* — ₹{plan['price']}\n"
        f"emoji_6028565819225542441 UTR: `{utr}`\n"
        f"{DIVIDER}\n\n"
        "emoji_6147565374289220368 Searching payment inbox… _This takes a few seconds._",
        parse_mode="Markdown",
    )

    await _do_autopay_verify(
        utr=utr, plan_key=plan_key, plan=plan, user_id=user_id,
        order_id=order_id, hold_msg=hold_msg, ctx=ctx,
        user=update.effective_user, is_retry=False,
    )
    return ConversationHandler.END


