# ── Campaign — live card ──────────────────────────────────────────────────────
# One live card per campaign. Each card is bound to its own state dict so a
# stale engine can never update or finish a newer campaign.
from premium_ui import (
    CAMPAIGN_CUSTOM_EMOJI_ID, JD_CUSTOM_EMOJI_ID, DONE_CUSTOM_EMOJI_ID,
    CANCEL_CUSTOM_EMOJI_ID, ACCEPT_PENDING_CUSTOM_EMOJI_ID,
)
from premium_emoji_runtime import custom_emoji_html as _custom_emoji

_camp_ui: dict[int, dict] = {}


def _fmt_eta(seconds) -> str:
    if seconds is None:
        return "—"
    s = max(0, int(round(float(seconds))))
    if s < 60:
        return f"{s}s"
    m, s = divmod(s, 60)
    if m < 60:
        return f"{m}m {s:02d}s"
    h, m = divmod(m, 60)
    return f"{h}h {m:02d}m"


# Speed note shown under every campaign card (Mass DM and Join Request DM).
CAMPAIGN_SPEED_NOTE = (
    f"{custom_emoji_html('⚡', '5188481279963715781')} <b><i>Smart Speed Guard</i></b>\n"
    "<b><i>If your account was limited or spam-flagged,</i></b> "
    "<i>Telegram may pause for some seconds. The bot waits and continues automatically.</i>\n"
    "<b><i>If not,</i></b> <i>you get no limits and no pauses. Full speed, one message per second.</i>"
)


def _render_campaign_card(st: dict) -> str:
    s = st["stats"]
    is_jd = st.get("kind") == "jd"
    title = st.get("title") or ("Join Request DM Campaign" if is_jd else "Mass DM Campaign")
    title_icon = _custom_emoji("📣" if is_jd else "🚀", JD_CUSTOM_EMOJI_ID if is_jd else CAMPAIGN_CUSTOM_EMOJI_ID)

    status = str(st["status"])
    low = status.lower()
    if low.startswith("completed") and "stopped" not in low:
        status_icon = _custom_emoji("✅", DONE_CUSTOM_EMOJI_ID)
    elif "stopped" in low or low.startswith("not started"):
        status_icon = _custom_emoji("⛔", CANCEL_CUSTOM_EMOJI_ID)
    elif low.startswith("paused"):
        status_icon = "⏸"
    else:
        status_icon = _custom_emoji("⏳", ACCEPT_PENDING_CUSTOM_EMOJI_ID)

    total = int(s["found"] or 0)
    sent = int(s["sent"] or 0)
    pct = int(round(100 * sent / total)) if total else 0
    filled = max(0, min(10, pct // 10))
    bar = "▰" * filled + "▱" * (10 - filled)

    return (
        f"{title_icon} <b>{html.escape(title)}</b>\n"
        f"{DIVIDER}\n"
        f"{status_icon} <b>Status:</b> {html.escape(status)}\n\n"
        f"👥 <b>Total Chats:</b> <code>{int(s['scanned']):,}</code>\n"
        f"🔎 <b>Total Chats Found:</b> <code>{int(s['found']):,}</code>\n"
        f"✉️ <b>Sending:</b> <code>{int(s['queued']):,}</code>\n"
        f"✅ <b>Sent:</b> <code>{sent:,}</code>\n"
        f"⏱ <b>ETA:</b> <code>{_fmt_eta(s['eta'])}</code>\n\n"
        f"<code>{bar}</code>  <b>{pct}%</b>\n"
        f"{DIVIDER}\n"
        + CAMPAIGN_SPEED_NOTE
    )


async def _update_campaign_card(st: dict, force: bool = False) -> None:
    """Refresh the live card. Routine updates are throttled to one every 2 seconds."""
    if st.get("finished"):
        return
    now = time.monotonic()
    if not force and now - st.get("last_edit", 0.0) < 2.0:
        return
    text = _render_campaign_card(st)
    if text == st.get("last_text"):
        return
    st["last_edit"] = now
    st["last_text"] = text
    try:
        await st["bot"].edit_message_text(
            chat_id=st["uid"],
            message_id=st["msg_id"],
            text=text,
            parse_mode="HTML",
            reply_markup=_stop_kb(),
        )
    except Exception:
        pass


async def _finalize_card(st: dict, status: str, stats: dict | None = None) -> None:
    """Mark the card Completed (or stopped), remove the Stop button, show the main menu."""
    if st.get("finished"):
        return
    st["finished"] = True
    st["status"] = status
    if stats:
        st["stats"].update(stats)
    st["stats"]["queued"] = 0
    st["stats"]["eta"] = None
    if _camp_ui.get(st["uid"]) is st:
        _camp_ui.pop(st["uid"], None)
    _progress_msg_ids.pop(st["uid"], None)
    try:
        await st["bot"].edit_message_text(
            chat_id=st["uid"],
            message_id=st["msg_id"],
            text=_render_campaign_card(st),
            parse_mode="HTML",
            reply_markup=await get_main_menu_kb(),
        )
    except Exception:
        logger.exception("Campaign card finalisation failed for user %s", st["uid"])


# ── Campaign ──────────────────────────────────────────────────────────────────
async def _run_new_mass_dm_flow(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """V76 Mass DM UI: live one-to-one progress, counters and ETA."""
    q = update.callback_query
    await q.answer()
    await _clear_user_convs(update)
    user_id = update.effective_user.id

    if not await ensure_account(update) or not await ensure_not_banned(update):
        return

    if not userbot.get_client(user_id):
        loaded = await userbot.load_existing_session(user_id)
        if not loaded:
            await q.message.reply_text(
                f"emoji_5337312745857501717 *Session Expired*\n\n{DIVIDER}\n"
                "Your linked Telegram account session has expired or is no longer valid.\n\n"
                "Please remove your account and add it again to continue.",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup([
                    [_gbtn("emoji_5276032951342088188 Re-add Account", callback_data="cb_addaccount")],
                    [_bbtn("emoji_6123107313654960925 Back to Menu", callback_data="cb_back")],
                ]),
            )
            return

    msgs = await db.get_user_messages(user_id)
    if not msgs:
        await q.message.reply_text(
            f"emoji_6269362834258269327️ *No Message Set*\n\n{DIVIDER}\n"
            "You haven't set a campaign message yet.\n\n"
            "Tap *Set Message* first, then start your campaign.",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [setmsg_button("emoji_6269362834258269327️ Set Message Now", callback_data="cb_setmsg")],
                [_bbtn("emoji_6123107313654960925 Back", callback_data="cb_back")],
            ]),
        )
        return

    previous = _camp_ui.get(user_id)
    if previous is not None and not previous.get("finished"):
        previous["stop_reason"] = "Completed (replaced by a new campaign)"
        await userbot.cancel_campaign(user_id)
        await _finalize_card(previous, previous["stop_reason"])

    st = {
        "uid": user_id,
        "bot": ctx.bot,
        "msg_id": None,
        "status": "Scanning your chats and contacts…",
        "stats": {"scanned": 0, "found": 0, "queued": 0, "sent": 0, "eta": None},
        "last_edit": 0.0,
        "last_text": "",
        "finished": False,
        "stop_reason": None,
    }
    prog_msg = await q.message.reply_text(_render_campaign_card(st), parse_mode="HTML",
                                          reply_markup=_stop_kb())
    st["msg_id"] = prog_msg.message_id
    st["last_edit"] = time.monotonic()
    st["last_text"] = _render_campaign_card(st)
    _camp_ui[user_id] = st
    _progress_msg_ids[user_id] = prog_msg.message_id
    _campaign_start_times[user_id] = time.monotonic()

    async def on_progress(uid, sent, failed, total, label, skipped=0,
                          scanned=0, found=0, queued=0, eta=None, **_):
        if st.get("finished"):
            return
        st["stats"].update(scanned=scanned, found=found or total, sent=sent,
                           queued=queued, eta=eta)
        status = str(label)
        changed = status != st["status"]
        st["status"] = status
        await _update_campaign_card(st, force=changed)

    async def on_done(uid, error, _sent=0, _failed=0, _total=0, _skipped=0):
        try:
            found = _total or st["stats"].get("found", 0)
            if error is None:
                status = "Completed"
            elif error == "cancelled":
                status = st.get("stop_reason") or "Completed (stopped by user)"
            elif error == "free_limit":
                status = "Not started: free DM limit reached. Upgrade to Premium to continue."
            elif error == "No messages":
                status = "Not started: the saved message has no content"
            elif str(error).startswith("Not authorised"):
                status = "Not started: account session is not authorised"
            elif found == 0 and str(error).startswith("no_contacts"):
                status = "Completed: no eligible one-to-one chats were found"
            else:
                status = "Stopped due to an error"
                logger.warning("Mass DM for user %s ended with error: %s", uid, error)
            await _finalize_card(st, status, {"sent": _sent, "found": found})
        except Exception:
            logger.exception("Mass DM completion failed for user %s", uid)
        finally:
            userbot.clear_mass_dm_failures(uid)

    await userbot.start_mass_dm_campaign(user_id, msgs, on_progress, on_done)


# Compatibility aliases: every existing Mass DM entry points to the same flow.
async def cb_campaign(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    return await _run_new_mass_dm_flow(update, ctx)


async def cb_mass_dm_campaign(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    return await _run_new_mass_dm_flow(update, ctx)


# ── Stop Campaign ─────────────────────────────────────────────────────────────
async def _clear_campaign_state(user_id: int):
    """Fully wipe every in-memory trace of a campaign for this user."""
    card = _camp_ui.get(user_id)
    await userbot.cancel_campaign(user_id)
    if card is not None and not card.get("finished"):
        await _finalize_card(card, card.get("stop_reason") or "Completed (stopped by user)")
    _progress_msg_ids.pop(user_id, None)
    _progress_last_edit.pop(user_id, None)
    _campaign_start_times.pop(user_id, None)
    try:
        await db.update_campaign(user_id, status="cancelled")
    except Exception:
        pass


async def cb_stop_campaign(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Stop button under the live card: halts immediately and marks the campaign Completed."""
    q = update.callback_query
    user_id = update.effective_user.id
    card = _camp_ui.get(user_id)
    if card is not None and not card.get("finished"):
        await q.answer("Stopping campaign…")
        await _clear_campaign_state(user_id)
        return

    # Legacy path: other campaign types share this button.
    await q.answer("Stopping…", show_alert=False)
    msg_id = _progress_msg_ids.get(user_id)
    await _clear_campaign_state(user_id)
    camp = await db.get_campaign(user_id)
    sent = camp["sent"] if camp else 0
    text = (
        f"emoji_5832262406226579218 *Campaign Stopped*\n\n"
        f"{DIVIDER}\n"
        f"emoji_5287651735525937879 Messages sent before stopping: `{sent:,}`\n\n"
        "You can start a new campaign any time."
    )
    try:
        if msg_id:
            await q.message.edit_text(text, parse_mode="Markdown", reply_markup=await get_main_menu_kb())
        else:
            await q.message.reply_text(text, parse_mode="Markdown", reply_markup=await get_main_menu_kb())
    except Exception:
        await q.message.reply_text(text, parse_mode="Markdown", reply_markup=await get_main_menu_kb())


