async def handle_set_msg(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    import json as _json
    user_id = update.effective_user.id
    count = ctx.user_data.get("msg_count", 0) + 1
    ctx.user_data["msg_count"] = count

    msg = update.message

    # ── Detect "no link preview" ───────────────────────────────────────────
    # Honour the user's link-preview toggle exactly as they set it —
    # send to every DM with the same no-preview setting.
    no_preview = bool(
        getattr(msg, "link_preview_options", None)
        and getattr(msg.link_preview_options, "is_disabled", False)
    )

    # ── Detect reply relationship ──────────────────────────────────────────
    # If the user swipe-replied to a previous message while composing, store
    # which sequence index they replied to so the campaign can reconstruct
    # the exact same reply thread in every DM.
    # reply_to_index is 1-based: 1 = reply to first campaign message, etc.
    reply_to_index = None
    is_reply = False
    if msg.reply_to_message and count > 1:
        # The user replied to something while setting up messages.
        # We record it as "reply to the previous message in the sequence"
        # (count-1), which is the natural compose flow.
        reply_to_index = count - 1
        is_reply = True

    # ── Capture all formatting entities (bold/italic/spoiler/custom-emoji/etc.) ──
    # Preserve exact Telegram formatting just like the user sent it
    raw_entities = msg.entities or msg.caption_entities or []
    entities_list = []
    for e in raw_entities:
        etype = e.type.value if hasattr(e.type, "value") else str(e.type)
        entry: dict = {"type": etype, "offset": e.offset, "length": e.length}
        if e.url:
            entry["url"] = e.url
        if getattr(e, "custom_emoji_id", None):
            entry["custom_emoji_id"] = e.custom_emoji_id
        if getattr(e, "language", None):
            entry["language"] = e.language
        entities_list.append(entry)
    entities_json = _json.dumps(entities_list) if entities_list else None

    if msg.photo:
        photo = msg.photo[-1]
        file = await ctx.bot.get_file(photo.file_id)
        path = os.path.join(DATA_DIR, f"media_{user_id}_{count}.jpg")
        await file.download_to_drive(path)
        await db.add_message(user_id, content=(msg.caption or ""), media_path=path,
                             media_type="photo", link_preview_disabled=no_preview,
                             reply_to_index=reply_to_index, entities=entities_json)
        type_label = "emoji_6120625823285251747 Image"

    elif msg.sticker:
        # Stickers are real Telegram media, not text.  Older versions fell
        # through to the text branch, stored an empty message, and later the
        # sender raised: "Message 1 has no text or available media".
        # Preserve the sticker itself so Telethon can send the exact file.
        sticker = msg.sticker
        file = await ctx.bot.get_file(sticker.file_id)
        if getattr(sticker, "is_animated", False):
            ext = ".tgs"
        elif getattr(sticker, "is_video", False):
            ext = ".webm"
        else:
            ext = ".webp"
        path = os.path.join(DATA_DIR, f"media_{user_id}_{count}{ext}")
        await file.download_to_drive(path)
        await db.add_message(user_id, content="", media_path=path,
                             media_type="sticker", link_preview_disabled=False,
                             reply_to_index=reply_to_index, entities=None)
        type_label = "emoji_6257858798715670989 Sticker"

    elif msg.document:
        file = await ctx.bot.get_file(msg.document.file_id)
        path = os.path.join(DATA_DIR, f"media_{user_id}_{count}_{msg.document.file_name}")
        await file.download_to_drive(path)
        await db.add_message(user_id, content=(msg.caption or ""), media_path=path,
                             media_type="document", link_preview_disabled=no_preview,
                             reply_to_index=reply_to_index, entities=entities_json)
        type_label = "emoji_6129801569941592173 File"

    else:
        await db.add_message(user_id, content=(msg.text or ""),
                             link_preview_disabled=no_preview,
                             reply_to_index=reply_to_index, entities=entities_json)
        type_label = "emoji_6073288235642000201 Text"

    notes = []
    if no_preview:
        notes.append("emoji_6071188061058766421 no link preview")
    if is_reply:
        notes.append(f"↩️ reply to message {reply_to_index}")
    entity_note = (f"emoji_5206607081334906820 `{len(entities_list)}` formatting "
                   f"entr{'y' if len(entities_list)==1 else 'ies'} preserved\n"
                   if entities_list else "")
    note_line = ("  _(" + ", ".join(notes) + ")_") if notes else ""

    await update.message.reply_text(
        f"emoji_5877618313139327986 *{type_label} saved! ({count} total)*{note_line}\n"
        + (entity_note if entity_note else "")
        + ("\n"
            f"↩️ *Reply chain detected* — message {count} will be sent as a "
            f"reply to message {reply_to_index} in every DM.\n\n"
            if is_reply else "\n")
        + "Send another message to add more,\nor tap *Done* to finish.",
        parse_mode="Markdown",
        reply_markup=done_kb(count),
    )
    return SET_MSG_COLLECT


