async def handle_camp_channel(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    user_id = update.effective_user.id
    text = update.message.text.strip()
    channel, label = _parse_channel_input(text)
    ctx.user_data["camp_channel"] = channel
    ctx.user_data["camp_label"] = label

    wait_msg = await update.message.reply_text(
        f"emoji_6147565374289220368 Fetching pending join requests for `{label}`…",
        parse_mode="Markdown",
    )

    try:
        importers, total = await userbot.get_pending_join_requests(user_id, channel)
    except Exception as ex:
        await wait_msg.edit_text(
            f"emoji_5337312745857501717 *Error fetching requests*\n\n`{ex}`\n\n"
            "Make sure you are an admin of that channel.",
            parse_mode="Markdown",
            reply_markup=back_kb(),
        )
        return ConversationHandler.END

    if total == 0:
        await wait_msg.edit_text(
            f"ℹ️ *No pending join requests* found for `{label}`.",
            parse_mode="Markdown",
            reply_markup=back_kb(),
        )
        return ConversationHandler.END

    is_premium = await db.check_premium_active(user_id)
    free_limit = await db.get_free_limit()
    # Store only the real Telegram count — user IDs are fetched on-demand
    # via fetch_join_request_users (paginated) so no pre-fetching cap applies.
    ctx.user_data["camp_total"] = total
    ctx.user_data["camp_channel"] = channel
    ctx.user_data["camp_label"] = label

    available = total if is_premium else min(total, free_limit)
    limit_note = "Unlimited (VIP)" if is_premium else f"Free limit: {free_limit}"
    await wait_msg.edit_text(
        f"emoji_5778271407435682765 *Pending Join Requests: {total:,}*\n"
        f"{DIVIDER}\n"
        f"emoji_5249050854392091366 Channel: `{label}`\n"
        f"emoji_5215579104807497179 {limit_note}\n\n"
        f"Send a number (1–{available:,}) for how many users to DM:",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [cancel_button("emoji_6123107313654960925 Cancel", callback_data="cb_back")]
        ]),
    )
    return CAMP_COUNT_INPUT


async def handle_camp_count(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    user_id  = update.effective_user.id
    text     = update.message.text.strip()
    label    = ctx.user_data.get("camp_label", "channel")
    channel  = ctx.user_data.get("camp_channel", "")
    camp_total = ctx.user_data.get("camp_total", 0)

    try:
        amount = int(text)
        if amount <= 0:
            raise ValueError
    except ValueError:
        await update.message.reply_text("emoji_5337312745857501717 Invalid number. Send a valid integer (e.g. 50).")
        return CAMP_COUNT_INPUT

    is_premium = await db.check_premium_active(user_id)
    free_limit = await db.get_free_limit()

    # Enforce free plan cap
    if not is_premium and amount > free_limit:
        await update.message.reply_text(
            f"emoji_5337312745857501717 *Free limit is {free_limit} users.*\n\n"
            "Upgrade to VIP Premium for unlimited DMs! emoji_5472239203590888751",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [vip_button("💎 Buy Premium", callback_data="cb_premium")],
                [cancel_button("emoji_6123107313654960925 Cancel", callback_data="cb_back")],
            ]),
        )
        return CAMP_COUNT_INPUT

    # Premium users cannot target more than what actually exists
    if is_premium and amount > camp_total:
        await update.message.reply_text(
            f"emoji_5454415424319931791️ Only *{camp_total:,}* pending join requests exist for `{label}`.\n"
            f"Please enter a number between *1* and *{camp_total:,}*.",
            parse_mode="Markdown",
        )
        return CAMP_COUNT_INPUT

    # Cap free users to what actually exists
    if not is_premium:
        amount = min(amount, camp_total)

    msgs = await db.get_user_messages(user_id)
    client = userbot.get_client(user_id)
    if not client or not await client.is_user_authorized():
        await update.message.reply_text(
            "emoji_5337312745857501717 Your account is not linked. Please add your account first.",
            reply_markup=back_kb(),
        )
        return ConversationHandler.END

    # Fetch exact target users via pagination — no pre-fetch cap, no get_entity() needed
    fetch_msg = await update.message.reply_text(
        f"emoji_6147565374289220368 *Fetching {amount:,} users from join requests…*\n\n"
        f"{DIVIDER}\n"
        f"emoji_5249050854392091366 Channel: `{label}`\n"
        f"emoji_5778271407435682765 Target: *{amount:,}*\n\n"
        "Please wait…",
        parse_mode="Markdown",
    )

    try:
        target_users, _ = await userbot.fetch_join_request_users(user_id, channel, amount)
    except Exception as ex:
        await fetch_msg.edit_text(
            f"emoji_5337312745857501717 *Failed to fetch join request users*\n\n`{ex}`",
            parse_mode="Markdown",
            reply_markup=back_kb(),
        )
        return ConversationHandler.END

    if not target_users:
        await fetch_msg.edit_text(
            "emoji_5337312745857501717 No pending join request users found. They may have already been processed.",
            parse_mode="Markdown",
            reply_markup=back_kb(),
        )
        return ConversationHandler.END

    # ══════════════════════════════════════════════════════════════════════════
    # REQUEST-DM CAMPAIGN ENGINE
    # ══════════════════════════════════════════════════════════════════════════
    #
    # ROOT CAUSE of old 70% failure rate:
    #   Sending 25 concurrent DMs with zero delay triggers Telegram's
    #   PeerFloodError after ~150 sends.  Once that error fires, the ENTIRE
    #   ACCOUNT is restricted and EVERY remaining send fails immediately —
    #   giving the illusion that those users "can't receive messages".
    #
    # FIX:
    #   1. Sequential sends (concurrency = 1) with a short inter-send delay
    #      so Telegram never sees a burst that triggers PeerFloodError.
    #   2. PeerFloodError → pause the whole campaign for 5 min, then resume.
    #   3. FloodWaitError → honour Telegram's own wait, then retry same user.
    #   4. UserPrivacyRestricted / Deactivated / Stars → genuine, skip.
    #   5. Fetch a 50% buffer so genuine skips don't prevent hitting target.
    # ══════════════════════════════════════════════════════════════════════════

    TARGET     = amount
    sent       = 0      # successful deliveries
    failed     = 0      # genuine, permanent failures (privacy/deactivated/stars)
    skipped    = 0      # peer-flood pauses resolved — just for internal tracking
    _campaign_paused = False   # set True while waiting out a PeerFlood

    # ── Fetch a buffer of users upfront ──────────────────────────────────────
    # Fetch 3× the target (min +300) — privacy-restricted users are skipped
    # instantly, so even if 30–40% of the pool can't receive DMs we still
    # have enough eligible users to hit TARGET successful deliveries.
    buffer      = max(TARGET * 2, 300)
    fetch_count = min(camp_total, TARGET + buffer)

    all_users = list(target_users)
    seen_ids  = {u.id for u in all_users}

    if fetch_count > len(all_users):
        try:
            extra_users, _ = await userbot.fetch_join_request_users(
                user_id, channel, fetch_count
            )
            for u in extra_users:
                if u.id not in seen_ids:
                    all_users.append(u)
                    seen_ids.add(u.id)
        except Exception as ex:
            logger.warning("JR-campaign extra fetch failed: %s", ex)

    # ── ETA formatter (minutes only) ─────────────────────────────────────────
    def _fmt_eta_mins_jr(secs: float) -> str:
        if secs <= 0:
            return "< 1 minute"
        m = max(1, int(secs / 60 + 0.5))
        return f"{m} minute{'s' if m != 1 else ''}"

    # ── Progress helper ───────────────────────────────────────────────────────
    start_time = time.monotonic()
    async def _update_progress():
        pct    = min(100, round(100 * sent / TARGET)) if TARGET else 100
        filled = min(18, round(18 * sent / TARGET)) if TARGET else 18
        bar    = "█" * filled + "░" * (18 - filled)
        
        # Calculate ETA based on actual elapsed time for accuracy
        elapsed = time.monotonic() - start_time
        if sent > 0 and elapsed > 0:
            avg_rate = sent / elapsed  # messages per second
            remaining_secs = max(0, (TARGET - sent) / avg_rate) if avg_rate > 0 else 0
        else:
            remaining_secs = TARGET * INTER_SEND_DELAY
        
        rem_str = _fmt_eta_mins_jr(remaining_secs)
        try:
            await fetch_msg.edit_text(
                f"emoji_5472239203590888751 *Campaign Running…*\n\n"
                f"{DIVIDER}\n"
                f"emoji_5287651735525937879 Channel: `{label}`\n"
                f"emoji_6147565374289220368 Est. remaining: `{rem_str}`\n"
                f"`[{bar}]` {pct}%\n"
                f"emoji_5287651735525937879 Sent: `{sent:,}` / `{TARGET:,}`\n"
                f"emoji_5337312745857501717 Failed: `{failed:,}`",
                parse_mode="Markdown",
                reply_markup=_stop_kb(),
            )
        except Exception:
            pass

    # ── Launched card ─────────────────────────────────────────────────────────
    # More accurate ETA: TARGET messages × 0.25s per message
    eta_launch = _fmt_eta_mins_jr(TARGET * INTER_SEND_DELAY * 1.2)
    await fetch_msg.edit_text(
        f"emoji_5472239203590888751 *Campaign Launched — Running in Background!*\n\n"
        f"{DIVIDER}\n"
        f"emoji_5287651735525937879 Channel: `{label}`\n"
        f"emoji_6147565374289220368 Est. remaining: *{eta_launch}*\n"
        f"`[{'░' * 18}]` 0%\n"
        f"emoji_5287651735525937879 Sent: `0` / `{TARGET:,}`\n"
        f"emoji_5337312745857501717 Failed: `0`\n\n"
        f"emoji_5197269100878907942 _You can close this chat — the campaign keeps running._",
        parse_mode="Markdown",
        reply_markup=_stop_kb(),
    )

    # ── Sequential send loop ──────────────────────────────────────────────────
    # ONE send at a time with a short inter-send gap.
    # 0.80 s → ~75 msgs/min. This is deliberately steadier for account-level limits.
    INTER_SEND_DELAY = 0.45         # fast controlled pacing; Telegram FloodWait is always honored
    last_update      = 0            # monotonic time of last progress edit
    _flood_pause_active = False     # flag to prevent repeated pauses
    
    # ── Flood recovery helper ────────────────────────────────────────────────
    async def _handle_peer_flood_pause(pause_mins: int = 6):
        """Pause entire campaign when Telegram rate-limits us, then resume."""
        nonlocal _flood_pause_active
        if _flood_pause_active:
            return  # already paused once, don't repeat
        
        _flood_pause_active = True
        pause_secs = pause_mins * 60
        pause_until = time.monotonic() + pause_secs
        
        logger.warning("JR PeerFlood detected! Pausing campaign for %d minutes…", pause_mins)
        
        # Update UI to show pause
        pct = min(100, round(100 * sent / TARGET)) if TARGET else 0
        filled = min(18, round(18 * sent / TARGET)) if TARGET else 0
        bar = "█" * filled + "░" * (18 - filled)
        
        try:
            await fetch_msg.edit_text(
                f"emoji_5472239203590888751 *Campaign Paused — Rate Limited*\n\n"
                f"{DIVIDER}\n"
                f"emoji_5287651735525937879 Channel: `{label}`\n"
                f"emoji_6147565374289220368 Resuming in ~{pause_mins} minutes…\n"
                f"`[{bar}]` {pct}%\n"
                f"emoji_5287651735525937879 Sent: `{sent:,}` / `{TARGET:,}`\n"
                f"emoji_5337312745857501717 Failed: `{failed:,}`\n\n"
                f"_Telegram restricted the account. Waiting before retry…_",
                parse_mode="Markdown",
                reply_markup=_stop_kb(),
            )
        except Exception:
            pass
        
        # Wait in chunks of 10 seconds so we can update progress
        while time.monotonic() < pause_until:
            remaining = pause_until - time.monotonic()
            if remaining <= 0:
                break
            await asyncio.sleep(min(10, remaining))
            
            # Update remaining time every 30 seconds
            if int(remaining / 30) % 2 == 0:
                try:
                    rem_mins = max(1, int(remaining / 60))
                    await fetch_msg.edit_text(
                        f"emoji_5472239203590888751 *Campaign Paused — Rate Limited*\n\n"
                        f"{DIVIDER}\n"
                        f"emoji_5287651735525937879 Channel: `{label}`\n"
                        f"emoji_6147565374289220368 Resuming in ~{rem_mins} minute{'s' if rem_mins != 1 else ''}…\n"
                        f"`[{bar}]` {pct}%\n"
                        f"emoji_5287651735525937879 Sent: `{sent:,}` / `{TARGET:,}`\n"
                        f"emoji_5337312745857501717 Failed: `{failed:,}`",
                        parse_mode="Markdown",
                        reply_markup=_stop_kb(),
                    )
                except Exception:
                    pass
        
        logger.info("JR PeerFlood pause ended, resuming campaign…")

    for user_idx, user in enumerate(all_users):
        uid_str  = str(getattr(user, "id", "?"))
        ok       = False
        silently_skip = False       # True = privacy/deactivated, no delay needed
        peer_flooded = False        # track if we hit PeerFloodError

        for attempt in range(3):    # reduced attempts for faster processing
            try:
                for msg in msgs:
                    if msg.get("media_path") and os.path.exists(msg["media_path"]):
                        try:
                            await client.send_file(
                                user, msg["media_path"],
                                caption=msg.get("content") or "",
                            )
                        except Exception as media_err:
                            logger.debug("JR send_file failed uid=%s: %s", uid_str, media_err)
                            # Fall back to text-only if media fails
                            if msg.get("content"):
                                await client.send_message(user, msg["content"])
                    elif msg.get("content"):
                        await client.send_message(user, msg["content"])
                ok = True
                break               # success

            # ── FloodWaitError: per-request rate limit ───────────────────────
            except FloodWaitError as fw:
                wait_secs = max(1, int(fw.seconds))
                logger.info("JR FloodWait %ds uid=%s; waiting silently", wait_secs, uid_str)
                await asyncio.sleep(wait_secs)
                # retry same user

            # ── PeerFloodError: PAUSE ENTIRE CAMPAIGN ────────────────────────
            except PeerFloodError:
                logger.warning("JR PeerFlood uid=%s — account rate-limited; silent recovery", uid_str)
                peer_flooded = True
                await asyncio.sleep(30)
                peer_flooded = False
                continue

            # ── Privacy / deactivated: instant silent skip ───────────────────
            except (UserPrivacyRestrictedError,
                    UserDeactivatedError,
                    UserDeactivatedBanError):
                logger.debug("JR silent skip (privacy/deactivated) uid=%s", uid_str)
                silently_skip = True
                break

            # ── Catch-all ────────────────────────────────────────────────────
            except Exception as exc:
                err = str(exc).lower()
                permanently_unreachable = any(x in err for x in (
                    "deactivated", "deleted", "user_deactivated",
                    "stars", "starsrequired", "premium_required",
                    "user_blocked", "inputuserfrom", "cannot_send_to_user",
                ))
                if permanently_unreachable:
                    logger.debug("JR silent skip (permanent) uid=%s: %s", uid_str, exc)
                    silently_skip = True
                    break
                # Transient error — minimal back off for speed
                logger.debug("JR transient uid=%s attempt=%d: %s", uid_str, attempt + 1, exc)
                await asyncio.sleep(min(0.5 * attempt, 2))

        if ok:
            sent += 1
            # OPTIMIZED: Ultra-fast inter-send gap (0.25s instead of 0.7s)
            # This allows 240 msgs/min instead of 86 msgs/min
            await asyncio.sleep(INTER_SEND_DELAY)
        elif not silently_skip and not peer_flooded:
            # Retryable error that exhausted all attempts — count as failed
            failed += 1
        
        # Add small async yield every 10 users to prevent blocking
        if (user_idx + 1) % 10 == 0:
            await asyncio.sleep(0.01)

        # Keep progress silent while sending. Final statistics are shown only
        # after the complete target list has been processed.
        if (user_idx + 1) % 100 == 0:
            logger.info("JR campaign processed %d/%d sent=%d skipped=%d", user_idx + 1, len(all_users), sent, failed)

    # ── Final summary — real numbers ──────────────────────────────────────────
    bar_full = "█" * 18
    await fetch_msg.edit_text(
        done_message_html(
            f"emoji_5399967660052081305 *Campaign Complete!*\n\n"
        f"{DIVIDER}\n"
        f"emoji_5287651735525937879 Channel: `{label}`\n"
        f"`[{bar_full}]` 100%\n"
        f"emoji_5287651735525937879 Sent: *{sent:,}* / {TARGET:,}\n"
        f"emoji_5337312745857501717 Failed: *{failed:,}*\n"
        f"{DIVIDER}\n\n"
        "emoji_5877618313139327986 Great job! emoji_5472239203590888751"
        ),
        parse_mode="HTML",
        reply_markup=await get_main_menu_kb(),
    )
    ctx.user_data.clear()
    return ConversationHandler.END


