# ── Add Account conversation ──────────────────────────────────────────────────
async def cb_addaccount(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()
    await _clear_user_convs(update)
    if not await check_banned_for_callback(update, ctx):
        return
    user_id = update.effective_user.id
    acc = await db.get_account(user_id)
    if acc:
        await q.message.reply_text(
            f"emoji_5877618313139327986 *Account Already Linked*\n\n"
            f"{DIVIDER}\n"
            f"emoji_5778271407435682765 Phone: `{acc['phone']}`\n\n"
            "Use *Remove Account* first if you want to switch accounts.",
            parse_mode="Markdown",
            reply_markup=back_kb(),
        )
        return ConversationHandler.END

    # Recover from a previous failed OTP/2FA attempt. Telegram can keep an
    # unauthorised MTProto login session in a state where the next
    # send_code_request returns RESEND_CODE_* errors instead of sending a new
    # code. A fresh Add Account attempt must start from a clean unauthorised
    # session. Never touch an already-authorized account here.
    try:
        existing_phone = await userbot.get_authorized_account_phone(user_id)
        if existing_phone:
            await db.add_account(user_id, existing_phone)
            await q.message.reply_text(
                f"emoji_5877618313139327986 *Account Already Linked*\n\n"
                f"{DIVIDER}\n"
                f"emoji_5778271407435682765 Phone: `{existing_phone}`\n\n"
                "Use *Remove Account* first if you want to switch accounts.",
                parse_mode="Markdown",
                reply_markup=back_kb(),
            )
            return ConversationHandler.END
        await userbot.reset_login_attempt(user_id)
    except Exception:
        logger.exception("Could not reset stale login attempt for user %s", user_id)

    await q.message.reply_text(
        f"emoji_5276032951342088188 *ADD YOUR TELEGRAM ACCOUNT*\n"
        f"{DIVIDER}\n\n"
        "*Step 1 of 3 — Phone Number*\n\n"
        "Enter your phone number with country code:\n"
        "Example: `+91XXXXXXXXXX`\n\n"
        "emoji_5210952531676504517 _Your account is only used to send DMs — we never access personal data._",
        parse_mode="Markdown",
    )
    return ADD_PHONE


async def handle_add_phone(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Start Telegram user-account login and keep the OTP conversation alive.

    The old version performed the DB state write outside the protected block.
    If that write (or the OTP prompt itself) raised after Telegram had already
    sent the code, ConversationHandler lost ADD_CODE and the global handler
    replied with the generic ``Something went wrong`` message.  This version
    treats OTP delivery + state persistence as one guarded operation and
    never silently drops the conversation.
    """
    phone = (update.message.text or "").strip().replace(" ", "")
    user_id = update.effective_user.id

    if not phone.startswith("+"):
        await update.message.reply_text(
            "emoji_5454415424319931791️ Include country code. Example: `+91XXXXXXXXXX`",
            parse_mode="Markdown",
        )
        return ADD_PHONE

    # Basic E.164 sanity check before opening a Telethon connection.
    digits = phone[1:]
    if not digits.isdigit() or not (8 <= len(digits) <= 15):
        await update.message.reply_text(
            "emoji_5454415424319931791️ Please enter a valid phone number with country code.\n"
            "Example: `+919876543210`",
            parse_mode="Markdown",
        )
        return ADD_PHONE

    status_msg = await update.message.reply_text(
        f"emoji_5837003105228558796 *Sending OTP to {phone}…*\n\n"
        "_Please wait a moment…_",
        parse_mode="Markdown",
    )

    try:
        phone_code_hash = await userbot.send_code(user_id, phone)
        if not phone_code_hash:
            raise RuntimeError("Telegram did not return a phone code hash.")

        # Store the login state BEFORE showing the OTP prompt.  If the DB is
        # temporarily unavailable, keep the conversation in ADD_PHONE rather
        # than falling through to the global error handler.
        ctx.user_data["phone"] = phone
        ctx.user_data["phone_code_hash"] = phone_code_hash
        try:
            await db.upsert_user(
                user_id, phone=phone, phone_code_hash=phone_code_hash, state="code"
            )
        except Exception as db_ex:
            logger.exception("Could not persist OTP state for user %s", user_id)
            # The Telethon client is still holding the pending login request,
            # so keep the local conversation alive and let the user continue.
            await status_msg.edit_text(
                "⚠️ *OTP was requested successfully, but I could not save the temporary state.*\n\n"
                "Please tap *Retry OTP* below. Your current login attempt was not completed.",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup([
                    [user_button("🔄 Retry OTP", callback_data="cb_addaccount")],
                    [user_button("🔙 Back", callback_data="cb_back")],
                ]),
            )
            logger.error("OTP state DB error: %s", db_ex)
            return ConversationHandler.END

        await status_msg.edit_text(
            f"emoji_5877618313139327986 *OTP Sent to {phone}!*\n\n"
            f"{DIVIDER}\n"
            "*Step 2 of 3 — Enter OTP*\n\n"
            "Check your Telegram app for the code.\n"
            "Enter the code here (spaces are optional):\n"
            "Example: `1 2 3 4 5`",
            parse_mode="Markdown",
        )
        return ADD_CODE

    except Exception as ex:
        logger.exception("Add-account OTP request failed for user %s", user_id)
        # Make Telethon login state recoverable for a retry.
        try:
            ctx.user_data.pop("phone_code_hash", None)
            ctx.user_data["phone"] = phone
        except Exception:
            pass
        try:
            await db.upsert_user(user_id, phone=phone, state="idle")
        except Exception:
            pass
        try:
            await status_msg.edit_text(
                f"emoji_5337312745857501717 *Failed to Send OTP*\n\n"
                f"{DIVIDER}\n"
                f"Reason: `{_otp_reason(ex)[:900]}`\n\n"
                "Please double-check the number and try again. If the problem continues, verify that your Telegram API ID/API HASH are correct.",
                parse_mode="Markdown",
                reply_markup=await get_main_menu_kb(),
            )
        except Exception:
            await update.message.reply_text(
                "❌ Failed to send OTP. Please try again.",
                reply_markup=await get_main_menu_kb(),
            )
        return ConversationHandler.END


def _otp_reason(ex: Exception) -> str:
    """Readable reason for a failed OTP request."""
    try:
        from telethon.errors import FloodWaitError
        if isinstance(ex, FloodWaitError):
            return f"Telegram asked to wait {int(ex.seconds)} seconds before sending another code."
    except Exception:
        pass
    text = str(ex) or ex.__class__.__name__
    return text


async def handle_add_code(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    code = (update.message.text or "").strip().replace(" ", "")
    user_id = update.effective_user.id
    phone = ctx.user_data.get("phone")
    phone_code_hash = ctx.user_data.get("phone_code_hash")

    if not code or not code.isdigit() or not (4 <= len(code) <= 8):
        await update.message.reply_text(
            "⚠️ Please enter the OTP digits only. Example: `1 2 3 4 5`",
            parse_mode="Markdown",
        )
        return ADD_CODE
    if not phone or not phone_code_hash:
        await update.message.reply_text(
            "⚠️ This OTP session has expired. Please tap *Add Account* and request a new code.",
            parse_mode="Markdown",
            reply_markup=await get_main_menu_kb(),
        )
        return ConversationHandler.END

    try:
        await userbot.sign_in(user_id, phone, code, phone_code_hash)
        await db.add_account(user_id, phone)
        await db.upsert_user(user_id, state="idle")
        await db.mark_referral_account_added(user_id)   # referral step 1
        stats = await db.get_stats(user_id) or {}
        await update.message.reply_text(
            f"emoji_5399967660052081305 *Congratulations! Your Telegram account has been added successfully.*\n\n"
            f"{DIVIDER}\n"
            f"emoji_5778271407435682765 Phone: `{phone}`\n"
            f"🆓 Free sends available: *{await db.get_free_limit()}*\n"
            f"{DIVIDER}\n\n"
            "You can now start using all of the available services and features. emoji_5472239203590888751",
            parse_mode="Markdown",
            reply_markup=await get_main_menu_kb(),
        )
        return ConversationHandler.END
    except Exception as ex:
        if "password" in str(ex).lower() or "2fa" in str(ex).lower() or "SessionPasswordNeeded" in str(ex):
            ctx.user_data["code"] = code
            await update.message.reply_text(
                f"emoji_6222083761249455605 *2FA Password Required*\n\n"
                f"{DIVIDER}\n"
                "*Step 3 of 3 — Two-Factor Authentication*\n\n"
                "Your account has 2FA enabled.\n"
                "Enter your Telegram 2FA password:",
                parse_mode="Markdown",
            )
            return ADD_2FA
        # Do not leave Telegram's failed login attempt alive. It can poison
        # the next Add Account -> OTP request with RESEND_CODE errors.
        try:
            await userbot.reset_login_attempt(user_id)
        except Exception:
            logger.exception("Could not reset failed OTP login for user %s", user_id)
        ctx.user_data.pop("phone_code_hash", None)
        ctx.user_data.pop("phone", None)
        await db.upsert_user(user_id, state="idle")
        await update.message.reply_text(
            f"emoji_5337312745857501717 *Invalid OTP*\n\n"
            f"{DIVIDER}\n"
            f"Error: `{ex}`\n\n"
            "This login attempt has been reset. Tap *Add Account* to request a fresh OTP.",
            parse_mode="Markdown",
            reply_markup=await get_main_menu_kb(),
        )
        return ConversationHandler.END


async def handle_add_2fa(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """V88: Handle 2FA - Better error handling & database fix."""
    password = update.message.text.strip()
    user_id = update.effective_user.id
    phone = ctx.user_data.get("phone")

    if not password:
        await update.message.reply_text(
            "emoji_5337312745857501717 *2FA Password Required*\n\n"
            "Please enter your 2FA password (not empty):",
            parse_mode="Markdown",
        )
        return ADD_2FA

    try:
        # V88: Sign in with 2FA password
        await userbot.sign_in_2fa(user_id, password)
        logger.info("[V88] 2FA successful for user %s phone %s", user_id, phone)
        
        # V88: Add account with better error handling
        try:
            await db.add_account(user_id, phone)
        except Exception as db_ex:
            logger.error("[V88] DB add_account failed: %s", db_ex)
            # V88: Try alternative - maybe DB is locked, wait and retry
            await asyncio.sleep(1)
            try:
                await db.add_account(user_id, phone)
            except Exception as db_ex2:
                logger.error("[V88] DB add_account retry failed: %s", db_ex2)
                raise db_ex2
        
        await db.upsert_user(user_id, state="idle")
        await db.mark_referral_account_added(user_id)
        
        await update.message.reply_text(
            f"emoji_5399967660052081305 *Account Added Successfully!*\n\n"
            f"{DIVIDER}\n"
            f"emoji_5778271407435682765 Phone: `{phone}`\n"
            f"emoji_6222083761249455605 2FA: emoji_5877618313139327986 Verified ✓\n"
            f"🆓 Free sends: *{FREE_DM_LIMIT}*\n"
            f"{DIVIDER}\n\n"
            "Your account is ready to use! Start a campaign now.",
            parse_mode="Markdown",
            reply_markup=await get_main_menu_kb(),
        )
        logger.info("[V88] User %s successfully added account %s", user_id, phone)
        
    except Exception as ex:
        error_str = str(ex).lower()
        is_wrong_password = "password" in error_str or "2fa" in error_str or "invalid" in error_str
        
        logger.error("[V88] 2FA/Add error for user %s: %s", user_id, ex)
        
        # V88: Reset login properly
        try:
            await userbot.reset_login_attempt(user_id)
        except Exception as reset_ex:
            logger.error("[V88] Could not reset login: %s", reset_ex)
        
        ctx.user_data.pop("phone_code_hash", None)
        ctx.user_data.pop("phone", None)
        ctx.user_data.pop("code", None)
        await db.upsert_user(user_id, state="idle")
        
        # V88: Different messages based on error type
        if is_wrong_password:
            error_msg = "Wrong 2FA Password"
            hint = "Check that you're entering the correct 2FA password."
        elif "write" in error_str or "readonly" in error_str:
            error_msg = "Database Error"
            hint = "Our server had a temporary issue. Please try again."
        else:
            error_msg = "Login Failed"
            hint = "Please try again with a fresh OTP."
        
        await update.message.reply_text(
            f"emoji_5337312745857501717 *{error_msg}*\n\n"
            f"{DIVIDER}\n"
            f"Error: `{str(ex)[:100]}`\n\n"
            f"{hint}\n"
            "Tap *Add Account* to start fresh.",
            parse_mode="Markdown",
            reply_markup=await get_main_menu_kb(),
        )
    
    return ConversationHandler.END


