def _resolve_bot_username() -> str:
    """Return the effective bot username from env var (sync, used as fallback)."""
    return (BOT_USERNAME or "").strip().lstrip("@")


async def _get_referral_link(user_id: int) -> str:
    """Build the correct referral link using the DB-configured username first,
    then falling back to the BOT_USERNAME environment variable."""
    db_uname = await db.get_bot_username()
    uname = db_uname or _resolve_bot_username() or "YourBot"
    return f"https://t.me/{uname}?start=ref_{user_id}"


async def cb_refer(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    await q.answer()

    user_id = update.effective_user.id
    referral_link = await _get_referral_link(user_id)
    stats, reward_days, milestones = await asyncio.gather(
        db.get_referrer_stats(user_id),
        db.get_referral_reward_days(),
        db.get_referral_milestones(),
    )

    msg = _build_refer_message(user_id, referral_link, stats, reward_days, milestones)

    kb = InlineKeyboardMarkup([
        [_gbtn("emoji_6271384200486589609 Share My Referral Link", switch_inline_query=referral_link)],
        [_bbtn("emoji_6123107313654960925 Back to Menu", callback_data="cb_back")],
    ])
    await q.message.reply_text(msg, parse_mode="Markdown", reply_markup=kb)


