async def handle_autoreply_collect(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Capture any message type and save it as the auto-reply."""
    msg = update.message
    user_id = update.effective_user.id

    media_type = "text"
    file_id = None
    content = msg.text or msg.caption or ""

    if msg.photo:
        media_type = "photo"
        file_id = msg.photo[-1].file_id  # largest size
    elif msg.video:
        media_type = "video"
        file_id = msg.video.file_id
    elif msg.animation:
        media_type = "animation"
        file_id = msg.animation.file_id
    elif msg.voice:
        media_type = "voice"
        file_id = msg.voice.file_id
    elif msg.video_note:
        media_type = "video_note"
        file_id = msg.video_note.file_id
    elif msg.document:
        media_type = "document"
        file_id = msg.document.file_id
    elif msg.sticker:
        media_type = "sticker"
        file_id = msg.sticker.file_id
    elif msg.audio:
        media_type = "audio"
        file_id = msg.audio.file_id

    await db.set_auto_reply(user_id, media_type, file_id, content, mode="manual")

    # Tell userbot to re-register the handler so it picks up the new reply
    client = userbot.get_client(user_id)
    if client:
        await userbot.setup_auto_reply_handler(user_id, client)

    await msg.reply_text(
        f"emoji_5877618313139327986 *Auto Reply saved!*\n\n"
        f"{DIVIDER}\n"
        f"emoji_5447183459602669338 Type: `{media_type}`\n"
        + (f"emoji_5832262406226579218 Content: _{content[:80]}{'…' if len(content) > 80 else ''}_\n" if content else "")
        + f"{DIVIDER}\n\n"
        "From now on, every DM to your Telegram account will be automatically "
        "replied to with this message — even when you're offline.\n\n"
        "Tap *Set Auto Reply* again to change it at any time.",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [_bbtn("emoji_6070920317092500169 Back to Menu", callback_data="cb_back")],
        ]),
    )
    return ConversationHandler.END


