async def cb_setads(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Entry point: show management screen if ads active, otherwise start setup."""
    q = update.callback_query
    await q.answer()
    await _clear_user_convs(update)

    if not await ensure_account(update):
        return ConversationHandler.END
    if not await ensure_not_banned(update):
        return ConversationHandler.END

    user_id = update.effective_user.id
    existing = await db.get_ad(user_id)
    if existing and existing.get("is_active"):
        target_map = {
            "chats":  "emoji_6271665430650163493 Chats & Contacts",
            "groups": "emoji_5778271407435682765 Groups",
            "both":   "emoji_6269118781331609137 Chats, Contacts & Groups",
        }
        target_label = target_map.get(existing.get("target", "both"), "emoji_6269118781331609137 Chats, Contacts & Groups")
        delay = existing.get("delay_minutes", 5)
        std_delays = {5: "Every 5 Minutes", 15: "Every 15 Minutes", 20: "Every 20 Minutes"}
        delay_label = std_delays.get(int(delay), f"Every {delay} Minutes (Custom)")
        lp_val = existing.get("link_preview", 0)
        preview_label = "emoji_5877618313139327986 Show Preview" if lp_val else "emoji_6116290955743073366 No Preview"
        await q.message.reply_text(
            f"emoji_5769547529993588669 *Advertisement — Status*\n\n"
            f"{DIVIDER}\n"
            f"emoji_5877618313139327986 *Status:*        Active & Running\n"
            f"emoji_6006051952847230749 *Target:*        {target_label}\n"
            f"⏱ *Interval:*      {delay_label}\n"
            f"emoji_5197269100878907942 *Link Preview:*  {preview_label}\n"
            f"{DIVIDER}\n\n"
            "Your advertisement is running automatically in the "
            "background — even when you're offline.\n\n"
            "What would you like to do?",
            parse_mode="Markdown",
            reply_markup=_ads_manage_kb(),
        )
        return ADS_MANAGE

    return await _start_ads_setup(q.message, update.effective_user)


