async def handle_ads_collect(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Receive the ad message, preserve all formatting entities, prompt for target."""
    import json as _json
    msg = update.message
    user_id = update.effective_user.id

    # Detect media type — all types allowed for all users (free & premium)
    media_type = "text"
    file_id = None
    content = msg.text or msg.caption or ""

    if msg.photo:
        media_type, file_id = "photo", msg.photo[-1].file_id
    elif msg.video:
        media_type, file_id = "video", msg.video.file_id
    elif msg.animation:
        media_type, file_id = "animation", msg.animation.file_id
    elif msg.voice:
        media_type, file_id = "voice", msg.voice.file_id
    elif msg.video_note:
        media_type, file_id = "video_note", msg.video_note.file_id
    elif msg.document:
        media_type, file_id = "document", msg.document.file_id
    elif msg.sticker:
        media_type, file_id = "sticker", msg.sticker.file_id
    elif msg.audio:
        media_type, file_id = "audio", msg.audio.file_id

    # Serialise all formatting entities (bold/italic/spoiler/custom-emoji/etc.)
    raw_entities = msg.entities or msg.caption_entities or []
    entities_list = []
    for e in raw_entities:
        etype = e.type.value if hasattr(e.type, "value") else str(e.type)
        entry: dict = {"type": etype, "offset": e.offset, "length": e.length}
        if e.url:
            entry["url"] = e.url
        if getattr(e, "custom_emoji_id", None):
            entry["custom_emoji_id"] = e.custom_emoji_id
        if getattr(e, "language", None):
            entry["language"] = e.language
        entities_list.append(entry)
    entities_json = _json.dumps(entities_list) if entities_list else None

    # Stash everything in user_data until target+delay are chosen
    ctx.user_data["ads_media_type"] = media_type
    ctx.user_data["ads_file_id"]    = file_id
    ctx.user_data["ads_content"]    = content
    ctx.user_data["ads_entities"]   = entities_json

    type_icons = {
        "text": "emoji_5832262406226579218 Text", "photo": "emoji_6120625823285251747 Photo", "video": "emoji_6028565819225542441 Video",
        "animation": "emoji_5337249876126215335 GIF", "voice": "emoji_6269118781331609137 Voice", "video_note": "emoji_5334544901428229844 Video Note",
        "document": "emoji_5454380420336466255 Document", "sticker": "emoji_6257858798715670989 Sticker", "audio": "emoji_6123107313654960925 Audio",
    }
    type_label   = type_icons.get(media_type, media_type.capitalize())
    entity_note  = (f"emoji_5206607081334906820 `{len(entities_list)}` formatting "
                    f"entr{'y' if len(entities_list)==1 else 'ies'} preserved\n"
                    if entities_list else "")

    await msg.reply_text(
        f"emoji_5877618313139327986 *Advertisement Captured!*\n\n"
        f"{DIVIDER}\n"
        f"emoji_5447183459602669338 Type: {type_label}\n"
        + (f"emoji_5832262406226579218 Preview: _{content[:80]}{'…' if len(content) > 80 else ''}_\n" if content else "")
        + entity_note
        + f"{DIVIDER}\n\n"
        "emoji_6006051952847230749 *Now choose where to send your advertisement:*",
        parse_mode="Markdown",
        reply_markup=_ads_target_kb(),
    )
    return ADS_TARGET


async def handle_ads_target(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """User chose a delivery target; show delay selection."""
    q = update.callback_query
    await q.answer()
    user_id = update.effective_user.id
    is_premium = await db.check_premium_active(user_id)

    target_map = {
        "ads_target_chats":  ("chats",  "emoji_6271665430650163493 Chats & Contacts"),
        "ads_target_groups": ("groups", "emoji_5778271407435682765 Groups"),
        "ads_target_both":   ("both",   "emoji_6269118781331609137 Both (Chats, Contacts & Groups)"),
    }
    target_key, target_label = target_map.get(q.data, ("both", "Both"))
    ctx.user_data["ads_target"] = target_key

    await q.message.reply_text(
        f"emoji_5877618313139327986 *Target Selected:* {target_label}\n\n"
        f"{DIVIDER}\n\n"
        "⏱ *Now choose how often your advertisement should be sent automatically:*\n\n"
        + ("" if is_premium else "_⭐ Custom Delay is available for VIP Premium users._"),
        parse_mode="Markdown",
        reply_markup=_ads_delay_kb(is_premium),
    )
    return ADS_DELAY


async def handle_ads_delay(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """User chose a delay preset; route VIP to link-preview step, free users straight to finalize."""
    q = update.callback_query
    user_id = update.effective_user.id

    if q.data == "ads_delay_custom_locked":
        # show_alert requires its own answer call — do NOT call q.answer() twice
        await q.answer("⭐ Custom Delay is for VIP Premium users only.", show_alert=True)
        return ADS_DELAY

    if q.data == "ads_delay_custom":
        is_premium = await db.check_premium_active(user_id)
        if not is_premium:
            await q.answer("⭐ Upgrade to VIP Premium for custom delays.", show_alert=True)
            return ADS_DELAY
        await q.answer()
        await q.message.reply_text(
            "⭐ *Custom Delay (VIP Premium)*\n\n"
            f"{DIVIDER}\n"
            "Type how many *minutes* between each advertisement send.\n\n"
            "Examples:\n"
            "   `2` → Every 2 minutes\n"
            "   `30` → Every 30 minutes\n"
            "   `60` → Every 1 hour\n\n"
            "_Minimum: 1 minute_",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [cancel_button("⬅️ Cancel", callback_data="cb_back")],
            ]),
        )
        return ADS_CUSTOM_DELAY

    await q.answer()
    delay_map = {"ads_delay_5": 5, "ads_delay_15": 15, "ads_delay_20": 20}
    delay_minutes = delay_map.get(q.data, 5)
    ctx.user_data["ads_delay_minutes"] = delay_minutes
    return await _route_after_delay(update, ctx, user_id)


async def handle_ads_custom_delay(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Receive the custom delay in minutes (VIP only)."""
    msg = update.message
    user_id = update.effective_user.id

    raw = msg.text.strip()
    try:
        delay_minutes = max(1, int(raw))
    except ValueError:
        await msg.reply_text(
            "emoji_5454415424319931791️ Please send a valid number of minutes (e.g. `5`, `30`, `60`).",
            parse_mode="Markdown",
        )
        return ADS_CUSTOM_DELAY

    ctx.user_data["ads_delay_minutes"] = delay_minutes
    return await _route_after_delay(update, ctx, user_id)


async def _route_after_delay(update, ctx, user_id: int):
    """VIP users see the link-preview screen; free users go straight to finalize (no preview)."""
    is_premium = await db.check_premium_active(user_id)
    if is_premium:
        return await _ask_link_preview(update, ctx)
    # Free users: always disable link preview
    ctx.user_data["ads_link_preview"] = False
    return await _finalize_ads(update, ctx, user_id)


def _link_preview_kb(enabled: bool) -> InlineKeyboardMarkup:
    on_btn  = _gbtn("Show Preview (On)",  callback_data="ads_lp_on")
    off_btn = _gbtn("emoji_6116290955743073366 No Preview (Off)",   callback_data="ads_lp_off")
    return InlineKeyboardMarkup([
        [on_btn  if not enabled else _bbtn("Show Preview (On)",  callback_data="ads_lp_on")],
        [off_btn if enabled     else _bbtn("emoji_6116290955743073366 No Preview (Off)",  callback_data="ads_lp_off")],
        [cancel_button("⬅️ Cancel", callback_data="cb_back")],
    ])


async def _ask_link_preview(update, ctx):
    """Show the link-preview toggle screen for VIP users ONLY if message contains links.
    If no links detected, skip directly to finalize."""
    import re
    
    content = ctx.user_data.get("ads_content", "").strip()
    
    # Auto-detect if message contains URLs/links
    link_pattern = r'(https?://[^\s]+|t\.me/[^\s]+|telegram\.me/[^\s]+)'
    has_link = bool(re.search(link_pattern, content))
    
    # If no link in message, skip preview screen and go straight to finalize
    if not has_link:
        ctx.user_data["ads_link_preview"] = False
        await update.effective_message.reply_text(
            "✅ No link detected in message. Proceeding with delay settings...",
            reply_markup=InlineKeyboardMarkup([[cancel_button("Back", callback_data="cb_back")]])
        )
        return await _finalize_ads(update, ctx, update.effective_user.id)
    
    # Link detected - show preview options for VIP users
    current = ctx.user_data.get("ads_link_preview", False)
    text = (
        "🔗 *Link Preview Setting (VIP)*\n\n"
        f"{DIVIDER}\n"
        "Your message contains a link! Choose how it should appear:\n\n"
        "emoji_5877618313139327986 *Show Preview (On)* — Telegram displays a preview card with title, "
        "description, and thumbnail.\n\n"
        "emoji_6116290955743073366 *No Preview (Off)* — Only the plain text and URL are shown. "
        "No card, no thumbnail.\n\n"
        f"{DIVIDER}\n"
        "_Choose wisely for better engagement!_"
    )
    eff_msg = update.effective_message
    await eff_msg.reply_text(text, parse_mode="Markdown", reply_markup=_link_preview_kb(current))
    return ADS_LINK_PREVIEW


async def handle_ads_link_preview(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """VIP user tapped a link-preview button; save choice and finalize."""
    q = update.callback_query
    await q.answer()
    user_id = update.effective_user.id
    ctx.user_data["ads_link_preview"] = (q.data == "ads_lp_on")
    return await _finalize_ads(update, ctx, user_id)


async def _finalize_ads(update, ctx, user_id: int):
    """Save ad to DB, start sender, confirm to user with detailed info."""
    media_type    = ctx.user_data.get("ads_media_type", "text")
    file_id       = ctx.user_data.get("ads_file_id")
    content       = ctx.user_data.get("ads_content", "")
    target        = ctx.user_data.get("ads_target", "both")
    delay_minutes = int(ctx.user_data.get("ads_delay_minutes", 5))
    link_preview  = bool(ctx.user_data.get("ads_link_preview", False))
    entities      = ctx.user_data.get("ads_entities")
    
    is_premium = await db.check_premium_active(user_id)
    target_label  = {"chats": "Chats & Contacts", "groups": "Groups", "both": "Both"}.get(target, "Both")
    preview_label = "✅ Show Preview" if link_preview else "❌ No Preview"
    hours_display = (f"{delay_minutes // 60}h {delay_minutes % 60}m"
                     if delay_minutes >= 60 else f"{delay_minutes} minute(s)")
    
    # Get branding username for display
    branding_username = await db.get_ads_branding_username()
    branding_bio = await db.get_ads_branding_bio()

    await db.set_ad(user_id, media_type, file_id, content, target, delay_minutes,
                    link_preview=link_preview, entities=entities)
    await userbot.start_ads_sender(user_id)

    # Ads branding is plan-aware inside userbot:
    # free + 1–7 day premium => branding; 8+ days/lifetime => no branding/footer.
    success = await userbot.apply_bio_branding_now(user_id, force=True)
    premium_row = await db.get_premium(user_id)
    premium_days = int((premium_row or {}).get("days") or 0) if premium_row else 0
    branding_allowed = (not premium_row or not premium_row.get("is_active") or premium_days <= 7)
    bio_status = (f"✅ *Bio + Name Branding:* `{branding_bio[:50]}`" if success and branding_allowed
                  else "ℹ️ *8+ day/Lifetime Premium:* profile branding + ad footer disabled"
                  if premium_row and premium_row.get("is_active") and premium_days > 7
                  else "⚠️ Branding update pending...")

    confirm = (
        f"✅ *Advertisement Active!*\n\n"
        f"{DIVIDER}\n"
        f"🎯 *Target:*        {target_label}\n"
        f"⏰ *Interval:*      Every {hours_display}\n"
        f"🔗 *Link Preview:*  {preview_label}\n"
        f"👤 *Ads Brand:*     @{branding_username}\n"
        f"{bio_status}\n"
        f"{DIVIDER}\n\n"
        f"🤖 *What Happens Next:*\n"
        f"• Your message will be sent every {hours_display}\n"
        f"• Ad footer (1–7 day premium/free): `This ad is sent by @{branding_username}`\n"
        f"• Profile name + bio branding is enforced while Ads are ON\n"
        f"• If you change your name or bio, both are restored on the next Ads cycle\n"
        f"• Works 24/7 even when you're offline\n\n"
        f"📝 To change ads: *emoji_5769547529993588669 Set Ads → Modify*\n"
        f"🛑 To stop: *emoji_5769547529993588669 Set Ads → Turn Off*"
    )

    eff_msg = update.effective_message
    if update.callback_query:
        await update.callback_query.answer()
    await eff_msg.reply_text(confirm, parse_mode="Markdown", reply_markup=await get_main_menu_kb())

    for key in ("ads_media_type", "ads_file_id", "ads_content",
                "ads_target", "ads_delay_minutes", "ads_link_preview", "ads_entities"):
        ctx.user_data.pop(key, None)
    return ConversationHandler.END


async def cancel_setads(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if update.callback_query:
        await update.callback_query.answer()
    await update.effective_message.reply_text(
        "emoji_5337312745857501717 Ad setup cancelled.",
        reply_markup=await get_main_menu_kb(),
    )
    for key in ("ads_media_type", "ads_file_id", "ads_content",
                "ads_target", "ads_delay_minutes", "ads_link_preview", "ads_entities"):
        ctx.user_data.pop(key, None)
    return ConversationHandler.END


# ── Ads Logs ──────────────────────────────────────────────────────────────────
_LOGS_PER_PAGE = 1   # 1 per page — prevents message-too-long errors


def _md(text: str) -> str:
    """Escape Markdown V1 special characters in user-supplied content.

    Unescaped underscores/asterisks inside names like 'john_doe' or
    'my_group' break Telegram's Markdown parser and cause a BadRequest
    that propagates to the global error handler.
    """
    if not text:
        return ""
    for ch in ("_", "*", "`", "["):
        text = text.replace(ch, f"\\{ch}")
    return text


def _fmt_log_entry(log: dict, failures: list, replies: list, mentions: list) -> str:
    run_at        = log.get("run_at", "")
    delay         = int(log.get("delay_minutes", 5))
    target        = log.get("target", "both")
    total_chats   = int(log.get("total_chats", 0))
    sent_chats    = int(log.get("sent_chats", 0))
    failed_chats  = int(log.get("failed_chats", 0))
    total_groups  = int(log.get("total_groups", 0))
    sent_groups   = int(log.get("sent_groups", 0))
    failed_groups = int(log.get("failed_groups", 0))

    # Format timestamp
    try:
        from datetime import datetime
        if isinstance(run_at, str) and run_at:
            dt = datetime.fromisoformat(run_at.replace("Z", "+00:00"))
        else:
            dt = run_at
        time_str = dt.strftime("%d %B %Y  •  %I:%M %p")
    except Exception:
        time_str = str(run_at) if run_at else "Unknown time"

    delay_str  = (f"Every {delay // 60}h {delay % 60}m" if delay >= 60
                  else f"Every {delay} Minute{'s' if delay != 1 else ''}")
    target_lbl = {"chats": "Chats & Contacts", "groups": "Groups", "both": "Both"}.get(target, "Both")

    not_sent_chats  = max(0, total_chats  - sent_chats  - failed_chats)
    not_sent_groups = max(0, total_groups - sent_groups - failed_groups)
    total_all  = total_chats  + total_groups
    sent_all   = sent_chats   + sent_groups
    failed_all = failed_chats + failed_groups
    rate       = round(sent_all / total_all * 100) if total_all > 0 else 0

    lines = [
        f"emoji_6271665430650163493 *{_md(time_str)}*",
        f"⏱ {delay_str}   •   emoji_6006051952847230749 {target_lbl}",
        "┄" * 20,
    ]

    if target in ("chats", "both"):
        lines += [
            "emoji_6271665430650163493 *Chats & Contacts*",
            f"   Total: `{total_chats:,}`   Sent: `{sent_chats:,}`   Failed: `{failed_chats:,}`   Not Sent: `{not_sent_chats:,}`",
        ]

    if target in ("groups", "both"):
        lines += [
            "emoji_5778271407435682765 *Groups*",
            f"   Total: `{total_groups:,}`   Sent: `{sent_groups:,}`   Failed: `{failed_groups:,}`   Not Sent: `{not_sent_groups:,}`",
        ]

    lines += [
        "emoji_5235582317988171528 *Campaign Summary*",
        f"   Destinations: `{total_all:,}`   Delivered: `{sent_all:,}`   Failed: `{failed_all:,}`   Rate: `{rate}%`",
    ]

    # Replies — escape all user-supplied names
    if replies:
        r_lines = "\n".join(
            f"   • {_md(r.get('from_user', 'Unknown'))} ({_md(r.get('chat_name', ''))})"
            for r in replies[:5]
        )
        extra = f"\n   ...and {len(replies) - 5} more" if len(replies) > 5 else ""
        lines += [f"emoji_6073288235642000201 *Replies Received:* `{len(replies)}`", r_lines + extra]
    else:
        lines.append("emoji_6073288235642000201 *Replies Received:* `0`")

    # Mentions — escape all user-supplied names
    if mentions:
        m_lines = "\n".join(
            f"   • {_md(m.get('from_user', 'Unknown'))} ({_md(m.get('chat_name', ''))})"
            for m in mentions[:5]
        )
        extra = f"\n   ...and {len(mentions) - 5} more" if len(mentions) > 5 else ""
        lines += [f"emoji_5249050854392091366 *Mentions:* `{len(mentions)}`", m_lines + extra]
    else:
        lines.append("emoji_5249050854392091366 *Mentions:* `0`")

    # Failures — reason strings come from _categorize_error (safe), name is user-supplied
    if failures:
        f_lines = "\n".join(
            f"   • {_md(f.get('name', '?'))} — {f.get('reason', 'Error')}"
            for f in failures[:5]
        )
        extra = f"\n   ...and {len(failures) - 5} more" if len(failures) > 5 else ""
        lines += [f"emoji_5337312745857501717 *Failed Deliveries:* `{len(failures)}`", f_lines + extra]

    return "\n".join(lines)


