async def cb_adslogs_pg(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Legacy paginated ads logs view (kept for backward compatibility)."""
    q = update.callback_query
    await q.answer()

    if not await ensure_account(update):
        return
    if not await ensure_not_banned(update):
        return

    user_id = update.effective_user.id

    page = 0
    if q.data and q.data.startswith("cb_adslogs_pg_"):
        try:
            page = int(q.data.split("_")[-1])
        except ValueError:
            page = 0

    total = await db.get_ad_log_count(user_id)

    if total == 0:
        await q.message.reply_text(
            "emoji_6129801569941592173 *Ads Logs*\n\n"
            f"{DIVIDER}\n"
            "emoji_6269362834258269327 No advertisement logs yet.\n\n"
            "_Logs are created automatically after each advertisement cycle completes._\n\n"
            "Set up an advertisement using *emoji_5769547529993588669 Set Ads* to get started.",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [setads_button("📢 Set Ads", callback_data="cb_setads"),
                 _bbtn("⬅️ Back",   callback_data="cb_back")],
            ]),
        )
        return

    offset      = page * _LOGS_PER_PAGE
    logs        = await db.get_ad_logs(user_id, limit=_LOGS_PER_PAGE, offset=offset)
    total_pages = max(1, (total + _LOGS_PER_PAGE - 1) // _LOGS_PER_PAGE)

    header = (
        "emoji_6129801569941592173 *Ads Logs*\n\n"
        f"{DIVIDER}\n"
        "_Complete history of your advertisement campaigns._\n"
        "_Monitor deliveries, failures, replies, and mentions per cycle._\n"
        f"{DIVIDER}\n\n"
    )

    entries = []
    for log in logs:
        lid = log["id"]
        try:
            failures = await db.get_ad_log_failures(lid)
        except Exception:
            failures = []
        try:
            replies = await db.get_ad_log_replies(lid)
        except Exception:
            replies = []
        try:
            mentions = await db.get_ad_log_mentions(lid)
        except Exception:
            mentions = []
        try:
            entries.append(_fmt_log_entry(log, failures, replies, mentions))
        except Exception as fmt_err:
            logger.warning("Ads log format error for log %s: %s", lid, fmt_err)
            entries.append(f"_(Log #{lid} could not be rendered)_")

    body   = f"\n\n{'━' * 22}\n\n".join(entries)
    footer = (
        f"\n\n{DIVIDER}\n"
        f"_Page {page + 1} of {total_pages}  •  "
        f"{total} total log{'s' if total != 1 else ''}_"
    )

    full_text = header + body + footer

    _TG_LIMIT = 4000
    if len(full_text) > _TG_LIMIT:
        full_text = full_text[:_TG_LIMIT - 60] + "\n\n_...\\(truncated — use newer pages\\)_"

    nav_row = []
    if page > 0:
        nav_row.append(_bbtn("◀️ Newer", callback_data=f"cb_adslogs_pg_{page - 1}"))
    if page < total_pages - 1:
        nav_row.append(_bbtn("Older ▶️", callback_data=f"cb_adslogs_pg_{page + 1}"))

    kb_rows = []
    if nav_row:
        kb_rows.append(nav_row)
    kb_rows.append([setads_button("📢 Set Ads", callback_data="cb_setads"),
                    _bbtn("⬅️ Back",   callback_data="cb_back")])

    await q.message.reply_text(
        full_text,
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup(kb_rows),
    )


