# ── Play & Win event ─────────────────────────────────────────────────────────
PLAY_WIN_COOLDOWN_HOURS = 24
# Wheel uses mutually-exclusive outcome probabilities.
# 90% = Better Luck Next Time; total premium win chance = 10%.
# 100-day event prizes are disabled in V14. All event rewards are capped at 50 days.
# Play & Win probability rules (V14):
# Wheel: 90% Better Luck Next Time, 10% premium.
# Dice: premium is awarded ONLY when the Telegram dice exactly matches the
# number selected by the user. A mismatch always awards zero premium.
# Premium days are intentionally small: 1-10 days is the normal range,
# 11-49 are rare, and 50 days is extremely rare. No 100-day event prize.
WHEEL_CHANCES = {
    "premium": 10.0,
    "better_luck": 90.0,
}

DICE_MATCH_REQUIRED = True


def _event_premium_days() -> int:
    """Return a weighted 1..50 event prize.

    Most wins are 1-10 days. 11-49 days are rare and 50 days is extremely
    rare. This function is only called after a legitimate win condition.
    """
    roll = secrets.randbelow(10000)
    if roll < 8500:  # 85% of premium wins -> 1..10
        return secrets.randbelow(10) + 1
    if roll < 9950:  # 14.5% -> 11..49
        return secrets.randbelow(39) + 11
    return 50          # 0.5% -> 50 days



# ── Task system ───────────────────────────────────────────────────────────────
_TASK_LINK_RE = re.compile(r"(?:https?://)?(?:www\.)?(?:t\.me|telegram\.me)/([A-Za-z0-9_]{3,})", re.I)


def _task_telegram_targets(content: str) -> list[str]:
    targets = []
    for match in _TASK_LINK_RE.findall(content or ""):
        username = str(match).lstrip("@").strip()
        if username and username.lower() not in {x.lower() for x in targets}:
            targets.append(username)
    for raw in re.findall(r"(?<!\w)@[A-Za-z0-9_]{4,}", content or ""):
        username = raw[1:]
        if username.lower() not in {x.lower() for x in targets}:
            targets.append(username)
def _task_text(task: dict) -> str:
    import html as _html
    reward = str(task.get("reward_value", ""))
    if task.get("reward_type") == "premium":
        price = f"{_html.escape(reward)} day Premium"
    else:
        price = _html.escape(reward)
    caption = _html.escape(str(task.get("caption", "")).strip())
    content = _html.escape(str(task.get("content", "")).strip())
    return (
        "╔════════════════════╗\n"
        "        <b>TASK</b>\n"
        "╚════════════════════╝\n\n"
        f"<b>{caption}</b>\n\n"
        f"{content}\n\n"
        f"💰 <b>PRICE:</b> {price}"
    )


def _task_kb():
    return InlineKeyboardMarkup([
        [user_button("✅ Done", callback_data="task_done", style="success")],
        [user_button("🔙 Back", callback_data="cb_play_win", style="primary")],
    ])


async def cb_task(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    uid = int(update.effective_user.id)
    try:
        task = await db.get_active_task()
        if not task:
            await q.answer("No task is available right now.", show_alert=True)
            return
        if await db.get_task_completion(int(task["id"]), uid):
            await q.answer("You have already completed this task.", show_alert=True)
            return
        await q.message.edit_text(
            _task_text(task), parse_mode="HTML", reply_markup=_task_kb(),
            disable_web_page_preview=False
        )
        await q.answer()
    except Exception as exc:
        logger.exception("Task open failed for user %s: %s", uid, exc)
        try:
            await q.answer("Task could not be opened. Please try again.", show_alert=True)
        except Exception:
            pass


async def cb_task_done(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    uid = int(update.effective_user.id)
    try:
        task = await db.get_active_task()
        if not task:
            await q.answer("Task is no longer available.", show_alert=True)
            return
        if await db.get_task_completion(int(task["id"]), uid):
            await q.answer("You have already completed this task.", show_alert=True)
            return

        targets = _task_telegram_targets(task.get("content", ""))
        verification = "acknowledged"
        if targets:
            verification = "verified"
            failures = []
            for target in targets:
                try:
                    member = await ctx.bot.get_chat_member(f"@{target}", uid)
                    status = str(getattr(member, "status", ""))
                    if status in {"left", "kicked", "restricted"}:
                        failures.append(f"@{target}")
                except Exception as exc:
                    logger.warning("Task membership verification failed for %s/%s: %s", uid, target, exc)
                    failures.append(f"@{target}")
            if failures:
                await q.answer("Please complete the Telegram task first: " + ", ".join(failures), show_alert=True)
                return

        reward_granted = 0
        reward_type = str(task.get("reward_type") or "custom")
        reward_value = str(task.get("reward_value") or "").strip()
        if reward_type == "premium":
            days = int(reward_value)
            if days <= 0 or days > 3650:
                await q.answer("The task reward is invalid. Please contact admin.", show_alert=True)
                return
            await db.add_premium_days(uid, days, plan_key=f"task_{int(task['id'])}")
            reward_granted = 1
            reward_text = f"🎉 <b>Task completed!</b>\n\n💎 You received <b>{days} day Premium</b>."
        else:
            reward_text = f"🎉 <b>Task completed!</b>\n\n🎁 <b>Reward:</b> {_html.escape(reward_value)}"
            reward_granted = 1

        if not await db.add_task_completion(int(task["id"]), uid, reward_granted, verification):
            await q.answer("You have already completed this task.", show_alert=True)
            return
        await q.message.edit_text(reward_text, parse_mode="HTML", reply_markup=InlineKeyboardMarkup([
            [user_button("🎮 Play & Win", callback_data="cb_play_win")],
            [user_button("🔙 Main Menu", callback_data="cb_back", style="primary")],
        ]))
        await q.answer("Reward granted!")
    except Exception as exc:
        logger.exception("Task completion failed for user %s: %s", uid, exc)
        try:
            await q.answer("Something went wrong while verifying the task. Please try again.", show_alert=True)
        except Exception:
            pass

