def _chance_hit(chance: float) -> bool:
    """Return a cryptographically random hit for an individual percentage chance."""
    try:
        value = max(0.0, min(100.0, float(chance)))
    except Exception:
        value = 0.0
    return secrets.randbelow(10000) < int(value * 100)


def _pick_chance_prize(chances: dict | None = None, fallback: str = "better_luck") -> tuple[str, int]:
    """Pick one mutually-exclusive wheel outcome.

    The wheel has a hard 90% miss / 10% premium-win split. Premium days are
    generated only after the premium outcome is selected.
    """
    premium_chance = 10.0
    if chances:
        premium_chance = float(chances.get("premium", 10.0))
    premium_chance = max(0.0, min(100.0, premium_chance))
    roll = secrets.randbelow(10000) / 100.0
    if roll < premium_chance:
        days = _event_premium_days()
        return f"{days}d", days
    return fallback, 0


async def _play_win_available(user_id: int, game: str) -> tuple[bool, str]:
    """Check the 24-hour cooldown using the persistent DB record."""
    last = await db.get_last_play_win_spin(user_id, game)
    if not last or not last.get("created_at"):
        return True, ""
    try:
        stamp = datetime.strptime(str(last["created_at"])[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
        remaining = (stamp.timestamp() + PLAY_WIN_COOLDOWN_HOURS * 3600) - time.time()
        if remaining > 0:
            hours = int(remaining // 3600)
            minutes = int((remaining % 3600) // 60)
            return False, f"⏳ Your next {game.title()} chance is available in **{hours}h {minutes}m**."
    except Exception:
        pass
    return True, ""


async def _grant_event_prize(user_id: int, game: str, key: str, days: int) -> str:
    """Persist an event result. Admin accounts follow the same win rules.

    There is deliberately no admin bypass here: a dice mismatch can never
    receive premium, and neither game can grant 100 days.
    """
    days = min(50, max(0, int(days or 0)))
    if days > 0:
        await db.add_premium_days(user_id, days, plan_key=f"event_{game}_{days}d")
        await db.record_play_win_spin(user_id, game, key, days)
        return f"💎 **{days} DAY PREMIUM**"
    await db.record_play_win_spin(user_id, game, "better_luck", 0)
    return "🥀 **BETTER LUCK NEXT TIME**"


async def _edit_playwin_message(message, text: str, *, reply_markup=None, parse_mode="Markdown"):
    """Edit a Play & Win screen regardless of whether it is a text or photo message."""
    try:
        if getattr(message, "photo", None):
            return await message.edit_caption(caption=text, parse_mode=parse_mode, reply_markup=reply_markup)
        return await message.edit_text(text=text, parse_mode=parse_mode, reply_markup=reply_markup)
    except (BadRequest, TelegramError):
        # A photo message cannot be edit_text and an already-edited message may
        # reject an identical update.  Fall back to a fresh text message rather
        # than letting the global error handler show "Something went wrong".
        try:
            return await message.reply_text(text, parse_mode=parse_mode, reply_markup=reply_markup)
        except TelegramError:
            return None


async def _play_win_remaining_attempts(user_id: int, game: str, limit: int):
    count, oldest = await db.get_play_win_attempts_last_24h(user_id, game)
    remaining = max(0, int(limit) - count)
    wait_text = ""
    if remaining == 0 and oldest:
        try:
            stamp = datetime.strptime(str(oldest)[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
            seconds = max(0, int(stamp.timestamp() + 86400 - time.time()))
            hours, rem = divmod(seconds, 3600)
            minutes = rem // 60
            wait_text = f" Try again in about {hours}h {minutes}m."
        except Exception:
            pass
    return remaining, wait_text


