async def cb_pw_spin(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    uid = update.effective_user.id
    if not await check_banned_for_callback(update, ctx): return
    ok, msg = await _play_win_available(uid, "wheel")
    if not ok:
        await q.answer("Spin is on cooldown.", show_alert=True)
        await _edit_playwin_message(q.message, msg, reply_markup=_wheel_kb())
        return
    try:
        await q.answer()
    except Exception:
        pass

    # A real visual sequence: large emoji frames swap quickly, then the result
    # is shown. The attempt is recorded even for Better Luck, so re-adding an
    # account or changing bot state cannot reset the user's 24h wheel lock.
    frames = [
        "🎡 *SPINNING...*\n\n🎁     🎯     💎",
        "🎡 *SPINNING...*\n\n💎     🥀     🎉",
        "🎡 *SPINNING...*\n\n🎉     🎁     ⭐",
        "🎡 *SPINNING...*\n\n🥀     💎     🎁",
    ]
    for frame in frames:
        await _edit_playwin_message(q.message, frame, reply_markup=None)
        await asyncio.sleep(0.30)

    key, days = _pick_chance_prize(WHEEL_CHANCES)
    prize = await _grant_event_prize(uid, "wheel", key, days)
    if days:
        text = f"🎉 *CONGRATULATIONS!*\n\n🏆 You won: {prize}\n\n💎 Premium has been added to your existing premium balance."
    else:
        text = "🥀 *BETTER LUCK NEXT TIME!*\n\nYour wheel attempt is used. You can spin again after 24 hours."
    await _edit_playwin_message(q.message, text, reply_markup=InlineKeyboardMarkup([
        [user_button("🎮 Play & Win", callback_data="cb_play_win")],
        [user_button("🔙 Main Menu", callback_data="cb_back")],
    ]))


async def cb_pw_roll(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    uid = update.effective_user.id
    if not await check_banned_for_callback(update, ctx): return
    try:
        chosen = int(str(q.data).split("_")[-1])
    except Exception:
        await q.answer("Choose a number from 1 to 6.", show_alert=True)
        return
    if chosen < 1 or chosen > 6:
        await q.answer("Invalid number.", show_alert=True)
        return

    remaining, wait_text = await _play_win_remaining_attempts(uid, "dice", 3)
    if remaining <= 0 and uid != int(ADMIN_TG_ID):
        await q.answer("All 3 dice attempts are used.", show_alert=True)
        return

    try:
        await q.answer(f"You chose {chosen} 🎯")
    except Exception:
        pass

    await _edit_playwin_message(
        q.message,
        f"🎲 *ROLLING...*\n\n🎯 Your number: *{chosen}*\n\n⏳ The dice is rolling...",
        reply_markup=None,
    )
    await asyncio.sleep(0.65)

    # Telegram's real Dice message provides a server-generated 1..6 value and
    # displays the native dice animation/sticker to the user.
    try:
        dice_msg = await ctx.bot.send_dice(chat_id=uid, emoji="🎲")
        rolled = int(getattr(getattr(dice_msg, "dice", None), "value", 0) or 0)
    except Exception as exc:
        logger.exception("Real Telegram dice send failed for %s: %s", uid, exc)
        await _edit_playwin_message(q.message, "⚠️ The dice could not be rolled. Please try again.", reply_markup=_dice_kb())
        return

    # Record every actual roll, including misses, so the 3-per-24h rule is
    # durable and tied to the Telegram user ID.
    # A premium result is possible ONLY on an exact dice match. Admins do not
    # bypass this rule. Mismatch = zero premium, always.
    if rolled == chosen:
        days = _event_premium_days()
        key = f"{days}d"
        matched = True
    else:
        key, days = "better_luck", 0
        matched = False

    prize = await _grant_event_prize(uid, "dice", key, days)
    if matched and days:
        result = (
            f"🎉 *DICE MATCHED!*\n\n"
            f"🎯 You chose: *{chosen}*\n"
            f"🎲 Dice result: *{rolled}*\n\n"
            f"🏆 *YOU WON {days} DAYS PREMIUM!* 💎\n\n"
            "Premium has been added to your existing premium balance."
        )
    else:
        result = (
            f"🥀 *BETTER LUCK NEXT TIME!*\n\n"
            f"🎯 You chose: *{chosen}*\n"
            f"🎲 Dice result: *{rolled}*\n\n"
            "The dice did not match your number, so no premium was awarded."
        )
    await _edit_playwin_message(q.message, result, reply_markup=_dice_result_keyboard())


async def cb_pw_dice_pick_alias(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    # Compatibility alias kept separate so old clients/callbacks remain safe.
    return await cb_pw_roll(update, ctx)

def _format_giveaway_info(gw: dict, participants: int) -> str:
    ends = str(gw.get("ends_at", ""))[:19]
    return (
        "🎉 *ACTIVE GIVEAWAY* 🎉\n\n"
        f"🎁 *GIVEAWAY NAME*\n{gw.get('name','')}\n\n"
        f"🏆 *PRIZE*\n{gw.get('prize','')}\n\n"
        f"👥 *TOTAL WINNERS:* {int(gw.get('winners_count') or 0)}\n"
        f"👤 *PARTICIPANTS:* {participants}\n"
        f"⏰ *GIVEAWAY TILL:* {ends} UTC\n\n"
        "Tap below to enter. You can participate only once."
    )

async def cb_pw_giveaway(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not await check_banned_for_callback(update, ctx):
        return
    gw = await db.get_active_giveaway()
    if not gw:
        await q.answer("No active giveaway right now.", show_alert=True)
        await q.message.edit_text("🎉 *Giveaway*\n\nThere is currently no active giveaway.", parse_mode="Markdown", reply_markup=await _event_menu_kb())
        return
    await q.answer()
    participants = await db.get_giveaway_entry_count(int(gw["id"]))
    await q.message.edit_text(
        _format_giveaway_info(gw, participants), parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [user_button("🎉 PARTICIPATE", callback_data=f"gw_join_{gw['id']}")],
            [user_button("🔙 Back", callback_data="cb_play_win")],
        ])
    )

async def cb_giveaway_participate(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    user = update.effective_user
    if not await check_banned_for_callback(update, ctx):
        return
    try:
        giveaway_id = int(str(q.data).split("_", 2)[2])
    except Exception:
        await q.answer("Invalid giveaway.", show_alert=True); return
    gw = await db.get_active_giveaway()
    if not gw or int(gw["id"]) != giveaway_id:
        await q.answer("This giveaway has ended.", show_alert=True); return
    try:
        ends = datetime.strptime(str(gw["ends_at"])[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
        if ends.timestamp() <= time.time():
            await _end_giveaway(int(gw["id"]), ctx.application)
            await q.answer("This giveaway has ended.", show_alert=True); return
    except Exception:
        pass
    added = await db.add_giveaway_entry(int(gw["id"]), user.id, user.full_name or "User", user.username)
    if not added:
        await q.answer("You are already participating.", show_alert=True)
        return
    await q.answer("Entry added successfully!", show_alert=True)
    count = await db.get_giveaway_entry_count(int(gw["id"]))
    await q.message.edit_text(
        "🎉 *CONGRATULATIONS!*\n\n"
        "✅ *YOUR ENTRY IS ADDED*\n\n"
        f"👤 Participants: *{count}*\n"
        "🏆 Winners will be selected randomly when the giveaway ends.",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[user_button("🎉 Giveaway Details", callback_data="pw_giveaway")], [user_button("🎮 Play & Win", callback_data="cb_play_win")]])
    )

async def _broadcast_user_bot(text: str, reply_markup=None) -> tuple[int,int]:
    sent = failed = 0
    bot = Bot(BOT_TOKEN)
    try:
        users = await db.get_all_users()
        for row in users:
            uid = int(row["user_id"])
            try:
                await bot.send_message(chat_id=uid, text=text, parse_mode="Markdown", reply_markup=reply_markup)
                sent += 1
            except Exception:
                failed += 1
            await asyncio.sleep(0.035)
    finally:
        await bot.shutdown()
    return sent, failed

async def _end_giveaway(giveaway_id: int, application):
    gw = await db.get_active_giveaway()
    if not gw or int(gw["id"]) != giveaway_id or gw.get("status") != "active":
        return None
    entries = await db.get_giveaway_entries(giveaway_id)
    rng = secrets.SystemRandom()
    winners = rng.sample(entries, min(int(gw["winners_count"]), len(entries))) if entries else []
    await db.finish_giveaway(giveaway_id, winners)
    lines = ["🎉 *GIVEAWAY ENDED* ✅", "", f"🎁 *PRIZE:* {gw['prize']}", f"👥 *PARTICIPANTS:* {len(entries)}", f"🏆 *WINNERS:* {len(winners)}", ""]
    if winners:
        for i, w in enumerate(winners, 1):
            uname = f"@{w['username']}" if w.get('username') else "No username"
            lines.append(f"{i} - {uname} ✅")
    else:
        lines.append("No participants entered this giveaway.")
    admin_lines = list(lines)
    if winners:
        admin_lines += ["", "📋 *WINNER DETAILS*"]
        for i, w in enumerate(winners, 1):
            admin_lines += [
                f"\n🥇 *WINNER #{i}*",
                f"👤 Name: {w.get('name') or 'User'}",
                f"🔗 Username: @{w.get('username')}" if w.get('username') else "🔗 Username: None",
                f"🆔 User ID: `{w.get('user_id')}`",
            ]
    admin_text = "\n".join(admin_lines) + f"\n\n🆔 Giveaway ID: `{giveaway_id}`"
    # Also notify all users from the User Bot that the draw has ended. The
    # admin can still perform the final prize-fulfillment announcement later.
    try:
        await _broadcast_user_bot(
            "\n".join(lines) + "\n\n🎁 Prize fulfillment will be handled by the admin.",
            reply_markup=None,
        )
    except Exception as exc:
        logger.warning("giveaway user-end announcement failed: %s", exc)

    try:
        await application.bot.send_message(
            chat_id=ADMIN_TG_ID, text=admin_text, parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("📢 ANNOUNCE WINNERS", callback_data=f"a_gw_announce_{giveaway_id}")]]) if winners else None,
        )
    except Exception as exc:
        logger.warning("giveaway admin notification failed: %s", exc)
    return winners

async def _giveaway_expiry_checker(application):
    while True:
        try:
            gw = await db.get_active_giveaway()
            if gw:
                try:
                    ends = datetime.strptime(str(gw["ends_at"])[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
                    if ends.timestamp() <= time.time():
                        await _end_giveaway(int(gw["id"]), application)
                except Exception as exc:
                    logger.warning("giveaway expiry parse/end failed: %s", exc)
        except Exception as exc:
            logger.warning("giveaway checker failed: %s", exc)
        await asyncio.sleep(15)

async def cb_ownbot(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Open the Create Your Own Bot submenu.

    The main menu exposes only the parent button.  From here the user can
    either contact the configured support/backselector username or open the
    configured bot-maker username with ``/start create`` prefilled.
    """
    q = update.callback_query
    await q.answer()
    if not await check_banned_for_callback(update, ctx):
        return

    support = (await db.get_setting("support_username", ADMIN_USERNAME) or ADMIN_USERNAME).strip().lstrip("@")
    maker = (await db.get_setting("cyob_bot_username", "") or os.getenv("CYOB_BOT_USERNAME", "AutoDmsBotMaker_BOT")).strip().lstrip("@")
    if not maker:
        maker = "AutoDmsBotMaker_BOT"

    admin_text = quote(
        "Hi Admin, I want my own customized Auto DM bot. Let's discuss pricing and other details."
    )
    # Talk to Admin is permanently routed to @okdruv; Support remains separately configurable.
    admin_url = f"https://t.me/okdruv?text={admin_text}"
    maker_url = f"https://t.me/{maker}?start=create"

    text = (
        "🤖 *Create Your Own Bot*\n\n"
        "Choose how you want to continue:"
    )
    keyboard = InlineKeyboardMarkup([
        [auto_create_bot_button("🤖 Automatic Bot", url=maker_url)],
        [talk_to_admin_button("💬 Talk to Admin", url=admin_url)],
        [cancel_button("🔙 Back", callback_data="cb_back")],
    ])

    try:
        await q.message.edit_caption(caption=text, parse_mode="Markdown", reply_markup=keyboard)
    except Exception:
        try:
            await q.message.edit_text(text, parse_mode="Markdown", reply_markup=keyboard)
        except Exception:
            await q.message.reply_text(text, parse_mode="Markdown", reply_markup=keyboard)


async def cancel_channelpromo(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    await update.effective_message.reply_text(
        "emoji_5337312745857501717 Channel Promo cancelled. Returning to menu.",
        reply_markup=await get_main_menu_kb(),
    )
    ctx.user_data.clear()
    return ConversationHandler.END


# ── Global error handler ──────────────────────────────────────────────────────
async def _error_handler(update: object, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Log the real exception and always acknowledge failed callback queries."""
    logger.error("Unhandled exception in update %s: %s", update, ctx.error, exc_info=ctx.error)
    if isinstance(update, Update):
        q = update.callback_query
        if q is not None:
            try:
                await q.answer("Something went wrong. Please try again.", show_alert=True)
            except Exception:
                pass
        if update.effective_message:
            try:
                await update.effective_message.reply_text(
                    "emoji_5454415424319931791️ Something went wrong while processing that action. Please try again or use /start."
                )
            except Exception:
                pass


async def _cb_fallback(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Acknowledge stale/unknown callback data instead of leaving Telegram spinning."""
    q = update.callback_query
    if q is None:
        return
    
    # Check if user is banned
    user_id = update.effective_user.id
    user = await db.get_user(user_id)
    if user and user.get("is_banned"):
        try:
            await q.answer()
            await q.message.reply_text(
                "ACCESS DENIED : YOU ARE BAN ( FUCKED BY ADMINS )",
                parse_mode="Markdown",
            )
        except Exception:
            pass
        return
    
    try:
        await q.answer("This button is no longer active. Please use the current menu.", show_alert=True)
    except Exception:
        pass


# ── Owner Premium detection ───────────────────────────────────────────────────
async def _capture_owner_premium(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    user = getattr(update, "effective_user", None)
    if not user or getattr(user, "id", 0) != ADMIN_TG_ID:
        return
    premium = getattr(user, "is_premium", None)
    if premium is None:
        return
    try:
        from premium_emoji_runtime import set_owner_premium_status
        set_owner_premium_status(bool(premium))
        # Keep the user-button mode aligned with the real owner status.
        set_user_custom_emoji_mode(bool(premium))
    except Exception:
        pass


# ── App setup ─────────────────────────────────────────────────────────────────
def build_app():
    app = (
        Application.builder()
        .token(BOT_TOKEN)
        # ConversationHandler keeps per-user state (OTP, payments, campaign
        # setup, etc.).  Processing updates concurrently can race that state
        # and makes otherwise valid buttons fall through to the global error
        # handler.  Telegram updates are cheap to serialize for this bot and
        # correctness is more important than parallel callback handling.
        .concurrent_updates(False)
        .connect_timeout(60)
        .read_timeout(60)
        .write_timeout(60)
        .pool_timeout(60)
        .build()
    )
    app.add_error_handler(_error_handler)
    app.add_handler(TypeHandler(Update, _capture_owner_premium), group=-100)


    add_acc_conv = ConversationHandler(
        entry_points=[CallbackQueryHandler(cb_addaccount, pattern="^cb_addaccount$")],
        states={
            ADD_PHONE: [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_add_phone)],
            ADD_CODE:  [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_add_code)],
            ADD_2FA:   [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_add_2fa)],
        },
        fallbacks=[CommandHandler("cancel", cancel_addaccount)],
        allow_reentry=True, per_message=False,
    )
    setmsg_conv = ConversationHandler(
        entry_points=[CallbackQueryHandler(cb_setmsg, pattern="^cb_setmsg$")],
        states={
            SET_MSG_COLLECT: [
                CallbackQueryHandler(handle_msg_done, pattern="^msg_done$"),
                CallbackQueryHandler(cb_back, pattern="^cb_back$"),
                MessageHandler(filters.ALL & ~filters.COMMAND, handle_set_msg),
            ],
        },
        fallbacks=[CommandHandler("cancel", cancel_setmsg)],
        allow_reentry=True, per_message=False,
    )
    payment_conv = ConversationHandler(
        entry_points=[CallbackQueryHandler(cb_ipaid, pattern="^ipaid_(?!auto_)")],
        states={
            PAY_UTR:        [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_utr)],
            PAY_SCREENSHOT: [MessageHandler(filters.PHOTO | filters.Document.IMAGE, handle_pay_screenshot)],
        },
        fallbacks=[CommandHandler("cancel", cancel_addaccount)],
        allow_reentry=True, per_message=False,
    )
    payment_auto_conv = ConversationHandler(
        entry_points=[CallbackQueryHandler(cb_ipaid_auto, pattern="^ipaid_auto_")],
        states={
            PAY_UTR_AUTO: [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_utr_auto)],
        },
        fallbacks=[CommandHandler("cancel", cancel_autopay)],
        allow_reentry=True, per_message=False,
    )
    giftcode_conv = ConversationHandler(
        entry_points=[CallbackQueryHandler(cb_giftcode, pattern="^cb_giftcode$")],
        states={
            GIFT_CODE_INPUT: [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_gift_code_input)],
        },
        fallbacks=[
            CommandHandler("cancel", cancel_giftcode),
            CallbackQueryHandler(cancel_giftcode, pattern="^cb_back$"),
        ],
        allow_reentry=True, per_message=False,
    )

    accept_pending_conv = ConversationHandler(
        entry_points=[CallbackQueryHandler(cb_acceptpending, pattern="^cb_acceptpending$")],
        states={
            AP_CHANNEL_INPUT: [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_ap_channel)],
            AP_COUNT_INPUT:   [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_ap_count)],
        },
        fallbacks=[
            CommandHandler("cancel", cancel_acceptpending),
            CallbackQueryHandler(cancel_acceptpending, pattern="^cb_back$"),
        ],
        allow_reentry=True, per_message=False,
    )

    joinrequestdm_conv = ConversationHandler(
        entry_points=[CallbackQueryHandler(cb_joinrequestdm, pattern="^cb_joinrequestdm$")],
        states={
            JD_CHANNEL_INPUT: [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_jd_channel)],
            JD_COUNT_INPUT:   [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_jd_count_input)],
            JD_MSG_INPUT:     [MessageHandler(filters.ALL & ~filters.COMMAND, handle_jd_message)],
        },
        fallbacks=[
            CommandHandler("cancel", cancel_joinrequestdm),
            CallbackQueryHandler(cancel_joinrequestdm, pattern="^cb_back$"),
        ],
        allow_reentry=True, per_message=False,
    )

    channelpromo_conv = ConversationHandler(
        entry_points=[CallbackQueryHandler(cb_channelpromo, pattern="^cb_channelpromo$")],
        states={
            CP_CHANNEL_INPUT:   [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_cp_channel)],
            CP_MEMBER_COUNT:    [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_cp_member_count)],
            CP_UTR_INPUT:       [MessageHandler(filters.TEXT & ~filters.COMMAND, handle_cp_utr)],
            CP_SCREENSHOT_INPUT:[MessageHandler(filters.PHOTO | filters.Document.IMAGE, handle_cp_screenshot)],
        },
        fallbacks=[
            CommandHandler("cancel", cancel_channelpromo),
            CallbackQueryHandler(cancel_channelpromo, pattern="^cb_back$"),
        ],
        allow_reentry=True, per_message=False,
    )

    autoreply_conv = ConversationHandler(
        entry_points=[CallbackQueryHandler(cb_setautoreply, pattern="^cb_setautoreply$")],
        states={
            AUTO_REPLY_MODE_SELECT: [
                CallbackQueryHandler(cb_ai_autoreply, pattern="^cb_ai_autoreply$"),
                CallbackQueryHandler(cb_manual_autoreply, pattern="^cb_manual_autoreply$"),
            ],
            AI_AUTO_REPLY_TOGGLE: [
                CallbackQueryHandler(cb_ai_on, pattern="^cb_ai_on$"),
                CallbackQueryHandler(cb_ai_off, pattern="^cb_ai_off$"),
            ],
            SET_AUTO_REPLY_COLLECT: [MessageHandler(filters.ALL & ~filters.COMMAND, handle_autoreply_collect)],
        },
        fallbacks=[
            CommandHandler("cancel", cancel_autoreply),
            CallbackQueryHandler(cb_delete_autoreply, pattern="^cb_delete_autoreply$"),
            CallbackQueryHandler(cancel_autoreply, pattern="^cb_back$"),
            CallbackQueryHandler(cb_setautoreply, pattern="^cb_setautoreply$"),
        ],
        allow_reentry=True, per_message=False,
    )

    setads_conv = ConversationHandler(
        entry_points=[
            CallbackQueryHandler(cb_setads,   pattern="^cb_setads$"),
            CallbackQueryHandler(cb_ads_new,  pattern="^cb_ads_new$"),
        ],
        states={
            ADS_MANAGE: [
                CallbackQueryHandler(cb_ads_turnoff, pattern="^cb_ads_turnoff$"),
                CallbackQueryHandler(cb_ads_new,     pattern="^cb_ads_new$"),
                CallbackQueryHandler(cancel_setads,  pattern="^cb_back$"),
            ],
            ADS_COLLECT: [
                MessageHandler(filters.ALL & ~filters.COMMAND, handle_ads_collect),
                CallbackQueryHandler(cancel_setads, pattern="^cb_back$"),
            ],
            ADS_TARGET: [
                CallbackQueryHandler(handle_ads_target, pattern="^ads_target_"),
                CallbackQueryHandler(cancel_setads, pattern="^cb_back$"),
            ],
            ADS_DELAY: [
                CallbackQueryHandler(handle_ads_delay, pattern="^ads_delay_"),
                CallbackQueryHandler(cancel_setads, pattern="^cb_back$"),
            ],
            ADS_CUSTOM_DELAY: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, handle_ads_custom_delay),
                CallbackQueryHandler(cancel_setads, pattern="^cb_back$"),
            ],
            ADS_LINK_PREVIEW: [
                CallbackQueryHandler(handle_ads_link_preview, pattern="^ads_lp_(on|off)$"),
                CallbackQueryHandler(cancel_setads, pattern="^cb_back$"),
            ],
        },
        fallbacks=[
            CommandHandler("cancel", cancel_setads),
            CallbackQueryHandler(cancel_setads,  pattern="^cb_back$"),
            CallbackQueryHandler(cb_ads_turnoff, pattern="^cb_ads_turnoff$"),
        ],
        allow_reentry=True, per_message=False,
    )

    # ── Register all convs in module-level registry so _clear_user_convs works ──
    _all_convs.clear()
    _all_convs.extend([
        add_acc_conv, setmsg_conv, payment_conv, payment_auto_conv,
        giftcode_conv, accept_pending_conv, joinrequestdm_conv, channelpromo_conv,
        autoreply_conv, setads_conv,
    ])
    # camp_channel_conv added below after creation
    # ──────────────────────────────────────────────────────────────────────────

    # Start premium expiry checker as a background task
    async def _start_expiry_checker(application):
        asyncio.create_task(_premium_expiry_checker(application))
        asyncio.create_task(_giveaway_expiry_checker(application))
        try:
            from admin_bot import _v19_scheduler_loop
            asyncio.create_task(_v19_scheduler_loop(application), name="v19_broadcast_scheduler")
        except Exception as exc:
            logger.warning("Could not start persistent broadcast scheduler: %s", exc)

    app.post_init = _start_expiry_checker
    app.add_handler(TypeHandler(Update, _sync_user_emoji_update, block=False), group=-1)
    # IMPROVED: Start handler with NO filters - accepts ALL users
    app.add_handler(CommandHandler("start", cmd_start, filters=None))
    app.add_handler(add_acc_conv)
    app.add_handler(setmsg_conv)
    app.add_handler(payment_conv)
    app.add_handler(payment_auto_conv)
    app.add_handler(giftcode_conv)
    app.add_handler(accept_pending_conv)
    app.add_handler(CallbackQueryHandler(cb_stop_accept, pattern="^ap_stop$"))
    app.add_handler(joinrequestdm_conv)
    app.add_handler(channelpromo_conv)
