    app.add_handler(CallbackQueryHandler(cb_ownbot, pattern="^cb_ownbot$"))
    app.add_handler(CallbackQueryHandler(cb_play_win, pattern="^cb_play_win$"))
    app.add_handler(CallbackQueryHandler(cb_human_verification, pattern="^hv_"))
    app.add_handler(CallbackQueryHandler(cb_pw_giveaway, pattern="^pw_giveaway$"))
    app.add_handler(CallbackQueryHandler(cb_giveaway_participate, pattern="^gw_join_"))
    app.add_handler(CallbackQueryHandler(cb_pw_wheel, pattern="^pw_wheel$"))
    app.add_handler(CallbackQueryHandler(cb_task, pattern="^pw_task$"))
    app.add_handler(CallbackQueryHandler(cb_task_done, pattern="^task_done$"))
    app.add_handler(CallbackQueryHandler(cb_pw_dice, pattern="^pw_dice$"))
    app.add_handler(CallbackQueryHandler(cb_pw_spin, pattern="^pw_spin$"))
    app.add_handler(CallbackQueryHandler(cb_pw_roll, pattern="^pw_pick_[1-6]$"))
    app.add_handler(CallbackQueryHandler(cb_pw_dice_pick_alias, pattern="^pw_roll$"))
    app.add_handler(CallbackQueryHandler(cb_delete_autoreply, pattern="^cb_delete_autoreply$"))
    # ───────────────────────────────────────────────────────────────────────
    # SINGLE-BOT ADMIN MIGRATION
    # The complete Admin Bot UI/handlers are mounted on this USER BOT.
    # /admin is the only entry point; every admin callback still performs its
    # own primary/extra-admin authorization check.  The legacy Admin Bot is
    # no longer polled by main.py.
    # ───────────────────────────────────────────────────────────────────────
    from admin_bot import build_app as _build_legacy_admin_app
    _legacy_admin_app = _build_legacy_admin_app()

    # IMPORTANT: do not mount the same PTB handler objects directly into two
    # Application instances.  In PTB this can make callback/conversation state
    # unreliable; the symptom is exactly the "button is no longer active"
    # alert even though the dashboard itself opens correctly.  Keep the admin
    # Application as the authoritative handler registry and dispatch matching
    # admin handlers from this single user-bot Application.
    _admin_registry_handlers = []
    for _group in sorted(_legacy_admin_app.handlers):
        for _handler in _legacy_admin_app.handlers[_group]:
            if isinstance(_handler, (_TelegramCallbackQueryHandler, ConversationHandler)):
                _admin_registry_handlers.append(_handler)

    async def _dispatch_admin_update(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> bool:
        user = getattr(update, "effective_user", None)
        if not user:
            return False

        # EXPLICIT MODE ISOLATION:
        # The primary admin can use the normal User Panel too.  Once /start
        # has been used, ALL subsequent callbacks/messages belong to USER MODE
        # until /admin is used again.  Never let an Admin ConversationHandler
        # steal a User Panel callback merely because the admin account is the
        # authorized admin.
        try:
            if int(user.id) == int(ADMIN_TG_ID):
                if (ctx.user_data or {}).get("__single_bot_mode") != "admin":
                    return False
        except Exception:
            return False

        # Only the configured primary admin and registered extra admins are
        # allowed to enter this dispatcher.
        if user.id != ADMIN_TG_ID:
            try:
                if not await db.is_extra_admin(user.id):
                    return False
            except Exception:
                return False

        for _handler in _admin_registry_handlers:
            try:
                _check = _handler.check_update(update)
            except Exception:
                continue
            if not _check:
                continue
            try:
                await _handler.handle_update(update, app, _check, ctx)
            except Exception:
                logger.exception("Admin handler dispatch failed for %s", getattr(update, "update_id", "?"))
                raise
            return True
        return False

    async def _admin_update_bridge(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        handled = await _dispatch_admin_update(update, ctx)
        if handled:
            # Prevent the same admin callback/message from falling through into
            # the normal user-bot handlers or the stale-callback guard.
            raise ApplicationHandlerStop

    # BROADCAST TEXT RECOVERY BRIDGE
    #
    # The admin ConversationHandler is maintained in a legacy registry and is
    # dispatched manually above.  On some PTB versions, its internal
    # ConversationHandler state is not reconstructed when a callback entry
    # point is dispatched through another Application.  The result is that
    # the admin can tap Broadcast All, type the message, and the normal bot
    # error/fallback path receives that text instead of the broadcast handler.
    #
    # Handle the active broadcast workflow explicitly in the single-bot
    # application.  This is intentionally limited to ADMIN MODE + the
    # broadcast state keys, so ordinary user messages are never affected.
    from admin_bot import (
        handle_v18_broadcast_message as _admin_handle_broadcast_message,
        handle_v18_select_user as _admin_handle_broadcast_select_user,
        handle_v18_schedule_delay as _admin_handle_broadcast_schedule_delay,
    )

    async def _admin_broadcast_text_bridge(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        user = getattr(update, "effective_user", None)
        message = getattr(update, "effective_message", None)
        if not user or not message or getattr(update, "callback_query", None) is not None:
            return
        try:
            if int(user.id) != int(ADMIN_TG_ID):
                return
        except Exception:
            return
        data = ctx.user_data or {}
        if data.get("__single_bot_mode") != "admin":
            return
        mode = data.get("v18_bc_mode")
        if mode not in {"all", "select", "schedule"}:
            return

        # Select-user flow: first text is the user ID, subsequent text is the
        # actual message to send.
        if mode == "select" and not data.get("v18_bc_target_ids"):
            await _admin_handle_broadcast_select_user(update, ctx)
            raise ApplicationHandlerStop

        # Schedule flow: first text is the message; the next text is the
        # delay (10M / 2S / 1D).
        if mode == "schedule" and data.get("v18_bc_source_chat_id"):
            await _admin_handle_broadcast_schedule_delay(update, ctx)
            raise ApplicationHandlerStop

        # Broadcast All, selected-user message, and the first message in a
        # scheduled broadcast all enter the normal message handler.
        await _admin_handle_broadcast_message(update, ctx)
        raise ApplicationHandlerStop

    # Run before the legacy ConversationHandler bridge.
    app.add_handler(TypeHandler(Update, _admin_broadcast_text_bridge, block=True), group=-151)

    # Highest practical callback/message bridge for the admin dashboard.
    # ConversationHandlers keep their state because the original handler
    # objects remain alive in _legacy_admin_app.
    app.add_handler(TypeHandler(Update, _admin_update_bridge, block=True), group=-150)

    # ── SINGLE-BOT COMMAND MODE GATE ────────────────────────────────────────
    # /start and /admin MUST be resolved before ANY migrated ConversationHandler
    # or broadcast text bridge.  Otherwise an admin who is in an Admin
    # conversation can send /start and the broadcast bridge may consume that
    # command as normal text before cmd_start() gets a chance to switch back to
    # USER MODE.  PTB evaluates lower handler groups first, so these command
    # gates intentionally live above the admin bridge.
    from admin_bot import cmd_start as _admin_dashboard

    async def _clear_admin_conversations_for_user(user_id: int, chat_id: int | None = None):
        try:
            key = (chat_id, user_id) if chat_id is not None else None
            for _handler in _admin_registry_handlers:
                if isinstance(_handler, ConversationHandler):
                    if key is not None:
                        _handler._conversations.pop(key, None)
                    else:
                        for _key in list(_handler._conversations):
                            if isinstance(_key, tuple) and len(_key) >= 2 and _key[-1] == user_id:
                                _handler._conversations.pop(_key, None)
        except Exception:
            logger.exception("Could not clear stale admin conversation state for %s", user_id)

    async def _start_command_priority(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        # /start ALWAYS means USER MODE, including for the primary admin.
        # Clear any stale admin conversation/broadcast state first so /start
        # itself can never be mistaken for broadcast text.
        user = getattr(update, "effective_user", None)
        chat = getattr(update, "effective_chat", None)
        uid = int(user.id) if user else 0
        try:
            if ctx.user_data is not None:
                ctx.user_data["__single_bot_mode"] = "user"
                for _key in (
                    "v18_bc_mode", "v18_bc_target_ids", "v18_bc_source_chat_id",
                    "v18_bc_source_message_id", "v18_bc_preview",
                ):
                    ctx.user_data.pop(_key, None)
        except Exception:
            pass
        await _clear_admin_conversations_for_user(uid, getattr(chat, "id", None))
        await _clear_user_convs(update)
        await cmd_start(update, ctx)
        raise ApplicationHandlerStop

    # Highest priority: /start must beat the broadcast/admin bridges.
    app.add_handler(CommandHandler("start", _start_command_priority, filters=None), group=-210)

    async def _admin_command_priority(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        # /admin explicitly switches the primary admin account into ADMIN MODE.
        # /start switches it back to USER MODE.
        try:
            if ctx.user_data is not None:
                ctx.user_data["__single_bot_mode"] = "admin"
                for _key in (
                    "v18_bc_mode", "v18_bc_target_ids", "v18_bc_source_chat_id",
                    "v18_bc_source_message_id", "v18_bc_preview",
                ):
                    ctx.user_data.pop(_key, None)
        except Exception:
            pass
        # Leaving USER MODE must also terminate any user-side conversation so
        # the next admin callback cannot be consumed by a user ConversationHandler.
        await _clear_user_convs(update)
        await _clear_admin_conversations_for_user(
            int(update.effective_user.id) if update.effective_user else 0,
            int(update.effective_chat.id) if update.effective_chat else None,
        )
        try:
            # Authoritative dashboard entry point.  The admin dashboard itself
            # performs the final primary/extra-admin authorization check.
            await _admin_dashboard(update, ctx)
        except Exception as _admin_exc:
            logger.exception("/admin dashboard handler failed: %s", _admin_exc)
            if getattr(update, "effective_message", None):
                try:
                    await update.effective_message.reply_text(
                        "❌ Admin panel failed to open. Check ADMIN_TG_ID in hosting variables."
                    )
                except Exception:
                    pass
        # Never allow another handler/conversation to consume /admin.
        raise ApplicationHandlerStop

    # Keep this above every user/admin ConversationHandler.
    app.add_handler(
        CommandHandler(
            "admin",
            _admin_command_priority,
            filters=filters.ChatType.PRIVATE,
        ),
        group=-1000,
    )
    logger.info("Mounted %s Admin Bot handlers into the User Bot (/admin) at priority -200", len(_admin_registry_handlers))

    async def _admin_callback_isolation(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        # Any callback from the primary admin account that was not consumed by
        # the admin dispatcher must never fall into a normal USER callback.
        q = getattr(update, "callback_query", None)
        user = getattr(update, "effective_user", None)
        if q is not None and user is not None and int(user.id) == int(ADMIN_TG_ID):
            # In USER MODE, do not intercept anything. The normal User Bot
            # callback handlers must receive the admin's user-panel buttons.
            try:
                if (ctx.user_data or {}).get("__single_bot_mode") != "admin":
                    return
            except Exception:
                return
            try:
                await q.answer("Use the Admin Dashboard buttons.", show_alert=True)
            except Exception:
                pass
            raise ApplicationHandlerStop

    # This runs after the admin bridge but before the normal user catch-all.
    app.add_handler(TypeHandler(Update, _admin_callback_isolation, block=True), group=-140)
    app.add_handler(CallbackQueryHandler(_cb_fallback))

    return app


