async def _record_pending_giveaway_referral(user_id: int, ctx) -> bool:
    arg = (ctx.user_data or {}).get("pending_gw_ref")
    if not arg or not str(arg).startswith("gwref_"):
        return False
    try:
        parts = str(arg).split("_")
        if len(parts) != 3:
            return False
        gid, referrer = int(parts[1]), int(parts[2])
        if gid <= 0 or referrer == int(user_id):
            return False
        gw = await db.get_active_giveaway()
        if not gw or int(gw["id"]) != gid or str(gw.get("giveaway_type") or "random") != "invite":
            return False
        added = await db.add_giveaway_referral(gid, referrer, int(user_id))
        if added:
            # Keep referral notifications lightweight; the admin gets one event per
            # successful referral/start, while the original participant remains unique.
            try:
                count = await db.get_giveaway_referral_count(gid, referrer)
                await ctx.bot.send_message(
                    chat_id=ADMIN_TG_ID,
                    text=f"🔗 *GIVEAWAY REFERRAL*\n\n👤 User ID: `{user_id}`\n👑 Referrer ID: `{referrer}`\n📊 Referrals: *{count}*\n🆔 Giveaway ID: `{gid}`",
                    parse_mode="Markdown",
                )
            except Exception as exc:
                logger.warning("giveaway referral admin notify failed: %s", exc)
        ctx.user_data.pop("pending_gw_ref", None)
        return added
    except Exception as exc:
        logger.warning("pending giveaway referral failed: %s", exc)
        return False


def _gw_user_type(gw):
    return str(gw.get("giveaway_type") or "random").lower()


async def cb_pw_giveaway(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not await check_banned_for_callback(update, ctx):
        return
    gw = await db.get_active_giveaway()
    if not gw:
        await q.answer("No active giveaway right now.", show_alert=True)
        try:
            await q.message.edit_text("🎉 *Giveaway*\n\nThere is currently no active giveaway.",
                                      parse_mode="Markdown", reply_markup=await _event_menu_kb())
        except Exception:
            await q.message.reply_text("🎉 Giveaway\n\nThere is currently no active giveaway.",
                                        reply_markup=await _event_menu_kb())
        return
    await q.answer()
    participants = await db.get_giveaway_entry_count(int(gw["id"]))
    gtype = _gw_user_type(gw)
    type_label = "Invite Link" if gtype == "invite" else "Random Winner"
    text = (
        "🎉 *GIVEAWAY* 🎉\n\n"
        f"🎉 *GIVEAWAY NAME*\n{gw.get('name','')}\n\n"
        f"🎁 *PRIZE*\n{gw.get('prize','')}\n\n"
        f"🏆 *TOTAL WINNERS:* {int(gw.get('winners_count') or 0)}\n"
        f"👥 *TOTAL PARTICIPANTS:* {participants}\n"
        f"⏰ *GIVEAWAY TILL:* {str(gw.get('ends_at',''))[:19]} UTC\n"
        f"🎯 *GIVEAWAY TYPE:* {type_label}\n\n"
        "Tap *PARTICIPATE* to enter."
    )
    await q.message.edit_text(
        text, parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [user_button("🎉 PARTICIPATE", callback_data=f"gw_join_{gw['id']}")],
            [user_button("🔙 Back", callback_data="cb_play_win")],
        ])
    )


async def cb_giveaway_participate(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    user = update.effective_user
    if not await check_banned_for_callback(update, ctx):
        return
    try:
        await q.answer("Checking your entry…")
    except Exception:
        pass
    try:
        parts = str(q.data).split("_", 2)
        gid = int(parts[2])
        gw = await db.get_active_giveaway()
        if not gw or int(gw.get("id") or 0) != gid:
            await q.answer("This giveaway has ended.", show_alert=True)
            return
        try:
            ends = datetime.strptime(str(gw.get("ends_at", ""))[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
            if ends.timestamp() <= time.time():
                await _end_giveaway(gid, ctx.application)
                await q.answer("This giveaway has ended.", show_alert=True)
                return
        except Exception:
            pass
        await db.upsert_user(user.id, username=user.username or "")
        added = await db.add_giveaway_entry(gid, user.id, user.full_name or "User", user.username)
        if not added:
            if str(gw.get("giveaway_type") or "random").lower() == "invite":
                count = await db.get_giveaway_referral_count(gid, user.id)
                bot_username = (gw.get("invite_bot_username") or "").lstrip("@")
                if not bot_username:
                    try: bot_username = (await ctx.bot.get_me()).username or ""
                    except Exception: bot_username = ""
                link = f"https://t.me/{bot_username}?start=gwref_{gid}_{user.id}" if bot_username else ""
                await q.message.reply_text(
                    f"🔗 *YOUR REFER LINK*\n\n`{link}`\n\n📊 *TOTAL REFERRALS:* {count}\n\n"
                    "Share this link in your chats or contacts and ask them to start the bot and complete verification.",
                    parse_mode="Markdown",
                )
            else:
                await q.answer("You are already participating.", show_alert=True)
            return

        # Single-bot architecture: notify the admin through the same User Bot.
        try:
            admin_text = (
                "🎉 *GIVEAWAY PARTICIPATION*\n\n"
                f"👤 Name: {user.full_name or 'User'}\n"
                f"🔗 Username: @{user.username}" if user.username else
                f"🎉 *GIVEAWAY PARTICIPATION*\n\n👤 Name: {user.full_name or 'User'}\n🔗 Username: None"
            )
            await ctx.bot.send_message(chat_id=ADMIN_TG_ID, text=admin_text, parse_mode="Markdown")
        except Exception as exc:
            logger.warning("single-bot giveaway participation notify failed: %s", exc)

        count = await db.get_giveaway_entry_count(gid)
        gtype = str(gw.get("giveaway_type") or "random").lower()
        if gtype == "invite":
            bot_username = (gw.get("invite_bot_username") or "").lstrip("@")
            if not bot_username:
                try: bot_username = (await ctx.bot.get_me()).username or ""
                except Exception: bot_username = ""
            link = f"https://t.me/{bot_username}?start=gwref_{gid}_{user.id}" if bot_username else "Link unavailable"
            referrals = await db.get_giveaway_referral_count(gid, user.id)
            text = (
                "🎉 *YOUR ENTRY IS RECORDED IN GIVEAWAY* ✅\n\n"
                f"🎁 Prize: *{gw.get('prize','')}*\n"
                f"🏆 Winners: *{gw.get('winners_count',0)}*\n"
                f"👥 Total Participants: *{count}*\n\n"
                "🔗 *YOUR REFER LINK*\n"
                f"`{link}`\n\n"
                "📌 *HOW TO WIN*\n"
                "1️⃣ Share this link in your chats and contacts.\n"
                "2️⃣ Ask them to start the bot using your link.\n"
                "3️⃣ They must complete human verification.\n"
                "4️⃣ If force-join is enabled, they must join all required channels.\n"
                "5️⃣ Each verified unique start counts as 1 referral.\n\n"
                f"📊 *TOTAL REFERRALS:* {referrals}"
            )
        else:
            text = (
                "🎉 *YOUR ENTRY IS RECORDED IN GIVEAWAY* ✅\n\n"
                f"🎁 Prize: *{gw.get('prize','')}*\n"
                f"🏆 Winners: *{gw.get('winners_count',0)}*\n"
                f"👥 Total Participants: *{count}*\n\n"
                "🏆 Winners will be selected when the giveaway ends."
            )
        kb = InlineKeyboardMarkup([[user_button("🎉 Giveaway Details", callback_data="pw_giveaway")], [user_button("🎮 Play & Win", callback_data="cb_play_win")]])
        try:
            await q.message.edit_text(text, parse_mode="Markdown", reply_markup=kb)
        except Exception:
            await q.message.reply_text(text, parse_mode="Markdown", reply_markup=kb)
    except Exception as exc:
        logger.exception("giveaway participation failed for user=%s: %s", getattr(user, "id", None), exc)
        try: await q.answer("Could not record the entry. Please try again.", show_alert=True)
        except Exception: pass
        try: await q.message.reply_text("⚠️ We could not record your giveaway entry right now. Please tap PARTICIPATE again.")
        except Exception: pass


async def _gw_select_winners(gw: dict, entries: list[dict]) -> list[dict]:
    gtype = _gw_user_type(gw)
    limit = min(int(gw.get("winners_count") or 0), len(entries))
    if limit <= 0:
        return []
    if gtype == "invite":
        board = await db.get_giveaway_referral_leaderboard(int(gw["id"]))
        entry_ids = {int(e["user_id"]) for e in entries}
        ranked = [x for x in board if int(x["referrer_id"]) in entry_ids]
        if not ranked:
            return []
        # Highest referral counts win; ties are randomized only among equal counts.
        groups = {}
        for row in ranked:
            groups.setdefault(int(row["referrals"]), []).append(row)
        winners = []
        for score in sorted(groups, reverse=True):
            group = groups[score][:]
            secrets.SystemRandom().shuffle(group)
            for row in group:
                entry = next((e for e in entries if int(e["user_id"]) == int(row["referrer_id"])), None)
                if entry:
                    winners.append(entry)
                if len(winners) >= limit:
                    return winners
        return winners
    return secrets.SystemRandom().sample(entries, limit)


async def _end_giveaway(giveaway_id: int, application, *, cancelled=False, reason=""):
    gw = await db.get_active_giveaway()
    if not gw or int(gw["id"]) != giveaway_id:
        return None
    entries = await db.get_giveaway_entries(giveaway_id)
    if cancelled:
        await db.set_giveaway_cancelled(giveaway_id, reason)
        msg = (
            "⚠️ *GIVEAWAY CANCELLED*\n\n"
            "We're sorry, but the admin had to close this giveaway.\n\n"
            f"📝 *Reason:* {reason or 'Not specified'}"
        )
        await _broadcast_user_bot(msg)
        return []
    winners = await _gw_select_winners(gw, entries)
    await db.finish_giveaway(giveaway_id, winners)
    lines = [
        "🎉 *GIVEAWAY ENDED* 🎉", "",
        f"🎁 *PRIZE:* {gw.get('prize','')}",
        f"👥 *PARTICIPANTS:* {len(entries)}",
        f"🏆 *WINNERS:* {len(winners)}", ""
    ]
    for i,w in enumerate(winners,1):
        lines.append(f"{i}️⃣ @{w.get('username')}" if w.get('username') else f"{i}️⃣ {w.get('name','User')}")
    await _broadcast_user_bot("\n".join(lines))
    try:
        details=["🎉 *GIVEAWAY RESULTS*",f"🎁 Prize: *{gw.get('prize','')}*",f"🎯 Type: *{'Invite Link' if _gw_user_type(gw)=='invite' else 'Random Winner'}*",""]
        for i,w in enumerate(winners,1):
            details += [f"🏆 Winner #{i}",f"👤 {w.get('name','User')}",f"🔗 @{w.get('username')}" if w.get('username') else "🔗 No username",f"🆔 `{w.get('user_id')}`",""]
        await application.bot.send_message(chat_id=ADMIN_TG_ID,text="\n".join(details),parse_mode="Markdown")
    except Exception as exc:
        logger.warning("giveaway result admin notify failed: %s", exc)
    return winners


async def _giveaway_expiry_checker(application):
    while True:
        try:
            gw=await db.get_active_giveaway()
            if gw:
                ends=datetime.strptime(str(gw["ends_at"])[:19],"%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
                if ends.timestamp()<=time.time():
                    await _end_giveaway(int(gw["id"]),application)
        except Exception as exc:
            logger.warning("giveaway checker failed: %s", exc)
        await asyncio.sleep(10)

