os.makedirs(SESSIONS_DIR, exist_ok=True)
os.makedirs(DATA_DIR,     exist_ok=True)

def _migrate_legacy_state():
    """Migrate an existing DB from an older uploaded workspace once."""
    import shutil
    from pathlib import Path
    persistent_db = os.path.join(DATA_DIR, "bot.db")
    if os.path.exists(persistent_db):
        return
    candidates = [os.path.join(BASE_DIR, "data", INSTANCE_ID, "bot.db")]
    home = Path(os.path.expanduser("~"))
    for root_name in ("downloads", "Downloads", "data"):
        root = home / root_name
        try:
            if root.exists():
                candidates.extend(str(x) for x in root.glob(f"**/data/{INSTANCE_ID}/bot.db"))
        except Exception:
            pass
    for source_db in candidates:
        if source_db and os.path.isfile(source_db) and os.path.abspath(source_db) != os.path.abspath(persistent_db):
            os.makedirs(os.path.dirname(persistent_db), exist_ok=True)
            shutil.copy2(source_db, persistent_db)
            print(f"[PERSISTENCE] Migrated existing user database: {source_db}")
            break

_migrate_legacy_state()

