            "ALTER TABLE messages ADD COLUMN reply_to_index INTEGER DEFAULT NULL",
            # Premium improvements: store amount paid and track expiry notification
            "ALTER TABLE premium ADD COLUMN amount_paid REAL DEFAULT 0",
