async def _fetchone(query, params=()):
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(query, params) as cur:
            row = await cur.fetchone()
            return dict(row) if row else None


async def _fetchall(query, params=()):
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        async with db.execute(query, params) as cur:
            rows = await cur.fetchall()
            return [dict(r) for r in rows]


async def _execute(query, params=()):
    """V88: Execute with retry on database lock."""
    max_retries = 3
    for attempt in range(max_retries):
        try:
            async with aiosqlite.connect(DB_PATH, timeout=10.0) as db:
                await db.execute(query, params)
                await db.commit()
            return
        except Exception as e:
            error_str = str(e).lower()
            is_lock = "database is locked" in error_str or "readonly" in error_str
            
            if is_lock and attempt < max_retries - 1:
                # V88: Database locked - wait and retry
                await asyncio.sleep(0.5 * (attempt + 1))
                continue
            
            raise


