# ── Premium ───────────────────────────────────────────────────────────────────
async def get_premium(user_id):
    return await _fetchone("SELECT * FROM premium WHERE user_id=?", (user_id,))


async def set_premium(user_id, plan_key, days, amount_paid: float = 0):
    """
    Activate or renew premium for a user.

    Uses hours instead of days to avoid SQLite rounding issues that caused
    1-day plans to expire immediately (e.g. '+1 days' at 23:59 UTC could
    expire within seconds on some SQLite builds). Storing as hours ensures
    a 1-day plan always grants exactly 24 hours.
    """
    hours = int(round(float(days) * 24))
    await _execute("""
        INSERT INTO premium (user_id, plan_key, days, starts_at, expires_at, is_active, amount_paid, expiry_notified)
        VALUES (?, ?, ?,
            CURRENT_TIMESTAMP,
            datetime(CURRENT_TIMESTAMP, '+' || ? || ' hours'),
            1, ?, 0)
        ON CONFLICT(user_id) DO UPDATE SET
            plan_key=excluded.plan_key,
            days=excluded.days,
            starts_at=excluded.starts_at,
            expires_at=excluded.expires_at,
            is_active=1,
            amount_paid=excluded.amount_paid,
            expiry_notified=0
    """, (user_id, plan_key, days, hours, amount_paid))


async def add_premium_days(user_id: int, days: int, plan_key: str = "event_reward"):
    """Add event-reward premium on top of an existing active premium period."""
    days = max(1, int(days))
    row = await get_premium(user_id)
    active = False
    if row and row.get("expires_at"):
        active_row = await _fetchone(
            "SELECT 1 FROM premium WHERE user_id=? AND is_active=1 AND expires_at > CURRENT_TIMESTAMP",
            (user_id,),
        )
        active = bool(active_row)
    if active:
        await _execute(
            "UPDATE premium SET expires_at=datetime(expires_at, '+' || ? || ' days'), days=days+?, plan_key=?, is_active=1, expiry_notified=0 WHERE user_id=?",
            (days, days, plan_key, user_id),
        )
    else:
        await set_premium(user_id, plan_key, days, amount_paid=0)


