# ── Milestone referral rewards ─────────────────────────────────────────────────
# Hardcoded defaults — used when no DB value has been set yet.
REFERRAL_MILESTONES: dict[int, int] = {
    5:  1,
    10: 3,
    15: 7,
    20: 15,
    25: 30,
}


async def get_referral_milestones() -> dict[int, int]:
    """Return the milestone table {refs_needed: bonus_days} from the DB.
    Falls back to the hardcoded REFERRAL_MILESTONES defaults."""
    raw = await get_setting("referral_milestones", None)
    if raw:
        try:
            data = json.loads(raw)
            return {int(k): int(v) for k, v in data.items()}
        except Exception:
            pass
    return dict(REFERRAL_MILESTONES)


async def set_referral_milestones(milestones: dict[int, int]):
    """Persist a new milestone table to the DB."""
    await set_setting(
        "referral_milestones",
        json.dumps({str(k): v for k, v in sorted(milestones.items())}),
    )


async def get_milestone_bonus_async(completed_refs: int) -> int:
    """Return how many bonus days this exact completed_refs count unlocks (0 if not a milestone)."""
    milestones = await get_referral_milestones()
    return milestones.get(completed_refs, 0)


async def get_milestone_total_days_async(completed_refs: int) -> int:
    """Return the cumulative milestone days earned for the given ref count."""
    milestones = await get_referral_milestones()
    days = 0
    for threshold, d in milestones.items():
        if completed_refs >= threshold:
            days = d
    return days


async def get_next_milestone_async(completed_refs: int) -> tuple[int, int] | None:
    """Return (refs_needed, days) for the next milestone, or None if all milestones reached."""
    milestones = await get_referral_milestones()
    for threshold, d in sorted(milestones.items()):
        if completed_refs < threshold:
            return threshold, d
    return None


# ── Sync shims kept for backward compatibility ─────────────────────────────────
def get_milestone_bonus(completed_refs: int) -> int:
    return REFERRAL_MILESTONES.get(completed_refs, 0)


def get_milestone_total_days(completed_refs: int) -> int:
    days = 0
    for threshold, d in REFERRAL_MILESTONES.items():
        if completed_refs >= threshold:
            days = d
    return days


def get_next_milestone(completed_refs: int) -> tuple[int, int] | None:
    for threshold, d in sorted(REFERRAL_MILESTONES.items()):
        if completed_refs < threshold:
            return threshold, d
    return None


