async def extend_premium(user_id: int, days: int, plan_key: str = "referral"):
    """Add `days` to the user's current premium, or create a new one if none active."""
    existing = await _fetchone(
        "SELECT * FROM premium WHERE user_id=? AND is_active=1 AND expires_at > CURRENT_TIMESTAMP",
        (user_id,))
    hours = int(round(float(days) * 24))
    if existing:
        await _execute("""
            UPDATE premium
            SET expires_at = datetime(expires_at, '+' || ? || ' hours'),
                days       = days + ?,
                expiry_notified = 0
            WHERE user_id=?
        """, (hours, days, user_id))
    else:
        await set_premium(user_id, plan_key, days)


async def deduct_premium_days(user_id: int, days: int):
    """Deduct `days` from the user's current premium."""
    existing = await _fetchone(
        "SELECT * FROM premium WHERE user_id=? AND is_active=1 AND expires_at > CURRENT_TIMESTAMP",
        (user_id,))
    
    if not existing:
        return
    
    hours = int(round(float(days) * 24))
    new_days = max(0, existing.get('days', 0) - days)
    
    if new_days <= 0:
        # Expire the premium immediately
        await _execute(
            "UPDATE premium SET is_active=0, expires_at=CURRENT_TIMESTAMP WHERE user_id=?",
            (user_id,)
        )
    else:
        # Deduct the days from expiry time
        await _execute("""
            UPDATE premium
            SET expires_at = datetime(expires_at, '-' || ? || ' hours'),
                days       = ?,
                expiry_notified = 0
            WHERE user_id=?
        """, (hours, new_days, user_id))


async def get_users_to_notify_expired() -> list:
    """
    Return premium rows where:
      - is_active = 1 (was active, not already revoked)
      - expires_at <= CURRENT_TIMESTAMP (subscription has now lapsed)
      - expiry_notified = 0 (notification not yet sent)
    Also marks them as notified and revokes is_active atomically.
    """
    rows = await _fetchall("""
        SELECT p.user_id, p.plan_key, p.days, p.expires_at, p.amount_paid,
               u.username
        FROM premium p
        LEFT JOIN users u ON p.user_id = u.user_id
        WHERE p.is_active = 1
          AND p.expires_at <= CURRENT_TIMESTAMP
          AND p.expiry_notified = 0
    """)
    if rows:
        for row in rows:
            await _execute("""
                UPDATE premium
                SET is_active = 0, expiry_notified = 1
                WHERE user_id = ?
            """, (row["user_id"],))
    return rows


