async def create_ad_log(
    user_id: int,
    delay_minutes: int,
    target: str,
    total_chats: int,
    sent_chats: int,
    failed_chats: int,
    total_groups: int,
    sent_groups: int,
    failed_groups: int,
) -> int:
    async with aiosqlite.connect(DB_PATH) as db:
        db.row_factory = aiosqlite.Row
        cur = await db.execute(
            """INSERT INTO ad_logs
               (user_id, delay_minutes, target,
                total_chats, sent_chats, failed_chats,
                total_groups, sent_groups, failed_groups)
               VALUES (?,?,?,?,?,?,?,?,?)""",
            (user_id, delay_minutes, target,
             total_chats, sent_chats, failed_chats,
             total_groups, sent_groups, failed_groups),
        )
        await db.commit()
        return cur.lastrowid


