async def is_agent(user_id: int) -> bool:
    row = await _fetchone("SELECT 1 FROM agents WHERE user_id=?", (user_id,))
    return row is not None


async def get_agent(user_id: int) -> dict | None:
    return await _fetchone("SELECT * FROM agents WHERE user_id=?", (user_id,))


async def create_agent_order(
    agent_id: int,
    channel_link: str,
    member_target: int,
    payment_amount: float,
) -> dict:
    await _execute(
        """INSERT INTO agent_orders (agent_id, channel_link, member_target, payment_amount)
           VALUES (?,?,?,?)""",
        (agent_id, channel_link, member_target, payment_amount),
    )
    row = await _fetchone(
        "SELECT * FROM agent_orders WHERE agent_id=? ORDER BY id DESC LIMIT 1",
        (agent_id,),
    )
    return row


async def get_agent_order(order_id: int) -> dict | None:
    return await _fetchone("SELECT * FROM agent_orders WHERE id=?", (order_id,))


async def update_agent_order(order_id: int, **fields) -> None:
    fields["updated_at"] = "CURRENT_TIMESTAMP"
    set_clause = ", ".join(
        f"{k}=CURRENT_TIMESTAMP" if v == "CURRENT_TIMESTAMP" else f"{k}=?"
        for k, v in fields.items()
    )
    values = [v for v in fields.values() if v != "CURRENT_TIMESTAMP"]
    await _execute(
        f"UPDATE agent_orders SET {set_clause} WHERE id=?",
        values + [order_id],
    )


# ── Payout System ──────────────────────────────────────────────────────────────

async def set_payout_channel(admin_id: int, channel_id: int, channel_title: str = "") -> None:
    """Save or update payout channel for an admin."""
    await _execute("""
        INSERT OR REPLACE INTO payout_channels (admin_id, channel_id, channel_title, verified)
        VALUES (?, ?, ?, 1)
    """, (admin_id, channel_id, channel_title))


async def get_payout_channel(admin_id: int) -> dict | None:
    """Get payout channel for an admin."""
    return await _fetchone(
        "SELECT * FROM payout_channels WHERE admin_id=?",
        (admin_id,)
    )


async def delete_payout_channel(admin_id: int) -> None:
    """Remove payout channel for an admin."""
    await _execute(
        "DELETE FROM payout_channels WHERE admin_id=?",
        (admin_id,)
    )


async def record_payout(admin_id: int, days: int, amount: float, payment_id: int = None, payout_type: str = "automatic") -> int:
    """Record a payout in the database and return the record ID."""
    async with aiosqlite.connect(DB_PATH) as db:
        await db.execute("""
            INSERT INTO payout_records (admin_id, payment_id, days, amount, payout_type)
            VALUES (?, ?, ?, ?, ?)
        """, (admin_id, payment_id, days, amount, payout_type))
        await db.commit()
        cursor = await db.execute("SELECT last_insert_rowid()")
        result = await cursor.fetchone()
        return result[0] if result else None


async def check_payout_recorded(payment_id: int) -> bool:
    """Check if a payment has already been recorded as a payout."""
    result = await _fetchone(
        "SELECT id FROM payout_records WHERE payment_id=? LIMIT 1",
        (payment_id,)
    )
    return result is not None


async def get_agent_orders_by_status(agent_id: int, status: str) -> list:
    return await _fetchall(
        "SELECT * FROM agent_orders WHERE agent_id=? AND status=? ORDER BY id DESC",
        (agent_id, status),
    )


async def get_all_agent_orders_by_status(status: str) -> list:
    """Return all orders across all agents matching *status*, newest first."""
    return await _fetchall(
        """SELECT ao.*, a.username as agent_username
           FROM agent_orders ao
           LEFT JOIN agents a ON ao.agent_id = a.user_id
           WHERE ao.status=? ORDER BY ao.id DESC""",
        (status,),
    )

    
    # ── EMOJI SETTINGS MANAGEMENT ────────────────────────────────────────────
    async def set_emoji_mode(self, admin_id: int, mode: str) -> bool:
        """Set emoji mode for admin (premium or unicode)"""
        try:
            await _execute("""
                INSERT OR REPLACE INTO emoji_settings (admin_id, emoji_mode)
                VALUES (?, ?)
            """, (admin_id, mode))
            return True
        except Exception as e:
            logger.error(f"Error setting emoji mode: {e}")
            return False
    
    async def get_emoji_mode(self, admin_id: int) -> str:
        """Get emoji mode for admin (default: premium)"""
        try:
            result = await _fetch_one(
                "SELECT emoji_mode FROM emoji_settings WHERE admin_id = ?",
                (admin_id,)
            )
            return result[0] if result else 'premium'
        except Exception as e:
            logger.error(f"Error getting emoji mode: {e}")
            return 'premium'
    
    async def toggle_premium_emoji(self, admin_id: int) -> str:
        """Toggle premium emoji mode"""
        current = await self.get_emoji_mode(admin_id)
        new_mode = "unicode" if current == "premium" else "premium"
        await self.set_emoji_mode(admin_id, new_mode)
        return new_mode
    
    async def toggle_unicode_emoji(self, admin_id: int) -> str:
        """Toggle unicode emoji mode"""
        current = await self.get_emoji_mode(admin_id)
        new_mode = "premium" if current == "unicode" else "unicode"
        await self.set_emoji_mode(admin_id, new_mode)
        return new_mode


    
