async def create_giveaway(name: str, prize: str, winners_count: int, ends_at: str,
                          created_by: int, giveaway_type: str = "random",
                          invite_bot_username: str = ""):
    await _execute(
        "INSERT INTO giveaways (name, prize, winners_count, ends_at, created_by, giveaway_type, invite_bot_username) "
        "VALUES (?,?,?,?,?,?,?)",
        (name, prize, winners_count, ends_at, created_by, giveaway_type, invite_bot_username or ""),
    )
    return await _fetchone("SELECT * FROM giveaways ORDER BY id DESC LIMIT 1")


async def add_giveaway_referral(giveaway_id: int, referrer_id: int, referred_id: int) -> bool:
    if int(referrer_id) == int(referred_id):
        return False
    try:
        await _execute(
            "INSERT INTO giveaway_referrals (giveaway_id,referrer_id,referred_id) VALUES (?,?,?)",
            (giveaway_id, referrer_id, referred_id),
        )
        return True
    except Exception as exc:
        if "UNIQUE" in str(exc).upper() or "PRIMARY KEY" in str(exc).upper():
            return False
        raise


async def get_giveaway_referral_count(giveaway_id: int, referrer_id: int) -> int:
    row = await _fetchone(
        "SELECT COUNT(*) AS n FROM giveaway_referrals WHERE giveaway_id=? AND referrer_id=?",
        (giveaway_id, referrer_id),
    )
    return int((row or {}).get("n") or 0)


async def get_giveaway_referral_leaderboard(giveaway_id: int):
    return await _fetchall(
        "SELECT r.referrer_id, COUNT(*) AS referrals, "
        "u.username, u.user_id "
        "FROM giveaway_referrals r LEFT JOIN users u ON u.user_id=r.referrer_id "
        "WHERE r.giveaway_id=? GROUP BY r.referrer_id ORDER BY referrals DESC, r.referrer_id ASC",
        (giveaway_id,),
    )


async def set_giveaway_cancelled(giveaway_id: int, reason: str = ""):
    await _execute(
        "UPDATE giveaways SET status='cancelled', ended_at=CURRENT_TIMESTAMP, cancel_reason=? "
        "WHERE id=? AND status IN ('active','stopped')",
        (reason[:1000], giveaway_id),
    )


async def get_giveaway_entry(giveaway_id: int, user_id: int):
    return await _fetchone(
        "SELECT * FROM giveaway_entries WHERE giveaway_id=? AND user_id=?",
        (giveaway_id, user_id),
    )
