async def get_force_join_chat_ids() -> dict:
    raw = await get_setting("force_join_chat_ids", "{}")
    try:
        data = json.loads(raw or "{}")
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


async def set_force_join_chat_id(channel_link: str, chat_id: int):
    mapping = await get_force_join_chat_ids()
    mapping[channel_link] = int(chat_id)
    await set_setting("force_join_chat_ids", json.dumps(mapping))


# ── Force Join: join requests waiting for the user to finish verification ────
async def _get_pending_requests() -> list:
    raw = await get_setting("fj_pending_requests", "[]")
    try:
        data = json.loads(raw or "[]")
        return data if isinstance(data, list) else []
    except Exception:
        return []


async def add_pending_join_request(user_id: int, chat_id: int):
    items = await _get_pending_requests()
    entry = {"user_id": int(user_id), "chat_id": int(chat_id)}
    if entry not in items:
        items.append(entry)
    await set_setting("fj_pending_requests", json.dumps(items))


async def pop_pending_join_requests(user_id: int) -> list:
    items = await _get_pending_requests()
    mine = [int(x["chat_id"]) for x in items if int(x.get("user_id", 0)) == int(user_id)]
    rest = [x for x in items if int(x.get("user_id", 0)) != int(user_id)]
    if mine:
        await set_setting("fj_pending_requests", json.dumps(rest))
    return mine


