async def get_fj_verified(admin_id: int):
    raw = await get_setting(f"fj_verified_{int(admin_id)}", "")
    if not raw:
        return None
    try:
        data = json.loads(raw)
        return data if isinstance(data, dict) and data.get("chat_id") else None
    except Exception:
        return None


async def clear_fj_verified(admin_id: int):
    await set_setting(f"fj_verified_{int(admin_id)}", "")
