# Central emoji settings used by the admin panel.
# Modes: "unicode" or "animated"; glow controls decorative styling where supported.
EMOJI_MODE = "unicode"
EMOJI_GLOW = False

def set_emoji_mode(mode: str):
    global EMOJI_MODE
    mode = (mode or "").lower()
    if mode not in ("unicode", "animated"):
        mode = "unicode"
    EMOJI_MODE = mode
    return EMOJI_MODE

def toggle_glow(enabled=None):
    global EMOJI_GLOW
    EMOJI_GLOW = (not EMOJI_GLOW) if enabled is None else bool(enabled)
    return EMOJI_GLOW

def emoji_status():
    return {"mode": EMOJI_MODE, "glow": EMOJI_GLOW}
''',
    'gmail_checker': r'''
"""
Gmail IMAP checker for automatic UPI payment verification.
Reads GMAIL_ADDRESS and GMAIL_APP_PASSWORD from environment.

Verification logic:
  - Searches the last 10–20 emails from any payment source (UPI, bank alerts,
    GPay, PhonePe, Paytm, FamPay, NEFT/IMPS confirmations, etc.)
  - A payment is verified if BOTH conditions are met:
      1. The submitted UTR / Transaction ID appears in the email text
      2. The plan amount appears in the email text
  - Returns a VerifyResult with details for transparent user feedback.
"""
import imaplib
import email as email_lib
import re
import os
import logging
from dataclasses import dataclass
from datetime import datetime, timedelta

logger = logging.getLogger(__name__)

GMAIL_ADDRESS = os.environ.get("GMAIL_ADDRESS", "")
GMAIL_APP_PASSWORD = os.environ.get("GMAIL_APP_PASSWORD", "")

# ── Payment-related senders / subjects to search ──────────────────────────────
_PAYMENT_SEARCH_QUERIES_TEMPLATE = [
    # Popular UPI & payment apps
    '(SINCE {date} SUBJECT "payment")',
    '(SINCE {date} SUBJECT "received")',
    '(SINCE {date} SUBJECT "transaction")',
    '(SINCE {date} SUBJECT "transfer")',
    '(SINCE {date} SUBJECT "credited")',
    '(SINCE {date} SUBJECT "debited")',
    '(SINCE {date} SUBJECT "utr")',
    '(SINCE {date} SUBJECT "upi")',
    # Common payment senders
    '(SINCE {date} FROM "gpay")',
    '(SINCE {date} FROM "phonepe")',
    '(SINCE {date} FROM "paytm")',
    '(SINCE {date} FROM "fampay")',
    '(SINCE {date} FROM "noreply@")',
    '(SINCE {date} FROM "alerts@")',
    '(SINCE {date} FROM "no-reply@")',
    # Direct ID search (catches anything)
    '(SINCE {date} BODY "{id}")',
]

# How many days back to look
_LOOKBACK_DAYS = 5

# Maximum emails to check (safety cap)
_MAX_EMAILS = 25


@dataclass
class VerifyResult:
    matched: bool
    reason: str = ""
    email_subject: str = ""


def _connect() -> imaplib.IMAP4_SSL:
    if not GMAIL_ADDRESS or not GMAIL_APP_PASSWORD:
        raise RuntimeError("Gmail credentials not configured.")
    mail = imaplib.IMAP4_SSL("imap.gmail.com")
    mail.login(GMAIL_ADDRESS, GMAIL_APP_PASSWORD)
    return mail


def _extract_text(msg) -> str:
    """Extract all readable text from an email message."""
    parts = []
    if msg.is_multipart():
        for part in msg.walk():
            ctype = part.get_content_type()
            if ctype in ("text/plain", "text/html"):
                try:
                    raw = part.get_payload(decode=True)
                    parts.append(raw.decode("utf-8", errors="ignore"))
                except Exception:
                    pass
    else:
        try:
            raw = msg.get_payload(decode=True)
            parts.append(raw.decode("utf-8", errors="ignore"))
        except Exception:
            pass
    return " ".join(parts)


def _normalize(text: str) -> str:
    """Lowercase and collapse whitespace."""
    return re.sub(r"\s+", " ", text.lower()).strip()


def _id_present(submitted: str, full_text: str) -> bool:
    """
    True if the submitted UTR / transaction ID appears in the email.
    Handles:
      - Exact substring match (case-insensitive)
      - Whitespace / punctuation around the ID
      - Token-level match among alphanumeric sequences
    """
    sub = _normalize(submitted)
    text = _normalize(full_text)

    # Direct substring match
    if sub in text:
        return True

    # Match with non-alphanumeric boundary characters stripped
    clean_sub = re.sub(r"[^a-z0-9]", "", sub)
    if not clean_sub:
        return False

    # Extract all alphanumeric tokens of similar length and compare
    tokens = re.findall(r"[a-z0-9]{6,}", text)
    for tok in tokens:
        if tok == clean_sub:
            return True

    return False


def _amount_present(amount: int, full_text: str) -> bool:
    """
    True if the plan amount (in INR) appears in the email in any common format.
    Handles: ₹10, Rs. 10, INR 10, 10.00, 10, etc.
    """
    text = _normalize(full_text)
    a = str(amount)

    candidates = [
        a,
        f"₹{a}",
        f"₹ {a}",
        f"rs.{a}", f"rs. {a}", f"rs {a}",
        f"inr{a}", f"inr {a}", f"inr. {a}", f"inr.{a}",
        f"{a}.00",
        f"₹{a}.00",
        f"rs.{a}.00", f"rs {a}.00",
        f"inr {a}.00",
        f"inr{a}.00",
    ]
    for c in candidates:
        if c.lower() in text:
            return True

    # Regex: digit boundary match (avoids matching "100" inside "1000")
    pattern = r"(?<!\d)" + re.escape(a) + r"(?!\d)"
    if re.search(pattern, text):
        # Make sure it's in a payment-money context
        money_context = re.compile(
            r"(?:₹|rs\.?|inr|amount|paid|credited|debited|transfer)"
            r".{0,20}"
            + re.escape(a)
            + r"|"
            + re.escape(a)
            + r".{0,20}(?:₹|rs\.?|inr|amount|paid|credited|debited)"
        )
        if money_context.search(text):
            return True

    return False


def check_payment(submitted_id: str, amount: int) -> VerifyResult:
    """
    Search Gmail for a payment email matching submitted_id AND amount.

    Returns a VerifyResult with .matched=True on success.
    This function is blocking (IMAP) — run via run_in_executor.
    """
    submitted_id = submitted_id.strip()

    if not GMAIL_ADDRESS or not GMAIL_APP_PASSWORD:
        logger.warning("Gmail credentials not set — auto-pay verification cannot run.")
        return VerifyResult(
            matched=False,
            reason="gmail_not_configured",
        )

    try:
        mail = _connect()
        mail.select("inbox")

        since_date = (datetime.now() - timedelta(days=_LOOKBACK_DAYS)).strftime("%d-%b-%Y")

        # Collect unique email IDs matching any of our broad search queries
        collected_ids: set[bytes] = set()
        for tmpl in _PAYMENT_SEARCH_QUERIES_TEMPLATE:
            query = tmpl.format(date=since_date, id=submitted_id)
            try:
                status, messages = mail.search(None, query)
                if status == "OK" and messages[0]:
                    for mid in messages[0].split():
                        collected_ids.add(mid)
                        if len(collected_ids) >= _MAX_EMAILS:
                            break
            except Exception:
                continue
            if len(collected_ids) >= _MAX_EMAILS:
                break

        logger.info(
            f"Payment check: {len(collected_ids)} candidate email(s) "
            f"for id={submitted_id!r} amount=₹{amount}"
        )

        # Sort newest first (higher IDs are more recent in IMAP)
        sorted_ids = sorted(collected_ids, reverse=True)

        id_found = False  # Did we find the UTR but wrong amount?

        for email_id in sorted_ids:
            try:
                status, msg_data = mail.fetch(email_id, "(RFC822)")
                if status != "OK" or not msg_data or not msg_data[0]:
                    continue
                raw_bytes = msg_data[0][1]
                msg = email_lib.message_from_bytes(raw_bytes)
                subject = str(msg.get("Subject", ""))
                body = _extract_text(msg)
                full_text = body + " " + subject

                if not _id_present(submitted_id, full_text):
                    continue

                id_found = True

                if _amount_present(amount, full_text):
                    logger.info(
                        f"Payment MATCHED: id={submitted_id!r} amount=₹{amount} "
                        f"email_id={email_id} subject={subject!r}"
                    )
                    mail.logout()
                    return VerifyResult(
                        matched=True,
                        reason="matched",
                        email_subject=subject,
                    )
                else:
                    logger.info(
                        f"Payment ID found but amount ₹{amount} not present: "
                        f"id={submitted_id!r} subject={subject!r}"
                    )

            except Exception as ex:
                logger.warning(f"Error reading email {email_id}: {ex}")
                continue

        mail.logout()

        if id_found:
            # UTR matched but amount didn't — likely wrong amount or plan mismatch
            logger.info(f"Payment check: ID found but amount mismatch for id={submitted_id!r}")
            return VerifyResult(matched=False, reason="amount_mismatch")

        logger.info(f"Payment check: no match for id={submitted_id!r} amount=₹{amount}")
        return VerifyResult(matched=False, reason="not_found")

    except RuntimeError as ex:
        return VerifyResult(matched=False, reason="gmail_not_configured")
    except imaplib.IMAP4.error as ex:
        logger.error(f"Gmail IMAP login failed: {ex}")
        return VerifyResult(matched=False, reason="gmail_auth_error")
    except Exception as ex:
        logger.error(f"Gmail check failed: {ex}")
        return VerifyResult(matched=False, reason="error")


# Keep old name as alias for backwards compatibility
def check_fampay_payment(submitted_id: str, amount: int) -> bool:
    return check_payment(submitted_id, amount).matched
''',
    'live_log': r'''
"""
Shared live-log channel between userbot (producer) and logs_bot (consumer).

Design:
  • userbot._ads_worker calls emit_line() / emit_instant() after every ad
    send, passing the owner's Telegram user_id alongside the text.
  • logs_bot runs a consumer coroutine that drains the queue and delivers
    each event ONLY to the subscriber whose user_id matches the owner_id.
  • Complete per-user isolation: no subscriber ever sees another user's logs.
  • Subscribers are stored in memory (_subscribers set) and persisted to the
    DB (settings key "logs_bot_subscribers") so they survive restarts.

Queue item format:
  ("line",    text, owner_id)  — individual delivery result (success / failure).
  ("instant", text, owner_id)  — sent immediately (cycle start / end / stats).

Both kinds are routed exclusively to the subscriber whose ID == owner_id.
"""
import asyncio

# Created by init() — must be called before any emit.
_queue: asyncio.Queue | None = None

# In-memory set of subscriber Telegram user IDs.
_subscribers: set[int] = set()


def init() -> None:
    """Initialise the shared queue.  Call once at process startup."""
    global _queue
    _queue = asyncio.Queue(maxsize=50_000)


def emit_line(text: str, owner_id: int) -> None:
    """Enqueue a per-delivery log line tagged with the owner's user ID.

    Only enqueues if the owner is currently subscribed — avoids filling the
    queue for users who have never opened the Ads Logs Bot.  Non-blocking.
    """
    if _queue is not None and owner_id in _subscribers:
        try:
            _queue.put_nowait(("line", text, owner_id))
        except asyncio.QueueFull:
            pass


def emit_instant(text: str, owner_id: int) -> None:
    """Enqueue a cycle-level message (sent immediately) tagged with owner_id."""
    if _queue is not None and owner_id in _subscribers:
        try:
            _queue.put_nowait(("instant", text, owner_id))
        except asyncio.QueueFull:
            pass


def add_subscriber(user_id: int) -> None:
    _subscribers.add(user_id)


def remove_subscriber(user_id: int) -> None:
    _subscribers.discard(user_id)


def get_subscribers() -> frozenset[int]:
    return frozenset(_subscribers)


def load_subscribers(ids: list[int]) -> None:
    """Bulk-load subscriber IDs at startup (from DB)."""
    _subscribers.update(ids)
''',
    'logs_bot': r'''
"""
Ads Logs Bot — real-time per-user advertisement delivery feed.

Each user sees ONLY their own ad delivery logs — complete isolation guaranteed
by routing each queue event exclusively to the subscriber whose Telegram user ID
matches the event's owner_id.  No cross-user data leakage is possible.

Activate by setting ADS_LOGS_BOT_TOKEN as an environment variable
(required at startup — see config.py).

Users subscribe by sending /start.  Live log lines are pushed by
userbot.py via live_log.emit_line() / live_log.emit_instant(), each
tagged with the owner's Telegram user_id.

Every delivery event is sent as its own individual Telegram message:

  Success:
    emoji_5287651735525937879 Delivered Successfully
    ━━━━━━━━━━━━━━━━━━━━━━
    emoji_6271665430650163493 Name: John Doe
    emoji_5870531058755178453 Status: Success emoji_5287651735525937879

    This delivery was completed successfully.

  Failure:
    emoji_6120625823285251747 Delivery Failed
    ━━━━━━━━━━━━━━━━━━━━━━
    emoji_6271665430650163493 Name: Alex
    emoji_5870531058755178453 Status: Failed emoji_6120625823285251747

    Reason:
    User has deleted their account.

  Cycle start / end / stats messages are also sent individually.
"""
import asyncio
import json
import logging

from telegram import Update
from telegram.ext import Application, CommandHandler, ContextTypes

import database as db
import live_log

logger = logging.getLogger(__name__)

_app: Application | None = None
_consumer_task: asyncio.Task | None = None


# ── Subscription ──────────────────────────────────────────────────────────────

async def cmd_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> None:
    """Subscribe this user to their own live ad log feed."""
    user_id = update.effective_user.id
    live_log.add_subscriber(user_id)

    # Persist updated subscriber list to DB so it survives restarts.
    subs = list(live_log.get_subscribers())
    await db.set_setting("logs_bot_subscribers", json.dumps(subs))

    await update.message.reply_text(
        "emoji_5870531058755178453 *Ads Logs — Your Personal Live Feed*\n\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n"
        "emoji_5287651735525937879 *Subscribed!*  Your ad delivery logs will appear here in real-time.\n\n"
        "emoji_5210952531676504517 *Privacy Guarantee:*\n"
        "You only see logs from *your own* ads — never anyone else's.\n"
        "Every log is routed exclusively to its owner.\n\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n"
        "emoji_5397782960512444700 *What you'll see:*\n\n"
        "  emoji_5465443379917629504 `Scanning dialogs` — target discovery started\n"
        "  emoji_5337312745857501717 `Cycle Started` — send round begins with totals\n"
        "  emoji_5287651735525937879 `Delivered Successfully` — name + confirmation\n"
        "  emoji_6120625823285251747 `Delivery Failed` — name + exact reason\n"
        "  emoji_5870531058755178453 `Live Stats` — periodic progress (every 30 s)\n"
        "  emoji_6073288235642000201 `Ad reply` — someone replied to your ad\n"
        "  emoji_5249050854392091366 `Ad mention` — someone mentioned your account\n"
        "  emoji_5447183459602669338 `Cycle Complete` — full summary per round\n\n"
        "━━━━━━━━━━━━━━━━━━━━━━\n"
        "Each event arrives as its own separate message so nothing gets lost.\n\n"
        "emoji_5276032951342088188 Logs continue automatically across every cycle.\n\n"
        "_Keep this chat open — no further action needed._",
        parse_mode="Markdown",
    )


# ── Private delivery ──────────────────────────────────────────────────────────

async def _send_to_owner(app: Application, owner_id: int, text: str) -> None:
    """Deliver a log message exclusively to the subscriber matching owner_id.

    This is the sole routing point — every log message passes through here.
    A subscriber only receives messages where their user_id == owner_id,
    making cross-user log leakage structurally impossible.
    """
    if owner_id not in live_log.get_subscribers():
        return
    try:
        await app.bot.send_message(owner_id, text, parse_mode="Markdown")
    except Exception as e:
        logger.debug("LogsBot → %s send error: %s", owner_id, e)


# ── Consumer ──────────────────────────────────────────────────────────────────

async def _consumer(app: Application) -> None:
    """
    Drain the shared live-log queue and route each event exclusively to the
    subscriber whose user_id matches the event's owner_id.

    Queue item format: (kind, text, owner_id)
      • "line"    — individual delivery result (success / failure)
      • "instant" — cycle-level message (start / stats / complete)

    Both kinds are routed the same way: one message, one recipient.
    """
    queue = live_log._queue
    if queue is None:
        return

    while True:
        try:
            _kind, text, owner_id = await queue.get()
            queue.task_done()
            await _send_to_owner(app, owner_id, text)

        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.warning("LogsBot consumer error: %s", e)
            await asyncio.sleep(1)


# ── Lifecycle ─────────────────────────────────────────────────────────────────

def build_app(token: str) -> Application:
    global _app
    _app = (
        Application.builder()
        .token(token)
        .concurrent_updates(True)
        .connect_timeout(60)
        .read_timeout(60)
        .write_timeout(60)
        .pool_timeout(60)
        .build()
    )
    _app.add_handler(CommandHandler("start", cmd_start))
    return _app


async def start_consumer(app: Application) -> None:
    global _consumer_task
    _consumer_task = asyncio.create_task(
        _consumer(app), name="logs_bot_consumer"
    )


async def stop_consumer() -> None:
    global _consumer_task
    if _consumer_task and not _consumer_task.done():
        _consumer_task.cancel()
        try:
            await _consumer_task
        except asyncio.CancelledError:
            pass
        _consumer_task = None
''',
    'main': r'''
"""
Launcher — initialises the database, then runs the User Bot
(and optionally the Ads Logs Bot). The full Admin dashboard is mounted inside
the User Bot and opened with /admin.

All configuration is read from environment variables (see config.py).
The bot will exit immediately with a clear error list if any required
variable is missing — there are no silent defaults.

The Telethon user-account API is deliberately not contacted during startup.
It is only needed when a user adds an account.  Contacting it before starting
the Bot API polling loop could leave a healthy Railway process alive while
both bots were still waiting on a slow or unreachable Telethon connection.
"""
import asyncio
import json
import logging
import os

# Credentials and settings are stored directly in config.py.
import config as _config
from config import SUPPORT_USERNAME
REQUIRED_ENV_VARIABLES = []

import database as db
import bot as user_bot_module
import live_log
import logs_bot as logs_bot_module
from config import (
    GMAIL_ADDRESS, GMAIL_APP_PASSWORD,
    ADS_LOGS_BOT_TOKEN,
)

logging.basicConfig(level=logging.INFO)
# bot.py configures logging while it is imported above.  Set the root level
# explicitly as well so Railway shows startup failures and polling status.
logging.getLogger().setLevel(logging.INFO)
# HTTPX includes bot tokens in Telegram request URLs at INFO level.
# Keep operational logs useful without exposing credentials.
logging.getLogger("httpx").setLevel(logging.WARNING)
logging.getLogger("httpcore").setLevel(logging.WARNING)
logger = logging.getLogger(__name__)


async def _start_app(app, name: str, allowed_updates: list[str]) -> None:
    """Start one PTB application using its complete async lifecycle.

    ``run_polling()`` cannot be used here because three applications share
    one event loop.  Calling these lifecycle methods explicitly is the
    supported equivalent and lets the user/admin bots run together.
    """
    logger.info("Initialising %s", name)
    await app.initialize()

    # Polling and Telegram webhooks are mutually exclusive.  A webhook left
    # behind by an earlier deployment can make a healthy-looking Termux
    # process receive no /start updates.  Explicitly clear it before polling.
    # Keep pending updates so legitimate messages are not silently discarded.
    try:
        await app.bot.delete_webhook(drop_pending_updates=False)
        logger.info("%s webhook cleared; switching to long polling", name)
    except Exception:
        logger.exception("Could not clear webhook for %s", name)

    # PTB calls post_init automatically from run_polling().  Since this
    # launcher uses the explicit lifecycle, invoke it here as well.  The user
    # bot uses post_init for its premium-expiry background task.
    post_init = getattr(app, "post_init", None)
    if post_init is not None:
        await post_init(app)

    await app.start()
    await app.updater.start_polling(
        drop_pending_updates=False,
        allowed_updates=allowed_updates,
    )
    logger.info("%s is polling Telegram updates", name)


async def _stop_app(app, name: str) -> None:
    """Stop an application without masking the original shutdown error."""
    try:
        if app.updater and app.updater.running:
            await app.updater.stop()
    except Exception:
        logger.exception("Error stopping %s updater", name)
    try:
        if app.running:
            await app.stop()
    except Exception:
        logger.exception("Error stopping %s", name)
    try:
        await app.shutdown()
    except Exception:
        logger.exception("Error shutting down %s", name)


async def main():
    # 1. Initialise the live-log queue immediately so userbot can emit safely.
    live_log.init()

    # 2. Initialise DB tables before either bot starts handling updates
    await db.init_db()

    # 3. Restore Ads Logs Bot subscribers from DB into the live-log module
    _raw_subs = await db.get_setting("logs_bot_subscribers", "[]")
    try:
        _sub_ids = json.loads(_raw_subs)
        live_log.load_subscribers([int(i) for i in _sub_ids])
    except Exception:
        pass

    # 4. Seed Gmail credentials into gmail_checker.
    #    Priority order:
    #      a) DB-saved value (admin changed it via Admin Panel)  ← highest
    #      b) Environment variable (hosting board config)      ← fallback
    import gmail_checker
    saved_gmail      = await db.get_setting("gmail_address",      "")
    saved_gmail_pass = await db.get_setting("gmail_app_password", "")

    gmail_checker.GMAIL_ADDRESS      = saved_gmail      or GMAIL_ADDRESS
    gmail_checker.GMAIL_APP_PASSWORD = saved_gmail_pass or GMAIL_APP_PASSWORD

    # 5. Load custom buttons and plans into the user bot's in-memory cache
    await user_bot_module.reload_custom_buttons()
    await user_bot_module.reload_plans()

    # 6. Resolve Ads Logs Bot token — DB value wins over env var
    _logs_token_db = await db.get_setting("ads_logs_bot_token", "")
    _logs_token    = _logs_token_db or ADS_LOGS_BOT_TOKEN

    # 7. Build all bot applications
    user_app  = user_bot_module.build_app()
    logs_app  = logs_bot_module.build_app(_logs_token) if _logs_token else None

    # 8. Start the User Bot.  A bad/expired optional Logs Bot token must never
    # prevent the main bot from receiving /start.
    started_apps = []
    try:
        await _start_app(
            user_app, "User Bot", ["message", "callback_query", "chat_join_request", "my_chat_member"]
        )
        started_apps.append((user_app, "User Bot"))

        # 9. Ads Logs is optional and isolated from the core bot lifecycle.
        if logs_app:
            try:
                await _start_app(logs_app, "Ads Logs Bot", ["message"])
                started_apps.append((logs_app, "Ads Logs Bot"))
                await logs_bot_module.start_consumer(logs_app)

                # Auto-save the logs bot username to the DB
                try:
                    logs_me = await logs_app.bot.get_me()
                    if logs_me.username:
                        await db.set_setting("ads_logs_bot_username", logs_me.username)
                except Exception:
                    logger.exception("Could not save Ads Logs Bot username")
            except Exception:
                logger.exception(
                    "Ads Logs Bot could not start; the User Bot will continue running"
                )
                logs_app = None

        logger.info("All core bots are online")
        await asyncio.Event().wait()
    finally:
        if logs_app:
            await logs_bot_module.stop_consumer()
        for app, name in reversed(started_apps):
            await _stop_app(app, name)


if __name__ == "__main__":
    asyncio.run(main())
''',
    'premium_emoji_runtime': r'''

"""
Runtime premium/custom-emoji helpers.

Important: Telegram does not expose the bot's owner's personal Premium status
from a bot API call. A bot cannot reliably query whether an arbitrary owner
account is currently Premium. Therefore this module supports an explicit
OWNER_PREMIUM_EMOJIS setting (environment variable) and safe fallback to
Unicode. It also provides HTML custom-emoji formatting for message text.
"""

import os
import re

OWNER_PREMIUM_EMOJIS = True

def custom_emoji_html(unicode_emoji: str, custom_id: str, fallback: str | None = None) -> str:
    if OWNER_PREMIUM_EMOJIS and custom_id:
        return f'<tg-emoji emoji-id="{custom_id}">{unicode_emoji}</tg-emoji>'
    return fallback if fallback is not None else unicode_emoji

def premium_mode() -> bool:
    return OWNER_PREMIUM_EMOJIS
