def _list_markup(st: dict, items: list) -> InlineKeyboardMarkup:
    page = st["list_page"]
    start = page * LIST_PAGE
    rows = []
    for idx in range(start, min(len(items), start + LIST_PAGE)):
        entity, mine, restricted = items[idx]
        title = _entity_title(entity)[:30]
        mark = "✅ " if idx in st["list_selected"] else ""
        icon = "👑 " if mine else ""
        lock = " 🔒" if restricted else ""
        rows.append([InlineKeyboardButton(f"{mark}{icon}{title}{lock}", callback_data=f"ppm_l:{idx}")])
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton("◀ Previous", callback_data=f"ppm_lp:{page - 1}"))
    if start + LIST_PAGE < len(items):
        nav.append(InlineKeyboardButton("Next ▶", callback_data=f"ppm_lp:{page + 1}"))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton("☑ Select All", callback_data="ppm_lall"),
                 InlineKeyboardButton("✖ Clear", callback_data="ppm_lclear")])
    rows.append([InlineKeyboardButton("🚀 Send to Selected", callback_data="ppm_lgo")])
    rows.append([InlineKeyboardButton("🔙 Back", callback_data="ppm_dest_back")])
    return InlineKeyboardMarkup(rows)


def build_premium_post_conversation(menu_provider, db):
    """Premium Post Maker conversation: text, emoji picker, placement preview,
    buttons, and sending to Chats / Groups / Channels."""

    async def ppm_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        await q.answer()
        ctx.user_data["ppm"] = _fresh()
        await q.message.reply_text(
            f"<b>Premium Post Maker</b>\n{DIVIDER}\n"
            "Send the text you want to turn into a premium post.\n\n"
            "You can use any formatting: bold, italic, spoiler, links, and more. "
            "The bot keeps your text and formatting exactly as you send it.",
            parse_mode="HTML", reply_markup=_back_kb())
        return PPM_TEXT

    async def ppm_receive_text(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        msg = update.message
        if msg is None or not msg.text:
            if msg:
                await msg.reply_text("Please send a text message.", reply_markup=_back_kb())
            return PPM_TEXT
        if _units(msg.text) > MAX_TEXT_UNITS:
            await msg.reply_text(
                f"Your text is too long. Please keep it under {MAX_TEXT_UNITS} characters.",
                reply_markup=_back_kb())
            return PPM_TEXT
        entities = [_ent_to_dict(e) for e in (msg.entities or [])]
        logger.info("Premium post text received: %d chars, entities=%s",
                    len(msg.text), [e["type"] for e in entities])
        ids = await load_emoji_ids(db)
        st = _st(ctx)
        st.update(text=msg.text, entities=entities, selected=[], page=0,
                  arr=0, picks=None, ids=ids, buttons=[])
        await msg.reply_text(_picker_text(st), parse_mode="HTML", reply_markup=_picker_markup(st))
        return PPM_PICK

    async def ppm_toggle(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        st = _st(ctx)
        idx = int(q.data.split(":")[1])
        if not 0 <= idx < len(st["ids"]):
            await q.answer()
            return PPM_PICK
        cid = st["ids"][idx]
        if cid in st["selected"]:
            st["selected"].remove(cid)
            await q.answer("Removed")
        else:
            st["selected"].append(cid)
            await q.answer("Selected ✅")
        await _refresh_picker(q, st)
        return PPM_PICK

    async def ppm_page(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        st = _st(ctx)
        st["page"] = int(q.data.split(":")[1])
        await q.answer()
        await _refresh_picker(q, st)
        return PPM_PICK

    async def ppm_pick_done(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        st = _st(ctx)
        if not st["selected"]:
            await q.answer("Please select at least one emoji.", show_alert=True)
            return PPM_PICK
        await q.answer()
        picks = await _picks(ctx.bot, st["selected"])
        if len(picks) < len(st["selected"]):
            found = {c for c, _ in picks}
            names = ", ".join(str(st["ids"].index(c) + 1) for c in st["selected"]
                              if c not in found and c in st["ids"])
            await q.message.reply_text(
                f"These emojis could not be loaded from Telegram, so they were left out: {names}.")
        st["selected"] = [c for c, _ in picks]
        if not picks:
            await _refresh_picker(q, st)
            return PPM_PICK
        st["picks"] = picks
        st["arr"] = 0
        count = _arrangement_count(len(picks))
        text, ents = _arrange(st["text"], st["entities"], picks, 0)
        await q.message.reply_text(text, entities=_ents(ents), reply_markup=_preview_markup(0, count))
        await q.message.reply_text(
            f"Placement 1 of {count}. Emojis are placed at the start and end of your message. "
            "Tap Next to see another arrangement, or Done to continue.")
        return PPM_PREVIEW

    async def ppm_arrange(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        st = _st(ctx)
        if not st.get("picks"):
            await q.answer("This session has expired. Please start again.", show_alert=True)
            return ConversationHandler.END
        count = _arrangement_count(len(st["picks"]))
        k = max(0, min(count - 1, st["arr"] + int(q.data.split(":")[1])))
        st["arr"] = k
        await q.answer()
        text, ents = _arrange(st["text"], st["entities"], st["picks"], k)
        await q.message.edit_text(text, entities=_ents(ents), reply_markup=_preview_markup(k, count))
        return PPM_PREVIEW

    async def ppm_save(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        st = _st(ctx)
        if not st.get("picks"):
            await q.answer("This session has expired. Please start again.", show_alert=True)
            return ConversationHandler.END
        await q.answer("Saved ✅")
        text, ents = _arrange(st["text"], st["entities"], st["picks"], st["arr"])
        st["final_text"], st["final_ents"] = text, ents
        ctx.user_data["ppm_final"] = {"text": text, "entities": ents,
                                      "arrangement": st["arr"], "selected": list(st["selected"])}
        await q.message.reply_text(
            f"<b>Premium post saved</b>\n{DIVIDER}\n"
            "Do you want to add buttons to this message?",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton(ADD_BUTTON_LABEL, callback_data="ppm_addbtn")],
                [InlineKeyboardButton("⏭ Skip Buttons", callback_data="ppm_skipbtn")],
                [InlineKeyboardButton("🔙 Back", callback_data="ppm_back")],
            ]))
        return PPM_ASK_BTN

    async def ppm_addbtn(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        await q.answer()
        await q.message.reply_text(
            "Enter the button name (up to 32 characters).",
            reply_markup=_back_kb())
        return PPM_BTN_NAME

    async def ppm_btn_name(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        name = (update.message.text or "").strip()
        if not name or len(name) > 32:
            await update.message.reply_text("Please send a name of 1 to 32 characters.",
                                            reply_markup=_back_kb())
            return PPM_BTN_NAME
        _st(ctx)["pending_name"] = name
        await update.message.reply_text(
            "Now enter the link for this button. You can send a channel link or any URL.",
            reply_markup=_back_kb())
        return PPM_BTN_LINK

    async def ppm_btn_link(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        st = _st(ctx)
        url = _normalise_url(update.message.text)
        if not url:
            await update.message.reply_text(
                "That does not look like a valid link. Please send a link starting with https://, "
                "or a t.me link.", reply_markup=_back_kb())
            return PPM_BTN_LINK
        buttons = st.setdefault("buttons", [])
        buttons.append({"text": st.pop("pending_name", "Button"), "url": url,
                        "style": BUTTON_STYLES[len(buttons) % 3]})
        await update.message.reply_text(
            f"<b>Button saved successfully.</b>\n{DIVIDER}\n"
            f"Buttons added: <b>{len(buttons)}</b>\n\nWhat would you like to do next?",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("➕ Add More", callback_data="ppm_addbtn")],
                [InlineKeyboardButton("✔ It's Done", callback_data="ppm_btndone")],
            ]))
        return PPM_BTN_NEXT

    async def _show_final(q_message, ctx, st):
        markup = _button_markup(st.get("buttons", []))
        sent = await q_message.reply_text(
            st["final_text"], entities=_ents(st["final_ents"]), reply_markup=markup)
        st["final_msg_id"] = sent.message_id
        st["final_chat_id"] = sent.chat_id
        await q_message.reply_text(
            f"<b>Where do you want to send this premium post?</b>\n{DIVIDER}",
            parse_mode="HTML", reply_markup=_dest_markup())
        return PPM_DEST

    async def ppm_btndone(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        await q.answer()
        return await _show_final(q.message, ctx, _st(ctx))

    async def ppm_skipbtn(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        await q.answer()
        st = _st(ctx)
        st["buttons"] = []
        return await _show_final(q.message, ctx, st)

    async def ppm_dest(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        st = _st(ctx)
        uid = q.from_user.id
        kind = q.data.split(":")[1]
        await q.answer()
        if not st.get("final_msg_id"):
            await q.message.reply_text("This session has expired. Please start again.")
            return ConversationHandler.END
        client = await _client(uid)
        if client is None:
            await q.message.reply_text(
                "Your account is not connected yet. Connect it to send this post.",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("➕ Add Account", callback_data="cb_addaccount")],
                    [InlineKeyboardButton("🔙 Back", callback_data="ppm_dest_back")],
                ]))
            return PPM_DEST
        if kind == "chats":
            # Chats: the live card appears at once and forwarding starts automatically.
            title = "Premium Post · Chats"
            card_id = await _new_card(ctx.bot, uid, title, 0)
            await _set_card_status(ctx.bot, uid, card_id, title, "Loading your chats…")

            async def notify(wait):
                await _set_card_status(ctx.bot, uid, card_id, title,
                                       f"Telegram asked us to wait {wait}s, then loading your chats")
            try:
                from_peer = await _from_peer(ctx, client)
                dialogs = await _dialogs(client, uid, notify)
                targets = [e for e, _, _ in await _collect(dialogs, "chats")]
            except Exception as ex:
                logger.exception("Chats load failed for %s", uid)
                await ctx.bot.edit_message_text(chat_id=uid, message_id=card_id,
                                                text=f"Could not load your chats: {ex}")
                return ConversationHandler.END
            if not targets:
                await ctx.bot.edit_message_text(chat_id=uid, message_id=card_id,
                                                text="No private chats were found on this account.")
                return ConversationHandler.END
            card_id = await _restart_card(ctx.bot, uid, card_id, title, len(targets))
            if not _spawn(ctx.bot, uid, card_id, client, targets, from_peer,
                          st["final_msg_id"], title, menu_provider):
                await ctx.bot.send_message(uid, "A campaign is already running. Stop it first.")
            return ConversationHandler.END
        # Groups and channels: the list opens in place of the menu, with no extra message.
        st["pick_kind"] = kind
        st["picked"] = []
        await q.message.reply_text(PICK_PROMPTS[kind], reply_markup=_picker_keyboard(kind))
        return PPM_PICKER

    async def ppm_picker_message(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        msg = update.message
        st = _st(ctx)
        kind = st.get("pick_kind", "groups")
        picked = st.setdefault("picked", [])
        shared = getattr(msg, "chat_shared", None)
        if shared is not None:
            if all(p[0] != shared.chat_id for p in picked):
                picked.append((shared.chat_id, shared.title or str(shared.chat_id)))
            await msg.reply_text(f"Added: {shared.title or shared.chat_id}. Selected: {len(picked)}. "
                                 "Add more, or tap ✅ Done.", reply_markup=_picker_keyboard(kind))
            return PPM_PICKER
        text = (msg.text or "").strip()
        if text == BTN_CANCEL:
            picked.clear()
            await msg.reply_text("Cancelled.", reply_markup=ReplyKeyboardRemove())
            return PPM_DEST
        if text == BTN_DONE:
            if not picked:
                await msg.reply_text("Select at least one first.", reply_markup=_picker_keyboard(kind))
                return PPM_PICKER
            uid = msg.from_user.id
            client = await _client(uid)
            if client is None:
                await msg.reply_text("Your account is not connected yet.", reply_markup=ReplyKeyboardRemove())
                return ConversationHandler.END
            try:
                from_peer = await _from_peer(ctx, client)
                targets = [await client.get_entity(cid) for cid, _ in picked]
            except Exception as ex:
                logger.exception("Could not open selected chats for %s", uid)
                await msg.reply_text(f"Could not open the selected chats: {ex}", reply_markup=ReplyKeyboardRemove())
                return ConversationHandler.END
            title = "Premium Post · Groups" if kind == "groups" else "Premium Post · Channels"
            card_id = await _new_card(ctx.bot, uid, title, len(targets), markup=ReplyKeyboardRemove())
            if not _spawn(ctx.bot, uid, card_id, client, targets, from_peer,
                          st["final_msg_id"], title, menu_provider):
                await ctx.bot.send_message(uid, "A campaign is already running. Stop it first.")
            picked.clear()
            return ConversationHandler.END
        await msg.reply_text("Please use the buttons below.", reply_markup=_picker_keyboard(kind))
        return PPM_PICKER

    async def _refresh_list(q, st):
        items = _LISTS.get(q.from_user.id, [])
        try:
            await q.message.edit_text(_list_text(st["list_kind"], st, len(items)),
                                      parse_mode="HTML", reply_markup=_list_markup(st, items))
        except Exception:
            pass

    async def ppm_list_toggle(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        st = _st(ctx)
        idx = int(q.data.split(":")[1])
        if idx in st["list_selected"]:
            st["list_selected"].discard(idx)
        else:
            st["list_selected"].add(idx)
        await q.answer()
        await _refresh_list(q, st)
        return PPM_LIST

    async def ppm_list_page(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        st = _st(ctx)
        st["list_page"] = int(q.data.split(":")[1])
        await q.answer()
        await _refresh_list(q, st)
        return PPM_LIST

    async def ppm_list_all(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        st = _st(ctx)
        st["list_selected"] = set(range(len(_LISTS.get(q.from_user.id, []))))
        await q.answer()
        await _refresh_list(q, st)
        return PPM_LIST

    async def ppm_list_clear(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        st = _st(ctx)
        st["list_selected"] = set()
        await q.answer()
        await _refresh_list(q, st)
        return PPM_LIST

    async def ppm_list_go(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        st = _st(ctx)
        items = _LISTS.get(q.from_user.id, [])
        chosen = [items[i][0] for i in sorted(st["list_selected"]) if i < len(items)]
        if not chosen:
            await q.answer("Please select at least one.", show_alert=True)
            return PPM_LIST
        await q.answer()
        client = await _client(q.from_user.id)
        if client is None:
            await q.message.reply_text("Your account is not connected. Please connect it first.")
            return ConversationHandler.END
        title = "Premium Post · Groups" if st["list_kind"] == "groups" else "Premium Post · Channels"
        try:
            from_peer = await _from_peer(ctx, client)
        except Exception as ex:
            logger.exception("Could not resolve bot peer")
            await q.message.reply_text(f"Could not reach the bot from your account: {ex}")
            return ConversationHandler.END
        card_id = await _new_card(ctx.bot, q.from_user.id, title, len(chosen))
        ok = _spawn(ctx.bot, q.from_user.id, card_id, client, chosen, from_peer,
                    st["final_msg_id"], title, menu_provider)
        if not ok:
            await ctx.bot.send_message(q.from_user.id, "A campaign is already running. Stop it first.")
        _LISTS.pop(q.from_user.id, None)
        return ConversationHandler.END if ok else PPM_LIST

    async def ppm_dest_back(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        await q.answer()
        await q.message.edit_text(
            f"<b>Where do you want to send this premium post?</b>\n{DIVIDER}",
            parse_mode="HTML", reply_markup=_dest_markup())
        return PPM_DEST

    async def ppm_back(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        await q.answer()
        ctx.user_data.pop("ppm", None)
        await q.message.reply_text(_menu_text(), reply_markup=await menu_provider())
        return ConversationHandler.END

    async def ppm_cancel(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        ctx.user_data.pop("ppm", None)
        await update.message.reply_text("Premium Post Maker cancelled.",
                                        reply_markup=await menu_provider())
        return ConversationHandler.END

    return ConversationHandler(
        entry_points=[CallbackQueryHandler(ppm_start, pattern="^cb_premium_post$")],
        states={
            PPM_TEXT: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, ppm_receive_text),
                CallbackQueryHandler(ppm_back, pattern="^ppm_back$"),
            ],
            PPM_PICK: [
                CallbackQueryHandler(ppm_toggle, pattern=r"^ppm_t:\d+$"),
                CallbackQueryHandler(ppm_page, pattern=r"^ppm_p:\d+$"),
                CallbackQueryHandler(ppm_pick_done, pattern="^ppm_done$"),
                CallbackQueryHandler(ppm_back, pattern="^ppm_back$"),
            ],
            PPM_PREVIEW: [
                CallbackQueryHandler(ppm_arrange, pattern=r"^ppm_arr:-?\d+$"),
                CallbackQueryHandler(ppm_save, pattern="^ppm_save$"),
                CallbackQueryHandler(ppm_back, pattern="^ppm_back$"),
            ],
            PPM_ASK_BTN: [
                CallbackQueryHandler(ppm_addbtn, pattern="^ppm_addbtn$"),
                CallbackQueryHandler(ppm_skipbtn, pattern="^ppm_skipbtn$"),
                CallbackQueryHandler(ppm_back, pattern="^ppm_back$"),
            ],
            PPM_BTN_NAME: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, ppm_btn_name),
                CallbackQueryHandler(ppm_back, pattern="^ppm_back$"),
            ],
            PPM_BTN_LINK: [
                MessageHandler(filters.TEXT & ~filters.COMMAND, ppm_btn_link),
                CallbackQueryHandler(ppm_back, pattern="^ppm_back$"),
            ],
            PPM_BTN_NEXT: [
                CallbackQueryHandler(ppm_addbtn, pattern="^ppm_addbtn$"),
                CallbackQueryHandler(ppm_btndone, pattern="^ppm_btndone$"),
                CallbackQueryHandler(ppm_back, pattern="^ppm_back$"),
            ],
            PPM_DEST: [
                CallbackQueryHandler(ppm_dest, pattern=r"^ppm_dest:(chats|groups|channels)$"),
                CallbackQueryHandler(ppm_dest_back, pattern="^ppm_dest_back$"),
                CallbackQueryHandler(ppm_back, pattern="^ppm_back$"),
            ],
            PPM_PICKER: [
                MessageHandler(filters.ALL & ~filters.COMMAND, ppm_picker_message),
                CallbackQueryHandler(ppm_back, pattern="^ppm_back$"),
            ],
            PPM_LIST: [
                CallbackQueryHandler(ppm_list_toggle, pattern=r"^ppm_l:\d+$"),
                CallbackQueryHandler(ppm_list_page, pattern=r"^ppm_lp:\d+$"),
                CallbackQueryHandler(ppm_list_all, pattern="^ppm_lall$"),
                CallbackQueryHandler(ppm_list_clear, pattern="^ppm_lclear$"),
                CallbackQueryHandler(ppm_list_go, pattern="^ppm_lgo$"),
                CallbackQueryHandler(ppm_dest_back, pattern="^ppm_dest_back$"),
                CallbackQueryHandler(ppm_back, pattern="^ppm_back$"),
            ],
        },
        fallbacks=[CommandHandler("cancel", ppm_cancel)],
        allow_reentry=True,
        per_message=False,
    )


def build_premium_post_stop_handler():
    """Global Stop button for the running premium post campaign."""

    async def ppm_stop(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
        q = update.callback_query
        run = _RUNS.get(q.from_user.id)
        if run and not run["task"].done():
            await q.answer("Stopping campaign…")
            run["task"].cancel()
        else:
            await q.answer("No campaign is running.", show_alert=True)

    return CallbackQueryHandler(ppm_stop, pattern="^ppm_stop$")
