_EMOJI_MARKER_RE = re.compile(r"emoji_(\d+)")


def _emoji_fallback(emoji_id: str) -> str:
    """Return a real Unicode fallback for a legacy custom-emoji ID.

    The project historically stored custom emoji IDs as ``emoji_<id>`` text.
    Sending those IDs as Telegram HTML entities can fail with
    ``Entity_text_invalid`` when the bot does not have access to that custom
    emoji.  A normal Unicode glyph is always valid, so the user-facing bot
    deliberately uses Unicode fallbacks at the transport boundary.
    """
    fallback = {
        DONE_CUSTOM_EMOJI_ID: "✅",
        GIFT_CUSTOM_EMOJI_ID: "🎁",
        JD_CUSTOM_EMOJI_ID: "📣",
        CAMPAIGN_CUSTOM_EMOJI_ID: "🚀",
        SETADS_CUSTOM_EMOJI_ID: "📢",
        VIP_CUSTOM_EMOJI_ID: "💎",
        CANCEL_CUSTOM_EMOJI_ID: "❌",
        HOWTO_CUSTOM_EMOJI_ID: "❓",
        AUTOVERIFY_CUSTOM_EMOJI_ID: "🔐",
        CHANNELS_JOINED_CUSTOM_EMOJI_ID: "✅",
        CYOB_CUSTOM_EMOJI_ID: "🤖",
        ADDACC_CUSTOM_EMOJI_ID: "➕",
        REMOVEACC_CUSTOM_EMOJI_ID: "🗑️",
        REFER_CUSTOM_EMOJI_ID: "🔗",
        SETMSG_CUSTOM_EMOJI_ID: "💬",
        PREVIEW_CUSTOM_EMOJI_ID: "🖼️",
        PREVIEW_SAVED_CUSTOM_EMOJI_ID: "🖼️",
        MYACCOUNT_CUSTOM_EMOJI_ID: "📱",
        ACCEPT_PENDING_CUSTOM_EMOJI_ID: "📥",
        CHANNEL_PROMO_CUSTOM_EMOJI_ID: "📣",
        ADS_LOGS_CUSTOM_EMOJI_ID: "📊",
        MY_STATS_CUSTOM_EMOJI_ID: "📊",
        SETAUTOREPLY_CUSTOM_EMOJI_ID: "💬",
    }
    return fallback.get(str(emoji_id), "🔘")


def _replace_custom_emoji_markers(text: str) -> str:
    """Convert every legacy/custom-emoji marker to safe Unicode text.

    This intentionally does *not* emit ``<tg-emoji>`` HTML.  That markup is
    only safe when the exact custom emoji is available to the sending bot;
    otherwise Telegram rejects the whole message with ``Entity_text_invalid``.
    """
    if not isinstance(text, str):
        return text

    def _tag(match):
        return _emoji_fallback(match.group(1))

    # Clean existing tg-emoji HTML first.
    text = re.sub(
        r'<tg-emoji\s+emoji-id=["\'](\d+)["\']>.*?</tg-emoji>',
        _tag,
        text,
        flags=re.DOTALL | re.IGNORECASE,
    )
    # Then replace the legacy plain markers.
    return _EMOJI_MARKER_RE.sub(lambda m: _emoji_fallback(m.group(1)), text)


def _markdown_v1_to_html(text: str) -> str:
    """Conservative Markdown-v1 to HTML conversion used only when V23 needs
    custom emoji entities in a Markdown message.  It intentionally handles the
    constructs used throughout this bot: bold, italic, code and inline links.
    """
    escaped = html.escape(str(text), quote=False)
    escaped = re.sub(r'\[([^\]]+)\]\((https?://[^)]+)\)', r'<a href="\2">\1</a>', escaped)
    escaped = re.sub(r'`([^`\n]+)`', r'<code>\1</code>', escaped)
    escaped = re.sub(r'\*\*([^*\n]+)\*\*', r'<b>\1</b>', escaped)
    escaped = re.sub(r'\*([^*\n]+)\*', r'<b>\1</b>', escaped)
    escaped = re.sub(r'(?<!\w)_([^_\n]+)_(?!\w)', r'<i>\1</i>', escaped)
    return escaped


def _replace_v22_unicode_with_html(text: str) -> tuple[str, bool]:
    if not isinstance(text, str):
        return text, False
    changed = False
    # Longest first prevents partial matches for variation-selector emoji.
    items = sorted(V22_MESSAGE_EMOJI.items(), key=lambda kv: len(kv[0]), reverse=True)
    for glyph, (emoji_id, fallback) in items:
        tag = f'<tg-emoji emoji-id="{html.escape(str(emoji_id), quote=True)}">{html.escape(fallback)}</tg-emoji>'
        if glyph in text:
            text = text.replace(glyph, tag)
            changed = True
    return text, changed


def render_custom_emoji_message(text: str, parse_mode: Optional[str] = None) -> Tuple[str, Optional[str]]:
    """V23 transport layer.

    - Legacy ``emoji_<id>`` markers are always converted to safe Unicode.
    - When custom emoji mode is enabled *and* the owner has explicitly enabled
      OWNER_PREMIUM_EMOJIS, supplied V22 Unicode glyphs are converted to their
      exact custom IDs. Otherwise the original Unicode glyphs remain intact.
    - Markdown-v1 messages containing mapped glyphs are conservatively converted
      to HTML so Telegram can legally carry ``<tg-emoji>`` entities.
    """
    if not isinstance(text, str):
        return text, parse_mode

    # Legacy markers first; this is always safe.
    cleaned = _replace_custom_emoji_markers(text)

    if not USER_USE_CUSTOM_EMOJI:
        return cleaned, parse_mode

    # Do not risk invalid custom emoji entities when the owner has not enabled
    # Premium custom-emoji delivery. Unicode remains the guaranteed fallback.
    mode = str(parse_mode or '').upper()
    if mode == 'MARKDOWNV2':
        # MarkdownV2 conversion is intentionally left untouched; Unicode is
        # safer than corrupting escaping/entity offsets.
        return cleaned, parse_mode

    if mode == 'MARKDOWN':
        cleaned = _markdown_v1_to_html(cleaned)
        rendered, changed = _replace_v22_unicode_with_html(cleaned)
        return rendered, ('HTML' if changed else parse_mode)

    if mode in ('HTML', ''):
        rendered, changed = _replace_v22_unicode_with_html(cleaned)
        return rendered, ('HTML' if changed else parse_mode)

    return cleaned, parse_mode


# ── Generic builder ───────────────────────────────────────────────────────────

def _strip_leading_unicode_emoji(text: str) -> str:
    """Remove regular emoji prefixes from a custom-emoji button label.

    Telegram renders ``icon_custom_emoji_id`` separately from the label.  The
    old labels included a Unicode emoji as well, which produced two icons in
    the same button.  Keep the label text, but remove one or more leading
    Unicode emoji characters and their variation/joiner modifiers.
    """
    # Numeric custom-emoji markers are implementation details, never button
    # labels.  The real icon is supplied separately through icon_custom_emoji_id.
    value = _EMOJI_MARKER_RE.sub("", text).lstrip()
    while value:
        first = value[0]
        codepoint = ord(first)
        is_emoji = (
            0x1F000 <= codepoint <= 0x1FAFF
            or 0x2300 <= codepoint <= 0x23FF
            or 0x2600 <= codepoint <= 0x27BF
            or 0x2B00 <= codepoint <= 0x2BFF
            or 0x3030 <= codepoint <= 0x303F
            or 0xFE0F == codepoint
        )
        if not is_emoji:
            break
        value = value[1:].lstrip()
        while value and ord(value[0]) in (0xFE0F, 0x200D, 0x20E3):
            value = value[1:].lstrip()
    return value


def _make_button(text: str, emoji_id: str, fallback: str, **kwargs) -> InlineKeyboardButton:
    """Build a styled inline button using Telegram's current button styles.

    Green (success) is used for actions/confirmations; blue (primary) is used
    for navigation, information and neutral actions.  The project intentionally
    avoids red so the user-facing UI stays within the requested green/blue palette.
    """
    clean_text = _strip_leading_unicode_emoji(text) or "Button"
    button_kwargs = dict(kwargs)
    if "style" not in button_kwargs:
        label = clean_text.casefold()
        if label == "task":
            button_kwargs["style"] = "primary"
        if any(word in label for word in (
            "back", "cancel", "preview", "stats", "support", "terms",
            "how to", "account", "logs", "history", "choose", "menu",
            "create your own bot", "talk to admin", "auto bot", "my account",
        )):
            button_kwargs["style"] = "primary"
        else:
            button_kwargs["style"] = "success"
    if USER_USE_CUSTOM_EMOJI:
        button_kwargs.setdefault("icon_custom_emoji_id", str(emoji_id))
        try:
            return InlineKeyboardButton(clean_text, **button_kwargs)
        except TypeError as exc:
            if "icon_custom_emoji_id" not in str(exc):
                raise
            button_kwargs.pop("icon_custom_emoji_id", None)
    safe_fallback = _emoji_fallback(str(fallback).replace("emoji_", "")) if str(fallback).startswith("emoji_") else str(fallback)
    if not USER_USE_CUSTOM_EMOJI:
        clean_text = f"{safe_fallback} {clean_text}"
    return InlineKeyboardButton(clean_text, **button_kwargs)


def user_button(text: str, **kwargs) -> InlineKeyboardButton:
    """Generic User Bot button with V22 custom emoji mapping and safe Unicode fallback."""
    raw = str(text or "")
    clean = _strip_leading_unicode_emoji(raw).strip()
    # Task has a fixed owner-supplied custom emoji and blue primary style.
    if clean.casefold() == "task":
        kwargs.setdefault("style", "primary")
        return _make_button(clean, V22_EMOJI_IDS["Task"], V22_EMOJI_FALLBACKS["Task"], **kwargs)
    # Exact/contained V22 labels take priority over legacy generic mappings.
    for label, eid in V22_EMOJI_IDS.items():
        if clean.casefold() == label.casefold() or clean.casefold().startswith(label.casefold() + " "):
            return _make_button(clean, eid, V22_EMOJI_FALLBACKS.get(label, "📌"), **kwargs)
    """Generic User Bot button with automatic custom emoji + green/blue style."""
    value = _strip_leading_unicode_emoji(text).casefold()
    if "start" in value and "campaign" in value:
        emoji_id, fallback = CAMPAIGN_CUSTOM_EMOJI_ID, CAMPAIGN_CUSTOM_EMOJI_FALLBACK
