def custom_emoji_html(unicode_emoji: str, custom_id: str | None = None, fallback: str | None = None) -> str:
    """Backward-compatible custom emoji formatter.

    Older modules call this helper with only the Unicode emoji.  Newer code
    may provide a Telegram custom-emoji ID.  Keep the fallback safe when no
    custom ID is supplied or when animated emoji mode is not configured.
    """
    if custom_id:
        return f'<tg-emoji emoji-id="{html.escape(str(custom_id), quote=True)}">{html.escape(unicode_emoji)}</tg-emoji>'
    return fallback if fallback is not None else unicode_emoji


def custom_message_html(markdown_text: str, emoji_html: str) -> str:
    """Convert common bot Markdown to HTML and prepend a chosen custom emoji."""
    text = html.escape(markdown_text, quote=False)
    text = re.sub(r"\*([^*\n]+)\*", r"<b>\1</b>", text)
    text = re.sub(r"_([^_\n]+)_", r"<i>\1</i>", text)
    text = re.sub(r"`([^`\n]+)`", r"<code>\1</code>", text)
    text = _replace_known_emoji_with_custom_entities(text)
    return f"{emoji_html} {text}"


