def done_message_html(text: str) -> str:
    """Render legacy Markdown-style status text safely as Telegram HTML.

    Older bot screens pass strings using *bold* markers while newer screens
    send the result with parse_mode=HTML.  Keep this helper permissive so
    those legacy screens do not crash at import/runtime.
    """
    value = str(text or "")
    # Do not escape Telegram custom-emoji placeholders such as emoji_123...;
    # they are plain text here and are intentionally left untouched.
    value = html.escape(value, quote=False)
    # Convert the common legacy Markdown emphasis used by existing screens.
    value = re.sub(r"\*(?=\S)(.*?\S)\*", r"<b>\1</b>", value)
    value = re.sub(r"`([^`]+)`", r"<code>\1</code>", value)
    return value

